//! Legacy Boa JavaScript engine seam: the only module allowed to import
//! `boa_engine` in the explicit Boa backend. A showstopper means fixing the
//! vendored fork, never swapping. Owns the page context, the `__dom_*`/`__http_*`
//! integer-syscall boundary over the Rust arena, the PRELUDE (the web platform,
//! self-hosted in JS on those syscalls), the compiled-code caches (prelude
//! image + cross-page CDN image), parallel/lazy parse, and the living-page
//! actor that keeps a displayed page's engine + DOM resident for dispatches.

use std::cell::{Cell, RefCell};
use std::collections::VecDeque;
use std::rc::Rc;
use std::time::{Duration, Instant};

use boa_engine::job::{Job, JobExecutor, NativeAsyncJob, PromiseJob};
use boa_engine::object::builtins::{JsArray, JsPromise};
use boa_engine::{Context, JsResult, JsString, JsValue, NativeFunction, Source};

use crate::dom::{AdoptError, DOCUMENT, Dom, SelectorList};

/// A generous wall window for tests that explicitly exercise deadline
/// behavior. Normal browsing does not arm a deadline: HTML's event-loop
/// processing model runs the selected task to completion, while navigation and
/// document teardown use the engine's independent host-interrupt controls.
#[cfg(test)]
const TEST_BUDGET: Duration = Duration::from_secs(60);

/// Cumulative *execution* time a page's scripts get before we stop
/// launching more. Measures compute, not wall clock (the wire is async
/// and free), so a slow server can't starve a fast page of its scripts.
// YouTube's current 10.7 MiB application bundle is a useful upper-bound
// canary: on the supported aarch64 desktop it needs about 40 s of JS CPU, then
// less than a second of parser-ordered bootstrap scripts to bind the supplied
// renderer data. A 30 s launch gate let the one already-running script finish
// but then skipped that entire ordered tail and DOMContentLoaded, producing a
// permanently empty application shell. Give standards-mandated script
// execution enough cumulative CPU to finish.
pub const COMPUTE_BUDGET: Duration = Duration::from_secs(50);

/// Diagnostic-only extension for exceptionally large applications. The normal
/// page limit remains [`COMPUTE_BUDGET`]; a manual diagnostic may set
/// `TRUST_DIAG_COMPUTE_SECS` to let a heavy page finish booting. Read once
/// because this is consulted at every script boundary.
fn compute_budget() -> Duration {
    static BUDGET: std::sync::OnceLock<Duration> = std::sync::OnceLock::new();
    *BUDGET.get_or_init(|| {
        let secs = std::env::var("TRUST_DIAG_COMPUTE_SECS")
            .ok()
            .and_then(|s| s.parse::<u64>().ok())
            .unwrap_or(COMPUTE_BUDGET.as_secs())
            .max(1);
        Duration::from_secs(secs)
    })
}

/// Most loop iterations any single script evaluation may run. Real-world
/// bundle boots measured in the canary use a few hundred thousand at
/// most; ten million leaves headroom while still catching `while(true)`
/// in well under a second.
const LOOP_LIMIT: u64 = 10_000_000;
/// Max JS function-call recursion depth (Boa default is 512). Reactive signal
/// graphs (YouTube kevlar) nest call frames deep; browsers allow thousands.
/// Frames are heap-allocated VM CallFrames for JS↔JS recursion, so this is
/// cheap and stays well within the trust-js thread's 64MB stack.
const RECURSION_LIMIT: usize = 4000;
/// Max VM operand-stack slots (Boa default 10240). The operand stack grows
/// with call depth (args/locals per frame), so it must scale with
/// RECURSION_LIMIT or a deep-but-finite recursion trips "exceeded maximum call
/// stack length" before completing. Also a heap Vec, so generous is cheap.
const STACK_SIZE_LIMIT: usize = 64 * 1024;

/// GC policy for the (vendored) boa_gc mark-sweep collector. Boa's stock
/// policy — a 1 MiB floor grown only ~1.43× per collection — thrashes
/// full stop-the-world marks on real bundles: it takes ~19 ever-larger
/// collections to chase a heavy page's growing live set up to steady state
/// (measured on YouTube's 10.5 MiB base: >50% of *execution* time in the
/// GC). The collector is non-generational, so every collection is a full
/// mark over the whole live set — making frequent collection of a large
/// live set the worst case.
///
/// Our policy keeps the floor LOW and the budget tight while the live set is
/// small (so a small live set still gets cheap, cache-friendly frequent
/// collection — a high threshold measurably *regresses* moderate sites like
/// react.dev by ~20%, blowing the cache with accumulated garbage and
/// inflating ALL execution, not just GC), and only lets the budget run loose
/// ([`GC_BIG_GROWTH_PERCENT`]) once the live set exceeds [`GC_BIG_LIVE`] —
/// past cache, where marking is out-of-cache regardless so the only win left
/// is doing fewer (expensive) full marks. `TRUST_GC_FLOOR` (MiB),
/// `TRUST_GC_GROWTH`/`TRUST_GC_BIG_GROWTH` (percent), `TRUST_GC_BIG_LIVE`
/// (MiB) override for tuning. See `js::tests::{engine_profile,gc_floor_win}`.
const GC_FLOOR: usize = 1024 * 1024;
// Below GC_BIG_LIVE the policy matches Boa's stock ~1.43x growth, so moderate
// pages (react.dev's live set is ~4 MiB) behave exactly as before — they have
// nothing to gain from GC tuning anyway (their collections are already cheap).
// The win is reserved for large-live-set heavy pages, which thrash under stock.
const GC_GROWTH_PERCENT: usize = 143;
const GC_BIG_LIVE: usize = 16 * 1024 * 1024;
const GC_BIG_GROWTH_PERCENT: usize = 400;

/// Apply the GC policy to the current thread's collector, honoring the
/// `TRUST_GC_*` overrides.
fn apply_gc_policy() {
    let mib = |name: &str, default: usize| -> usize {
        std::env::var(name)
            .ok()
            .and_then(|s| s.parse::<usize>().ok())
            .map(|m| m.saturating_mul(1024 * 1024).max(1))
            .unwrap_or(default)
    };
    let pct = |name: &str, default: usize| -> usize {
        std::env::var(name)
            .ok()
            .and_then(|s| s.parse::<usize>().ok())
            .unwrap_or(default)
    };
    boa_engine::gc::set_gc_threshold(mib("TRUST_GC_FLOOR", GC_FLOOR));
    boa_engine::gc::set_gc_growth_percent(pct("TRUST_GC_GROWTH", GC_GROWTH_PERCENT));
    boa_engine::gc::set_gc_big_growth(
        mib("TRUST_GC_BIG_LIVE", GC_BIG_LIVE),
        pct("TRUST_GC_BIG_GROWTH", GC_BIG_GROWTH_PERCENT),
    );
}

/// GC permanent generation (default on; `TRUST_NO_GC_PERMGEN` disables). After
/// the immortal platform graph (realm intrinsics + our JS prelude) is built,
/// `retenure_permanent` tenures it so it stops being re-ref-counted in the
/// `trace_non_roots` pass of every later collection during the page's life —
/// a ~2x cut to that phase on allocation-heavy pages (the phase is ~28% of GC
/// time). The first no-write-barrier
/// brick of the generational GC track. Safe by construction: tenuring only
/// ever *retains* (it can never free a live object), and the retenure is
/// self-cleaning across navigations on the reused page thread.
fn gc_permgen_on() -> bool {
    static ENABLED: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ENABLED.get_or_init(|| std::env::var_os("TRUST_NO_GC_PERMGEN").is_none())
}

/// Host interruption state shared by every script on the page.
///
/// Ordinary browsing is unbounded in wall time. A deadline is armed only by an
/// explicit bounded operation (currently user-event dispatch and tests), while
/// navigation/cancellation remain independently observable by the engine.
pub struct Budget {
    deadline: std::cell::Cell<Option<Instant>>,
    interrupt: std::sync::Arc<boa_engine::vm::RuntimeInterrupt>,
}

impl Budget {
    pub fn unbounded() -> Self {
        Self::with_interrupt(std::sync::Arc::new(
            boa_engine::vm::RuntimeInterrupt::default(),
        ))
    }

    /// Construct an explicitly deadline-bound budget. Production page and
    /// worker realms use [`Self::unbounded`]; this path remains useful for
    /// focused host-interrupt tests and deliberately bounded diagnostics.
    pub fn new(wall: Duration) -> Self {
        let budget = Self::unbounded();
        budget.rearm(wall);
        budget
    }

    fn with_interrupt(interrupt: std::sync::Arc<boa_engine::vm::RuntimeInterrupt>) -> Self {
        interrupt.set_deadline(None);
        Self {
            deadline: std::cell::Cell::new(None),
            interrupt,
        }
    }

    fn install(&self, ctx: &mut Context) {
        ctx.set_runtime_interrupt(Some(self.interrupt.clone()));
    }

    pub fn exhausted(&self) -> bool {
        self.interrupt.user_navigation_requested()
            || self
                .deadline
                .get()
                .is_some_and(|deadline| Instant::now() >= deadline)
    }

    /// Time left until an explicitly armed deadline. `None` is the normal
    /// browsing state and lets an async job driver wait for its task to finish.
    pub fn remaining(&self) -> Option<Duration> {
        if self.interrupt.user_navigation_requested() {
            return Some(Duration::ZERO);
        }
        self.deadline
            .get()
            .map(|deadline| deadline.saturating_duration_since(Instant::now()))
    }

    /// Arm an explicit deadline. Production browsing leaves this unset; this
    /// is retained for focused interruption/resource-limit tests.
    pub fn rearm(&self, wall: Duration) {
        let deadline = Instant::now() + wall;
        self.deadline.set(Some(deadline));
        self.interrupt.set_deadline(Some(deadline));
    }

    /// Clear any task-local deadline without disturbing navigation or teardown
    /// interrupts. Ordinary HTML tasks enter through this path.
    pub fn clear_deadline(&self) {
        self.deadline.set(None);
        self.interrupt.set_deadline(None);
    }

    /// Admit the next queued user-interaction task after a pending navigation
    /// request has made background JavaScript unwind.
    fn begin_user_interaction(&self) {
        self.interrupt.begin_user_interaction();
    }
}

/// What a page's scripts did, for the status bar (`· JS:n!`) and
/// `app.notice`: per-script failures are collected, never fatal — a
/// broken script renders a partial page, not a blank one.
#[derive(Default, Clone)]
pub struct Outcome {
    pub errors: Vec<String>,
    pub elapsed: Duration,
    /// `type="module"` scripts that could not run (an entry whose URL didn't
    /// resolve / whose body never arrived). Modules otherwise execute for real.
    pub modules_skipped: usize,
    /// A script tripped an engine bug; remaining page JS was abandoned.
    pub panicked: bool,
    /// Page-initiated network requests (fetch/XHR) performed.
    pub fetches: usize,
    /// Captured console.* output, for tests and debugging.
    pub console: Vec<String>,
    /// Typed presentation payload for a render event. Kept in the existing
    /// event envelope so the public event shape and its extensive actor tests
    /// remain stable while frontends stop consuming `html`.
    pub(crate) rendered: Option<Box<crate::http::RenderedPage>>,
}

impl std::fmt::Debug for Outcome {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("Outcome")
            .field("errors", &self.errors)
            .field("elapsed", &self.elapsed)
            .field("modules_skipped", &self.modules_skipped)
            .field("panicked", &self.panicked)
            .field("fetches", &self.fetches)
            .field("console", &self.console)
            .field("rendered", &self.rendered.is_some())
            .finish()
    }
}

impl Outcome {
    /// The headline failure for `app.notice`, if anything went wrong.
    /// (Test/diagnostic surface — the app currently formats its own notice.)
    #[cfg_attr(not(test), allow(dead_code))]
    pub fn notice(&self) -> Option<String> {
        let first = self.errors.first()?;
        match self.errors.len() {
            1 => Some(format!("JS: {first}")),
            n => Some(format!("JS: {first} (+{} more)", n - 1)),
        }
    }
}

/// Boa's job executor for a page. It is the bundled `SimpleJobExecutor`
/// with one decisive change: it **parks** on in-flight async jobs
/// (`group.next().await`) instead of busy-polling them. That is what lets
/// page fetches overlap — they all sit in one `FuturesUnordered`, polled
/// concurrently and driven by the tokio reactor, while the JS thread
/// sleeps until one completes. (The stock executor spins a core the whole
/// time a request is outstanding; we cannot ship that.) Timers are
/// virtual (driven by `__trust.tick`, not Boa's clock), so `TimeoutJob`s
/// never actually arise here, but we run any stray non-promise job rather
/// than drop it.
#[derive(Default)]
struct PageJobExecutor {
    promise_jobs: RefCell<VecDeque<PromiseJob>>,
    async_jobs: RefCell<VecDeque<NativeAsyncJob>>,
    /// Dynamically prepared classic scripts are their own HTML resource
    /// tasks. Keep them separate from author `fetch()` jobs: the document's
    /// `load` event waits for a prepared script's result, but not for an
    /// arbitrary page fetch started by DOMContentLoaded.
    script_jobs: RefCell<VecDeque<NativeAsyncJob>>,
    /// Module-script fetches are later HTML tasks. Keep them out of the
    /// parser's ordinary host-job checkpoint so a resident page can paint its
    /// shell while a code-split component graph downloads. Once the actor is
    /// servicing host work normally, these join the same async group.
    deferred_module_jobs: RefCell<VecDeque<NativeAsyncJob>>,
    other_jobs: RefCell<VecDeque<Job>>,
}

impl PageJobExecutor {
    fn clear(&self) {
        self.promise_jobs.borrow_mut().clear();
        self.async_jobs.borrow_mut().clear();
        self.script_jobs.borrow_mut().clear();
        self.deferred_module_jobs.borrow_mut().clear();
        self.other_jobs.borrow_mut().clear();
    }

    /// Whether a later host task is waiting to be serviced. The live page
    /// actor uses this to wake after the parser returns without draining an
    /// asynchronously inserted module's whole network graph in the parser
    /// task itself.
    fn has_pending_jobs(&self) -> bool {
        !self.promise_jobs.borrow().is_empty()
            || !self.async_jobs.borrow().is_empty()
            || !self.script_jobs.borrow().is_empty()
            || !self.deferred_module_jobs.borrow().is_empty()
            || !self.other_jobs.borrow().is_empty()
    }

    fn has_load_blockers(&self) -> bool {
        !self.script_jobs.borrow().is_empty() || !self.deferred_module_jobs.borrow().is_empty()
    }

    fn enqueue_script(&self, job: NativeAsyncJob) {
        self.script_jobs.borrow_mut().push_back(job);
    }

    fn enqueue_deferred_module(&self, job: NativeAsyncJob) {
        self.deferred_module_jobs.borrow_mut().push_back(job);
    }

    /// Perform the HTML microtask checkpoint that is part of cleaning up after
    /// a classic script, without advancing any later host work. Page
    /// microtasks (`Promise` reactions, `queueMicrotask`, MutationObserver
    /// delivery) all ride Boa's `PromiseJob` queue. `NativeAsyncJob`s are the
    /// separate host work behind fetches and dynamically prepared resources;
    /// polling those here would incorrectly keep `document.currentScript`
    /// active across a later network/resource task.
    fn run_microtask_checkpoint(&self, ctx: &mut Context) -> JsResult<()> {
        loop {
            let jobs = std::mem::take(&mut *self.promise_jobs.borrow_mut());
            if jobs.is_empty() {
                ctx.clear_kept_objects();
                return Ok(());
            }
            let exec_t = phase_begin();
            for job in jobs {
                if let Err(err) = job.call(ctx) {
                    phase_end(Phase::Execute, exec_t);
                    self.clear();
                    return Err(err);
                }
            }
            phase_end(Phase::Execute, exec_t);
        }
    }
    async fn run_jobs_async_mode(
        self: Rc<Self>,
        context: &RefCell<&mut Context>,
        include_deferred_modules: bool,
    ) -> JsResult<()> {
        use futures::stream::StreamExt as _;
        let mut group = futures::stream::FuturesUnordered::new();
        loop {
            for job in std::mem::take(&mut *self.script_jobs.borrow_mut()) {
                group.push(job.call(context));
            }
            for job in std::mem::take(&mut *self.async_jobs.borrow_mut()) {
                group.push(job.call(context));
            }
            if include_deferred_modules {
                for job in std::mem::take(&mut *self.deferred_module_jobs.borrow_mut()) {
                    group.push(job.call(context));
                }
            }
            let exec_t = phase_begin();
            let promise = std::mem::take(&mut *self.promise_jobs.borrow_mut());
            let other = std::mem::take(&mut *self.other_jobs.borrow_mut());
            let ran_sync = !promise.is_empty() || !other.is_empty();
            for job in promise {
                if let Err(err) = job.call(&mut context.borrow_mut()) {
                    self.clear();
                    return Err(err);
                }
            }
            for job in other {
                let r = match job {
                    Job::TimeoutJob(t) => t.call(&mut context.borrow_mut()),
                    Job::GenericJob(g) => g.call(&mut context.borrow_mut()),
                    Job::PromiseJob(p) => p.call(&mut context.borrow_mut()),
                    Job::AsyncJob(a) => {
                        group.push(a.call(context));
                        Ok(JsValue::undefined())
                    }
                    _ => Ok(JsValue::undefined()),
                };
                if let Err(err) = r {
                    self.clear();
                    return Err(err);
                }
            }
            phase_end(Phase::Execute, exec_t);
            let script_empty = self.script_jobs.borrow().is_empty();
            let deferred_empty =
                !include_deferred_modules || self.deferred_module_jobs.borrow().is_empty();
            if self.async_jobs.borrow().is_empty()
                && script_empty
                && deferred_empty
                && !ran_sync
                && group.is_empty()
            {
                break;
            }
            if ran_sync
                || !self.async_jobs.borrow().is_empty()
                || !script_empty
                || (include_deferred_modules && !self.deferred_module_jobs.borrow().is_empty())
            {
                continue;
            }
            phase(&format!("job park ({} in flight)", group.len()));
            if let Some(Err(err)) = group.next().await {
                self.clear();
                return Err(err);
            }
            phase(&format!("job wake ({} left)", group.len()));
            context.borrow_mut().clear_kept_objects();
        }
        Ok(())
    }

    /// Run only the resource tasks that can delay the document's `load`
    /// event. Author `fetch()` jobs stay parked in `async_jobs`, because the
    /// HTML event loop does not make an arbitrary Fetch promise a load-event
    /// blocker. Dynamic classic scripts live in `script_jobs`; dynamic module
    /// entry fetches live in `deferred_module_jobs` and their evaluation/load
    /// reactions arrive through `promise_jobs`.
    async fn run_load_blocking_jobs(
        self: Rc<Self>,
        context: &RefCell<&mut Context>,
    ) -> JsResult<()> {
        use futures::stream::StreamExt as _;
        let mut group = futures::stream::FuturesUnordered::new();
        loop {
            for job in std::mem::take(&mut *self.script_jobs.borrow_mut()) {
                group.push(job.call(context));
            }
            for job in std::mem::take(&mut *self.deferred_module_jobs.borrow_mut()) {
                group.push(job.call(context));
            }

            let exec_t = phase_begin();
            let promise = std::mem::take(&mut *self.promise_jobs.borrow_mut());
            let other = std::mem::take(&mut *self.other_jobs.borrow_mut());
            let ran_sync = !promise.is_empty() || !other.is_empty();
            for job in promise {
                if let Err(err) = job.call(&mut context.borrow_mut()) {
                    self.clear();
                    return Err(err);
                }
            }
            for job in other {
                let r = match job {
                    Job::TimeoutJob(t) => t.call(&mut context.borrow_mut()),
                    Job::GenericJob(g) => g.call(&mut context.borrow_mut()),
                    Job::PromiseJob(p) => p.call(&mut context.borrow_mut()),
                    // A resource callback may start an ordinary page fetch.
                    // It belongs to the later networking task lane and must
                    // not turn that fetch into a load-event blocker.
                    Job::AsyncJob(a) => {
                        self.async_jobs.borrow_mut().push_back(a);
                        Ok(JsValue::undefined())
                    }
                    _ => Ok(JsValue::undefined()),
                };
                if let Err(err) = r {
                    self.clear();
                    return Err(err);
                }
            }
            phase_end(Phase::Execute, exec_t);

            let no_new_blockers = self.script_jobs.borrow().is_empty()
                && self.deferred_module_jobs.borrow().is_empty();
            if no_new_blockers && !ran_sync && group.is_empty() {
                break;
            }
            if ran_sync || !no_new_blockers {
                continue;
            }
            phase(&format!("load-blocker park ({} in flight)", group.len()));
            if let Some(Err(err)) = group.next().await {
                self.clear();
                return Err(err);
            }
            context.borrow_mut().clear_kept_objects();
        }
        Ok(())
    }
}

impl JobExecutor for PageJobExecutor {
    fn enqueue_job(self: Rc<Self>, job: Job, _ctx: &mut Context) {
        match job {
            Job::PromiseJob(p) => self.promise_jobs.borrow_mut().push_back(p),
            Job::AsyncJob(a) => self.async_jobs.borrow_mut().push_back(a),
            other => self.other_jobs.borrow_mut().push_back(other),
        }
    }

    fn run_jobs(self: Rc<Self>, ctx: &mut Context) -> JsResult<()> {
        // Reached by no-net pages (and unit tests): no tokio-backed async
        // jobs exist, so `run_jobs_async` never parks on the reactor — it
        // runs the synchronous queues straight through, so any block_on
        // suffices (no tokio runtime needed).
        futures::executor::block_on(self.run_jobs_async(&RefCell::new(ctx)))
    }

    async fn run_jobs_async(self: Rc<Self>, context: &RefCell<&mut Context>) -> JsResult<()>
    where
        Self: Sized,
    {
        self.run_jobs_async_mode(context, true).await
    }
}

/// A fresh, isolated engine for one page, with the hostile-input limits
/// applied. Dropped with the page — nothing survives navigation.
#[cfg_attr(not(test), allow(dead_code))] // test/diagnostic surface
pub fn page_context() -> Context {
    page_context_with(None).0
}

#[derive(Clone, Copy)]
struct ClockAnchor {
    epoch_ms: f64,
    monotonic: Instant,
}

thread_local! {
    /// The page clock's last virtual-time anchor. Between explicit timer-clock
    /// advances the clock continues from the host's monotonic clock: High
    /// Resolution Time §2.1 requires web clocks to count real elapsed time, and
    /// freezing Date/performance within one synchronous callback makes a
    /// deadline loop (`while (performance.now() < end)`) non-terminating.
    /// `None` means real system time before the prelude anchors a fresh realm.
    static PAGE_CLOCK_ANCHOR: Cell<Option<ClockAnchor>> = const { Cell::new(None) };
}

/// Boa's `Date` clock, virtual-time-backed: `new Date()` and the native
/// `Date.now()` read the SAME clock the prelude's timers advance, so the two
/// can't diverge during a fast-forward settle (before this, `Date.now()` was
/// overridden in JS to track `timers.now` while `new Date()` kept reading the
/// real host clock — a page comparing them saw time run backwards). The clock
/// advances monotonically from its last virtual anchor even while one callback
/// is running, as both ECMAScript time and High Resolution Time require.
#[derive(Debug)]
struct PageClock;

impl boa_engine::context::Clock for PageClock {
    fn now(&self) -> boa_engine::context::time::JsInstant {
        let ms = PAGE_CLOCK_ANCHOR.get().map_or_else(
            || {
                std::time::SystemTime::now()
                    .duration_since(std::time::UNIX_EPOCH)
                    .unwrap_or_default()
                    .as_millis() as f64
            },
            |anchor| anchor.epoch_ms + anchor.monotonic.elapsed().as_secs_f64() * 1000.0,
        );
        let ms = ms.max(0.0); // JsInstant is epoch-relative and non-negative
        boa_engine::context::time::JsInstant::new(
            (ms / 1000.0) as u64,
            ((ms % 1000.0) * 1_000_000.0) as u32,
        )
    }
}

/// `__clock_set(epochMs)` — anchor the engine's `Date` clock to the page's
/// virtual time (an absolute ms-since-epoch value). Called by the prelude when
/// it first anchors `__epoch0` and whenever `timers.now` advances.
fn sys_clock_set(_: &JsValue, args: &[JsValue], _ctx: &mut Context) -> JsResult<JsValue> {
    if let Some(ms) = args.first().and_then(JsValue::as_number)
        && ms.is_finite()
    {
        PAGE_CLOCK_ANCHOR.set(Some(ClockAnchor {
            epoch_ms: ms,
            monotonic: Instant::now(),
        }));
    }
    Ok(JsValue::undefined())
}

fn page_context_with(loader: Option<Rc<WebModuleLoader>>) -> (Context, Rc<PageHooks>) {
    let hooks = Rc::new(PageHooks {
        rejections: RefCell::new(Vec::new()),
    });
    let executor = Rc::new(PageJobExecutor::default());
    // A fresh page starts on the REAL clock; the prelude anchors its virtual
    // epoch once its timer clock exists (reused threads would otherwise leak
    // the previous page's frozen time into the new page's prelude boot).
    PAGE_CLOCK_ANCHOR.set(None);
    let mut ctx = match loader {
        Some(loader) => Context::builder()
            .module_loader(loader)
            .host_hooks(hooks.clone())
            .clock(Rc::new(PageClock))
            .job_executor(executor)
            .build()
            .unwrap_or_default(),
        None => Context::builder()
            .host_hooks(hooks.clone())
            .clock(Rc::new(PageClock))
            .job_executor(executor)
            .build()
            .unwrap_or_default(),
    };
    let limits = ctx.runtime_limits_mut();
    limits.set_loop_iteration_limit(LOOP_LIMIT);
    limits.set_recursion_limit(RECURSION_LIMIT);
    limits.set_stack_size_limit(STACK_SIZE_LIMIT);
    // Recursion limit raised above Boa's 512 default (see RECURSION_LIMIT):
    // real reactive frameworks (YouTube's kevlar signal graph) legitimately
    // nest call frames hundreds deep, and a browser's native stack allows
    // thousands. The frames are heap-allocated VM CallFrames (not native
    // stack) for pure JS↔JS recursion, so a higher cap is cheap; it still
    // bounds runaway recursion (just deeper), while host cancellation remains
    // available independently of these structural VM limits.
    // Replace Boa's thrashy GC policy (see GC_FLOOR/GC_GROWTH_PERCENT). The
    // policy is thread-local on the GC, so set it every time we build a page
    // context — the trust-js thread is reused across navigations, and each
    // fresh context's heap starts (near) empty as the old one drops.
    apply_gc_policy();
    (ctx, hooks)
}

/// A runaway loop trips Boa's per-frame loop-iteration cap (`LOOP_LIMIT`).
/// That error is UNCATCHABLE by design (the DoS stop — keeping it catchable
/// would let a page nest fresh-budget calls and spin ~unbounded CPU). The bug
/// these tests pin: when the limit is hit inside ASYNC/CALLBACK context (a
/// promise reaction, the Promise executor, an async fn, an async generator, a
/// native callback, …), Boa's reject paths called `to_opaque` on the
/// uncatchable error, which `panic!`s — and that panic, drained outside any
/// `catch_unwind`, killed the resident page actor (every later click then hit
/// "scripts are no longer running"). The fork now PROPAGATES the uncatchable
/// error out of the job instead; here we assert each shape (a) doesn't panic
/// and (b) leaves the engine HEALTHY (a fresh script still runs) — i.e. the
/// page stays fully live, not a dead snapshot.
#[cfg(test)]
mod runtime_limit_in_async {
    use super::*;

    fn assert_clean(label: &str, src: &str) {
        let (mut ctx, _h) = page_context_with(None);
        ctx.runtime_limits_mut().set_loop_iteration_limit(1000);
        let budget = Budget::new(TEST_BUDGET);
        let mut outcome = Outcome::default();
        run_script(&mut ctx, label, src.as_bytes(), &budget, &mut outcome);
        run_jobs_into(&mut ctx, &budget, &mut outcome);
        assert!(
            !outcome.panicked,
            "{label}: engine panicked instead of propagating cleanly: {:?}",
            outcome.errors
        );
        // The engine must remain usable — the limit aborted one job, not the
        // whole context. A fresh script runs cleanly afterward.
        let mut after = Outcome::default();
        run_script(
            &mut ctx,
            "after",
            b"globalThis.__ok = 2;",
            &budget,
            &mut after,
        );
        assert!(
            !after.panicked && after.errors.is_empty(),
            "{label}: engine unhealthy after the limit: panicked={} {:?}",
            after.panicked,
            after.errors
        );
    }

    const RUNAWAY: &str = "for(var i=0;i<1e9;i++){}";

    #[test]
    fn promise_then() {
        assert_clean(
            "then",
            &format!("Promise.resolve().then(function(){{{RUNAWAY}}});"),
        );
    }
    #[test]
    fn promise_executor() {
        assert_clean(
            "executor",
            &format!("new Promise(function(){{{RUNAWAY}}});"),
        );
    }
    #[test]
    fn promise_finally() {
        assert_clean(
            "finally",
            &format!("Promise.resolve().finally(function(){{{RUNAWAY}}});"),
        );
    }
    #[test]
    fn promise_reject_handler() {
        assert_clean(
            "rejectcb",
            &format!("Promise.reject(0).then(null,function(){{{RUNAWAY}}});"),
        );
    }
    #[test]
    fn promise_all_member() {
        assert_clean(
            "all",
            &format!("Promise.all([Promise.resolve().then(function(){{{RUNAWAY}}})]);"),
        );
    }
    #[test]
    fn async_fn() {
        assert_clean("asyncfn", &format!("(async function(){{{RUNAWAY}}})();"));
    }
    #[test]
    fn async_fn_after_await() {
        assert_clean(
            "asyncawait",
            &format!("(async function(){{await 0;{RUNAWAY}}})();"),
        );
    }
    #[test]
    fn async_generator() {
        assert_clean(
            "asyncgen",
            &format!("(async function*(){{{RUNAWAY}}})().next();"),
        );
    }
    #[test]
    fn sync_generator() {
        assert_clean("gen", &format!("(function*(){{{RUNAWAY}}})().next();"));
    }
    #[test]
    fn native_callback() {
        assert_clean(
            "sort",
            &format!("[3,1,2].sort(function(){{{RUNAWAY}return 0;}});"),
        );
    }
}

// ---- Per-phase load profiler (Step 1 decision-gate instrumentation) ----
//
// Decompose a LIVE page load into parse / compile / execute wall time,
// accumulated across every script, module, and job-drain on the page thread.
// The `engine_profile` test times one bundle in isolation; it CANNOT capture
// the settle-time execution where a real SPA spends its seconds (Steam's
// ~15s tail), which only exists in the full page context. This thread-local
// accumulator runs across the whole live load instead — the tool the JS
// JS profiling gate needs to decide whether parse+compile
// or execution dominates a real rendered page (and thus whether lazy compile
// is the prize or execution throughput remains the next target).
//
// Thread-local because all of a page's JS runs on its own `trust-page` thread
// (or the calling thread for the one-shot `transform`). Reset at `load_page`
// start, reported at `settle_page` end, gated on `TRUST_JS_PHASE` (each thread
// reads the env var once when its accumulator is first touched, so the
// `trust-page` thread honors a process-wide `TRUST_JS_PHASE=1`).
//
// Zero behaviour change: `run_script` now splits `ctx.eval` into its exact
// constituent steps — `Script::parse` → `Script::codeblock` → `Script::evaluate`
// — which is what `ctx.eval` does internally (`eval` == `parse?.evaluate`, and
// `evaluate`'s `prepare_run` memoizes `codeblock`; see vendored
// `Context::eval`/`script.rs`). The split is unconditional so what ships is
// what we measure; the `Instant::now()` calls are gated so the unprofiled path
// pays only a cached bool check.
//
// CAVEATS (read before interpreting numbers): (1) "execute" is the synchronous
// JS the VM runs — classic-script top level PLUS every synchronous job/microtask
// drained by the executor — but it EXCLUDES the network parking the executor
// sleeps on (that wall lands in `load wall − measured CPU`). (2) ES-module
// compilation happens inside Boa's `load_link_evaluate`/link (not separately
// exposed), so a module's compile time is attributed to "execute", not
// "compile"; the decision-gate page (Steam) is classic-script-dominated so this
// is benign, but a module-dominated page's "compile" is a lower bound. (3) A
// handful of internal `__trust.*` control evals (tick/scanImageLoads) are
// negligible and left unmeasured. (4) With parallel parse (Step 5a) ON, the
// raw parse of external classic scripts runs on worker threads, so its CPU is
// NOT in this (page-thread) accumulator — "parse" here drops toward zero and
// `measured JS CPU` falls below `/usr/bin/time` User (which sums all threads).
// That gap IS the parallel-parse win; read wall, not the per-phase split, to
// size it.

#[derive(Default, Clone, Copy, Debug)]
pub struct PhaseProfile {
    pub parse: Duration,
    pub parse_n: u32,
    pub compile: Duration,
    pub compile_n: u32,
    pub execute: Duration,
    pub execute_n: u32,
}

#[derive(Clone, Copy)]
enum Phase {
    Parse,
    Compile,
    Execute,
}

thread_local! {
    static PHASES: RefCell<PhaseProfile> = const { RefCell::new(PhaseProfile {
        parse: Duration::ZERO, parse_n: 0,
        compile: Duration::ZERO, compile_n: 0,
        execute: Duration::ZERO, execute_n: 0,
    }) };
    // Per-thread arm state, seeded from the process-wide env flag (so the
    // `trust-page` thread honors `TRUST_JS_PHASE`). Seeding reads the global
    // `OnceLock` — NOT `env::var_os` — so the env (and its global lock) is
    // scanned exactly once per process, never per thread. A test overrides it
    // on its own thread via `phases_arm`.
    static PHASE_ARMED: std::cell::Cell<bool> = std::cell::Cell::new(phase_env_default());
}

/// The process-wide `TRUST_JS_PHASE` flag, read from the environment exactly
/// once. Keeping the env scan out of the per-thread seed keeps the hot path a
/// single thread-local `Cell` read with no env-lock traffic.
fn phase_env_default() -> bool {
    static ENABLED: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ENABLED.get_or_init(|| std::env::var_os("TRUST_JS_PHASE").is_some())
}

#[inline]
fn phases_on() -> bool {
    PHASE_ARMED.with(std::cell::Cell::get)
}

/// Begin a `Some(Instant)` if profiling, else `None` — pairs with `phase_end`.
#[inline]
fn phase_begin() -> Option<Instant> {
    phases_on().then(Instant::now)
}

/// Accumulate `t.elapsed()` into `phase`, if a timer was started.
#[inline]
fn phase_end(phase: Phase, t: Option<Instant>) {
    let Some(t) = t else { return };
    let d = t.elapsed();
    PHASES.with(|p| {
        let mut p = p.borrow_mut();
        match phase {
            Phase::Parse => {
                p.parse += d;
                p.parse_n += 1;
            }
            Phase::Compile => {
                p.compile += d;
                p.compile_n += 1;
            }
            Phase::Execute => {
                p.execute += d;
                p.execute_n += 1;
            }
        }
    });
}

/// Zero the accumulator — called at the start of every page load.
fn phases_reset() {
    PHASES.with(|p| *p.borrow_mut() = PhaseProfile::default());
}

/// Read the accumulator without clearing it (the next load's `phases_reset`
/// clears it). Lets the `settle_page` report and a test read the same numbers.
fn phases_snapshot() -> PhaseProfile {
    PHASES.with(|p| *p.borrow())
}

/// Force-arm/disarm profiling on the current thread (tests; production reads
/// the env var per thread).
#[cfg(test)]
fn phases_arm(on: bool) {
    PHASE_ARMED.with(|c| c.set(on));
}

/// Print the per-phase decomposition of a finished live load (under
/// `TRUST_JS_PHASE`). `wall` is the full load+settle wall clock. The gate
/// reading: parse+compile is the ceiling lazy compilation can remove; if it is
/// a small share of the measured JS CPU (cross-check against `/usr/bin/time -v`
/// User CPU, which should be ≈ the CPU line here), execution dominates and the
/// execution throughput remains the next optimization target.
fn report_phases(wall: Duration) {
    if !phases_on() {
        return;
    }
    let p = phases_snapshot();
    let cpu = p.parse + p.compile + p.execute;
    let pc = p.parse + p.compile;
    let pct = |a: Duration, b: Duration| {
        if b.is_zero() {
            0.0
        } else {
            100.0 * a.as_secs_f64() / b.as_secs_f64()
        }
    };
    let at = crate::http::trace_ms();
    eprintln!("js : @{at:>6}ms ─── phase profile (whole live load) ───");
    eprintln!(
        "       parse   : {:>10.3?}  ({} units, {:>4.1}% of JS CPU)",
        p.parse,
        p.parse_n,
        pct(p.parse, cpu)
    );
    eprintln!(
        "       compile : {:>10.3?}  ({} units, {:>4.1}% of JS CPU)",
        p.compile,
        p.compile_n,
        pct(p.compile, cpu)
    );
    eprintln!(
        "       execute : {:>10.3?}  ({} drains+toplevel, {:>4.1}% of JS CPU; incl. module compile)",
        p.execute,
        p.execute_n,
        pct(p.execute, cpu)
    );
    eprintln!(
        "       ── measured JS CPU (parse+compile+execute): {cpu:.3?}  [≈ /usr/bin/time User]"
    );
    eprintln!(
        "       ── parse+compile = {:.3?} ({:>4.1}% of JS CPU)  ← lazy-compile lever ceiling",
        pc,
        pct(pc, cpu)
    );
    eprintln!(
        "       ── load wall: {:.3?}  (wall − JS CPU ≈ network wait + Rust-side: {:.3?})",
        wall,
        wall.saturating_sub(cpu)
    );
}

/// The process-wide `TRUST_FN_CENSUS` flag, read from the environment once. When
/// set, a live page load arms the function-execution census (`vm::fn_census`)
/// after the prelude and reports it at settle — the authoritative "real,
/// fully-booting page: what fraction of the page's own compiled functions are
/// never called" measurement (the lazy-parse sizing gate), and later the check
/// that a lazy-parse build actually defers them.
fn fn_census_on() -> bool {
    static ENABLED: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ENABLED.get_or_init(|| std::env::var_os("TRUST_FN_CENSUS").is_some())
}

/// Whether TRust lazy parsing is active, read from the environment once.
/// When on, eligible ordinary function bodies are (a) *skipped at parse time*
/// — their statement AST is never built; only the matching-brace boundary +
/// free-variable superset are scanned (TRust lazy *parsing*, Phase C2; see
/// [`boa_parser::lazy`]/[`boa_parser::lazy_scan`]) — and (b) compiled lazily,
/// deferred to first call (TRust lazy *compilation*, Phase B; see
/// [`boa_engine::vm::lazy`]). A function reaches the wire only when first called.
///
/// **Default ON** (2026-06-27): a parse-heavy multi-chunk page renders in ~0.98 s
/// at ~390 MB peak RSS instead of ~3.0 s / ~2.2 GB, and lazy now COMPOSES with
/// parallel parse (the workers skip too). `TRUST_NO_LAZY_PARSE` is the kill
/// switch / A-B toggle, like `TRUST_NO_PARALLEL_PARSE` / `TRUST_NO_CDN_CACHE`.
/// KNOWN: the C1 delazify scope-analyzer bug can degrade React/TanStack-heavy
/// pages (e.g. GitHub code-view) to a `·JS:n!` partial render — its own Boa-fork
/// session (see the lazy-parse-c1-delazify-bug notes).
fn lazy_parse_on() -> bool {
    static ENABLED: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ENABLED.get_or_init(|| std::env::var_os("TRUST_NO_LAZY_PARSE").is_none())
}

/// Enable (or disable) BOTH halves of TRust lazy parsing — lazy *parsing*
/// (`boa_parser::lazy`, skip bodies at parse) and lazy *compilation*
/// (`boa_engine::vm::lazy`, defer bytecode) — on the current thread, honoring
/// the `TRUST_LAZY_MIN` size override. Called on the page thread before any of
/// the page's own scripts load.
fn set_lazy_enabled(enabled: bool) {
    boa_engine::vm::lazy::set_enabled(enabled);
    boa_parser::lazy::set_enabled(enabled);
    if let Some(n) = lazy_min() {
        boa_engine::vm::lazy::set_min_source_len(n);
        boa_parser::lazy::set_min_len(n);
    }
}

/// Optional `TRUST_LAZY_MIN` override (code points) for the lazy-compilation
/// size threshold — the smallest function source worth deferring. `None` keeps
/// boa's [`DEFAULT_MIN_SOURCE_LEN`](boa_engine::vm::lazy). Used to A/B the
/// deferral aggressiveness.
fn lazy_min() -> Option<usize> {
    static MIN: std::sync::OnceLock<Option<usize>> = std::sync::OnceLock::new();
    *MIN.get_or_init(|| {
        std::env::var_os("TRUST_LAZY_MIN")
            .and_then(|v| v.to_str().and_then(|s| s.parse::<usize>().ok()))
    })
}

/// Report the live page's function-execution census, if armed (see
/// [`fn_census_on`]). Counts only the page's own scripts' blocks — the prelude's
/// are excluded because arming happens after `run_prelude`.
fn report_fn_census() {
    if !fn_census_on() {
        return;
    }
    let c = boa_engine::vm::fn_census::snapshot();
    let never_n = c.compiled_n.saturating_sub(c.executed_n);
    let never_bytes = c.compiled_bytes.saturating_sub(c.executed_bytes);
    let pct = |num: u64, den: u64| -> f64 {
        if den == 0 {
            0.0
        } else {
            100.0 * num as f64 / den as f64
        }
    };
    let at = crate::http::trace_ms();
    eprintln!("js : @{at:>6}ms ─── function census (page scripts, excl. prelude) ───");
    eprintln!(
        "       compiled    : {:>6} fns, {:>9} bytecode bytes",
        c.compiled_n, c.compiled_bytes
    );
    eprintln!(
        "       executed    : {:>6} fns ({:>5.1}%), {:>9} bytes ({:>5.1}%)",
        c.executed_n,
        pct(c.executed_n, c.compiled_n),
        c.executed_bytes,
        pct(c.executed_bytes, c.compiled_bytes),
    );
    eprintln!(
        "       NEVER-CALLED: {:>6} fns ({:>5.1}%), {:>9} bytes ({:>5.1}%)  ← lazy-parse prize",
        never_n,
        pct(never_n, c.compiled_n),
        never_bytes,
        pct(never_bytes, c.compiled_bytes),
    );
}

/// Run one script, tolerating failure: an exception (including a tripped
/// runtime limit) lands in `outcome.errors` tagged with `name`, and the
/// page lives on. Skipped outright when the budget is spent.
pub fn run_script(
    ctx: &mut Context,
    name: &str,
    source: &[u8],
    budget: &Budget,
    outcome: &mut Outcome,
) {
    run_script_task(ctx, name, source, budget, outcome, true);
}

/// Run source as a browser-owned task which HTML requires independently of
/// whether the document's author-script launch allowance has just been spent.
/// Boa's recursion/stack/loop limits still apply, but the browser does not arm
/// a wall deadline. In particular, HTML "the end" queues DOMContentLoaded and
/// load tasks; they are not optional trailing author scripts that a cumulative
/// script gate may silently discard.
fn run_browser_task(
    ctx: &mut Context,
    name: &str,
    source: &[u8],
    budget: &Budget,
    outcome: &mut Outcome,
) {
    run_script_task(ctx, name, source, budget, outcome, false);
}

fn run_script_task(
    ctx: &mut Context,
    name: &str,
    source: &[u8],
    budget: &Budget,
    outcome: &mut Outcome,
    enforce_compute_budget: bool,
) {
    if budget.exhausted() || (enforce_compute_budget && outcome.elapsed >= compute_budget()) {
        outcome
            .errors
            .push(format!("{name}: skipped, page JS budget exhausted"));
        return;
    }
    budget.install(ctx);
    let started = Instant::now();
    // catch_unwind: a Boa VM bug must cost one script, not the page —
    // the DOM mutations made so far stay serializable. (RefCell guards
    // release during unwind, so the arena stays consistent.)
    let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        // Tag the source with its URL/label so backtraces name the file
        // (classic scripts were anonymous "unknown" — modules already do this).
        //
        // This is `ctx.eval` unrolled into its exact three steps so the phase
        // profiler can time each: `eval` IS `Script::parse(..)?.evaluate(..)`,
        // and `evaluate`'s `prepare_run` memoizes `codeblock` — so pre-calling
        // `codeblock` only lets us time compilation separately; the result is
        // byte-for-byte identical to `ctx.eval`.
        let src = Source::from_bytes(source).with_path(std::path::Path::new(name));
        let t = phase_begin();
        let script = boa_engine::Script::parse(src, None, ctx)?;
        phase_end(Phase::Parse, t);
        let t = phase_begin();
        script.codeblock(ctx)?;
        phase_end(Phase::Compile, t);
        let t = phase_begin();
        let r = script.evaluate(ctx);
        phase_end(Phase::Execute, t);
        r
    }));
    match result {
        Ok(Ok(_)) => {}
        Ok(Err(err)) => record_task_error(outcome, name, err),
        Err(_) => {
            outcome
                .errors
                .push(format!("{name}: engine panic (Boa bug) — page JS halted"));
            outcome.panicked = true;
        }
    }
    outcome.elapsed += started.elapsed();
}

/// Process-global detached image of the compiled PRELUDE — the in-memory
/// compiled-code cache's first consumer (the cross-page cache work,
/// built on the K1/K2 keystone `CodeBlockImage`).
///
/// The prelude is the same ~65 KB of JS on every page, and its parse+compile is
/// the bulk of the per-page prelude cost. A compiled `CodeBlock` is normally
/// pinned to the thread + GC heap that built it, but a `CodeBlockImage` is the
/// detached, `Send + Sync`, `Gc`-free form: we compile the prelude ONCE per
/// process, store its image here, and rehydrate a fresh `Gc<CodeBlock>` into
/// each page thread's own heap — no re-parse, no re-compile.
///
/// Sound to reuse across realms because the prelude is a single top-level IIFE:
/// it declares NO top-level `let`/`const`/`function`/`var` (every global is a
/// `globalThis.X = …` property write from inside the IIFE), so its compiled
/// `<main>` block references no realm global-binding slots and runs identically
/// in any realm — exactly the cross-realm path the keystone tests exercise. It
/// also has no dynamic `import()` (the only runtime use of the carrier script's
/// own AST), so the empty shell it is installed into is never dereferenced.
static PRELUDE_IMAGE: std::sync::OnceLock<boa_engine::vm::CodeBlockImage> =
    std::sync::OnceLock::new();

/// Run a rehydrated [`CodeBlockImage`] as a script in `ctx`'s realm: install it
/// into an empty carrier script (`Script::parse("")`, ~free, which binds the
/// carrier to this realm) and evaluate. The shared execution seam behind both
/// the prelude cache and the cross-page CDN cache.
///
/// Sound ONLY for a realm-portable image: one whose source declared no globals,
/// so its compiled `<main>` block references no realm global-binding slots and
/// has no global-declaration side effects (the prelude has this by construction;
/// CDN libraries are admitted only after the realm-portability gate). The empty
/// carrier is never dereferenced as a dynamic-`import()` referrer because such a
/// block has no dynamic import. `name` (the script URL or "prelude") becomes the
/// carrier's source path so a thrown error's backtrace still names the file.
///
/// Same budget gate, `catch_unwind`, and error/panic accounting as
/// [`run_script`], so a (hypothetical) failure degrades the page identically.
fn run_rehydrated_image(
    ctx: &mut Context,
    name: &str,
    image: &boa_engine::vm::CodeBlockImage,
    budget: &Budget,
    outcome: &mut Outcome,
) {
    if budget.exhausted() || outcome.elapsed >= compute_budget() {
        outcome
            .errors
            .push(format!("{name}: skipped, page JS budget exhausted"));
        return;
    }
    let started = Instant::now();
    let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        let src = Source::from_bytes("".as_bytes()).with_path(std::path::Path::new(name));
        let t = phase_begin();
        let shell = boa_engine::Script::parse(src, None, ctx)?;
        phase_end(Phase::Parse, t);
        let t = phase_begin();
        shell.set_codeblock(boa_engine::vm::CodeBlock::from_image(image));
        phase_end(Phase::Compile, t);
        let t = phase_begin();
        let r = shell.evaluate(ctx);
        phase_end(Phase::Execute, t);
        r
    }));
    match result {
        Ok(Ok(_)) => {}
        Ok(Err(err)) => record_task_error(outcome, name, err),
        Err(_) => {
            outcome
                .errors
                .push(format!("{name}: engine panic (Boa bug) — page JS halted"));
            outcome.panicked = true;
        }
    }
    outcome.elapsed += started.elapsed();
}

/// Run the PRELUDE through the process-global compiled-code cache: the first
/// page parses + compiles it and stores the detached image; every later page
/// (on its own `trust-js`/`trust-page` thread) rehydrates that image and skips
/// both the 65 KB parse and the compile, paying only execution — which every
/// realm must pay regardless, since the prelude's globals are installed by
/// *running* the IIFE, not by declaring them.
///
/// The parse-skipping twin of [`run_script`] for our one always-present,
/// always-identical script: same budget gate, `catch_unwind`, and error/panic
/// accounting, so a (hypothetical) prelude failure degrades the page exactly as
/// before. `TRUST_NO_PRELUDE_CACHE` forces the cold `run_script` path — the A/B
/// toggle and safety valve, like `TRUST_NO_PARALLEL_PARSE` for parallel parse.
fn run_prelude(ctx: &mut Context, budget: &Budget, outcome: &mut Outcome) {
    if std::env::var_os("TRUST_NO_PRELUDE_CACHE").is_some() {
        run_script(ctx, "prelude", PRELUDE.as_bytes(), budget, outcome);
        return;
    }
    if let Some(image) = PRELUDE_IMAGE.get() {
        // Cache hit: rehydrate the compiled block into THIS thread's heap and
        // run it via an empty carrier — no 225 KB parse, no compile.
        run_rehydrated_image(ctx, "prelude", image, budget, outcome);
        return;
    }
    if budget.exhausted() || outcome.elapsed >= compute_budget() {
        outcome
            .errors
            .push(String::from("prelude: skipped, page JS budget exhausted"));
        return;
    }
    let started = Instant::now();
    let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        // Cold (first page of the process, or a rare concurrent-first race):
        // parse + compile the real prelude, cache its detached image for later
        // pages, then run. A lost `set` race is harmless — the winner's image
        // serves the cache and our own freshly compiled block still runs this
        // page (`let _ =` discards the rejected value).
        //
        // Suppress TRust lazy parsing AND compilation for this compile: the
        // result is dehydrated to a cached image, which cannot carry a lazy
        // stub (a skipped/deferred body) — `to_image` asserts it doesn't. The
        // prelude must parse and compile eagerly.
        let _no_lazy = boa_engine::vm::lazy::suppress();
        let _no_lazy_parse = boa_parser::lazy::suppress();
        let src = Source::from_bytes(PRELUDE.as_bytes()).with_path(std::path::Path::new("prelude"));
        let t = phase_begin();
        let script = boa_engine::Script::parse(src, None, ctx)?;
        phase_end(Phase::Parse, t);
        let t = phase_begin();
        let cb = script.codeblock(ctx)?;
        let _ = PRELUDE_IMAGE.set(cb.to_image());
        phase_end(Phase::Compile, t);
        let t = phase_begin();
        let r = script.evaluate(ctx);
        phase_end(Phase::Execute, t);
        r
    }));
    match result {
        Ok(Ok(_)) => {}
        Ok(Err(err)) => record_task_error(outcome, "prelude", err),
        Err(_) => {
            outcome.errors.push(String::from(
                "prelude: engine panic (Boa bug) — page JS halted",
            ));
            outcome.panicked = true;
        }
    }
    outcome.elapsed += started.elapsed();
}

/// Max parse workers in the parallel-parse pool. Bounded like
/// `PREFETCH_CONCURRENCY` so a page with
/// hundreds of `<script>`s can't spawn a thread storm; clamped to core count
/// and job count below.
const PARSE_CONCURRENCY: usize = 8;

/// The raw-parse half of parallel parse. External classic scripts are lexed and
/// parsed to ASTs on a pool of big-stack worker threads — OFF the page thread —
/// while the page thread runs the prelude and earlier scripts. Scope analysis
/// and bytecode compilation stay on the page thread, in document order, because
/// global lexical bindings (`let`/`const`/`class`) resolve at runtime by slot
/// index into one shared global environment, so their declaration order must be
/// preserved (see `boa_engine::Script::compile_raw`). Each worker parses with a
/// private interner that rides along with its AST; no interner merge is needed
/// because the shared scope links scripts by `JsString` name, not interner index.
struct ParsePool {
    rx: std::sync::mpsc::Receiver<(usize, Result<boa_engine::RawScript, String>)>,
    buffered: std::collections::HashMap<usize, Result<boa_engine::RawScript, String>>,
    dispatched: std::collections::HashSet<usize>,
}

impl ParsePool {
    /// Whether script `index` went to the pool (the rest are parsed inline).
    fn was_dispatched(&self, index: usize) -> bool {
        self.dispatched.contains(&index)
    }

    /// Take script `index`'s raw parse, buffering any other results that arrive
    /// first. Blocks only if the worker hasn't finished `index` yet — usually
    /// it has, having overlapped the page thread's earlier work. Only called for
    /// dispatched indices.
    fn take(&mut self, index: usize) -> Result<boa_engine::RawScript, String> {
        if let Some(result) = self.buffered.remove(&index) {
            return result;
        }
        loop {
            match self.rx.recv() {
                Ok((i, result)) if i == index => return result,
                Ok((i, result)) => {
                    self.buffered.insert(i, result);
                }
                // All workers exited without producing `index` — only possible
                // if every spawn failed; surface a per-script error, page lives.
                Err(_) => return Err(String::from("parse worker exited without a result")),
            }
        }
    }
}

/// Dispatch raw-parse jobs for every external classic script that has a fetched
/// body, returning a [`ParsePool`] to collect them — or `None` when there are
/// fewer than two such scripts (a single bundle is one parse unit, so a pool
/// would only add thread overhead; the loop then parses inline as before).
///
/// One parser id is allocated per script from the page `Context` up front
/// (tagged-template call-site identity must stay unique across separately parsed
/// scripts, exactly as the in-context parse path allocates them), so this
/// borrows `ctx` briefly before any worker starts.
fn dispatch_parallel_parse(
    scripts: &[(Option<String>, String, Option<String>, usize)],
    externals: &[(String, Option<std::sync::Arc<Vec<u8>>>)],
    cdn_keys: &std::collections::HashMap<usize, [u8; 32]>,
    cache_hits: &std::collections::HashSet<usize>,
    ctx: &mut Context,
) -> Option<ParsePool> {
    // Kill switch: `TRUST_NO_PARALLEL_PARSE` forces the sequential path (parse
    // inline on this thread). A safety valve for a concurrency feature touching
    // the engine, and the A/B toggle for measuring the win.
    if std::env::var_os("TRUST_NO_PARALLEL_PARSE").is_some() {
        return None;
    }
    // Parallel parse now COMPOSES with lazy parse: the workers skip eligible
    // bodies too (the per-job `lazy` flag below + `boa_parser::lazy` set on each
    // worker thread, since lazy parsing is thread-local). `compile_raw` on the
    // page thread stubs those skipped bodies; delazify re-parses from the
    // retained span, so the dropped worker interner is irrelevant. The one
    // exception is a CDN-cache candidate — it must stay EAGER so its image can
    // be dehydrated — so it is excluded from the lazy path per-job.
    let lazy_on = lazy_parse_on();
    let lazy_min = lazy_min();
    // (script index, name, shared body, parser id, lazy-parse this job)
    type ParseJob = (usize, String, std::sync::Arc<Vec<u8>>, u32, bool);
    let mut jobs: Vec<ParseJob> = Vec::new();
    for (i, (src, _inline, type_attr, _node)) in scripts.iter().enumerate() {
        if !is_classic(type_attr) {
            continue;
        }
        // A CDN cache hit is rehydrated, not compiled, so it needs no parse —
        // keep it out of the pool (parsing it would be pure waste).
        if cache_hits.contains(&i) {
            continue;
        }
        // Inline scripts stay on the page thread (small, and the body is already
        // in hand); only external bundles — where the parse cost lives — go to
        // the pool. A not-fetched / ad-blocked external has no body to parse.
        let Some(src) = src else { continue };
        let Some((_, Some(body))) = externals.iter().find(|(k, _)| k == src) else {
            continue;
        };
        let id = ctx.next_parser_identifier();
        // Lazy-parse this job unless it's a cacheable shared lib: the CDN image
        // cache (compiled once per session, rehydrated free) beats re-skipping
        // jQuery/D3/Vue every page, and a lazy stub can't be imaged. Big unique
        // first-party bundles — the lazy-parse prize — are skipped. The key
        // comes precomputed from `load_page` (SHA-256 over a multi-MB bundle
        // is not free — it was being recomputed here and again at run time).
        let lazy_job = lazy_on && !cdn_cache_candidate_keyed(cdn_keys.get(&i), body.len());
        jobs.push((i, src.clone(), body.clone(), id, lazy_job));
    }
    if jobs.len() < 2 {
        return None;
    }
    let dispatched: std::collections::HashSet<usize> = jobs.iter().map(|(i, ..)| *i).collect();
    let n_workers = std::thread::available_parallelism()
        .map(std::num::NonZeroUsize::get)
        .unwrap_or(2)
        .min(jobs.len())
        .min(PARSE_CONCURRENCY);
    let queue = std::sync::Arc::new(std::sync::Mutex::new(VecDeque::from(jobs)));
    let (tx, rx) = std::sync::mpsc::channel();
    for w in 0..n_workers {
        let queue = std::sync::Arc::clone(&queue);
        let tx = tx.clone();
        let spawned = std::thread::Builder::new()
            .name(format!("trust-parse-{w}"))
            // Same 64MB stack as the page thread: Boa's recursive-descent parser
            // can overflow a 2 MB stack on a big bundle (an uncatchable abort,
            // trap #1). The panic hook in main.rs covers `trust-*` threads.
            .stack_size(PAGE_STACK)
            .spawn(move || {
                loop {
                    let job = queue.lock().expect("parse queue poisoned").pop_front();
                    let Some((index, name, body, id, lazy)) = job else {
                        break;
                    };
                    // Lazy parsing is thread-local, so the page thread's setting
                    // does not reach this worker — apply the per-job decision
                    // before parsing (matching the page thread's `min_len`).
                    boa_parser::lazy::set_enabled(lazy);
                    if let Some(n) = lazy_min {
                        boa_parser::lazy::set_min_len(n);
                    }
                    let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                        let src =
                            Source::from_bytes(&body[..]).with_path(std::path::Path::new(&name));
                        boa_engine::Script::raw_parse(src, id)
                    }))
                    .unwrap_or_else(|_| Err(String::from("raw parse panicked (Boa bug)")));
                    if tx.send((index, result)).is_err() {
                        break; // page thread is gone; stop early
                    }
                }
            });
        if spawned.is_err() {
            // A worker failed to spawn; the others still drain the queue. Its tx
            // clone drops with the failed closure, so the channel still closes
            // when the live workers finish.
        }
    }
    drop(tx); // the spawned workers hold the only live senders now
    Some(ParsePool {
        rx,
        buffered: std::collections::HashMap::new(),
        dispatched,
    })
}

/// The cross-page CDN compiled-code cache — the keystone `CodeBlockImage`'s
/// second consumer, after the prelude cache.
///
/// External classic scripts (jQuery, D3, Vue, Lit, React … served from a CDN)
/// are byte-identical across the pages of a session, yet Boa re-parses and
/// re-compiles each one per page. This process-global cache keys a detached,
/// `Send + Sync` `CodeBlockImage` by the script's source hash so a given library
/// is parsed + compiled ONCE per process and merely *rehydrated* (re-allocated
/// into the page thread's GC heap) on every later page. RAM-only and
/// session-lifetime, the same ethos as the keep-alive `POOL` and the cookie jar.
///
/// Only **realm-portable** blocks are admitted (see the gate in
/// [`run_external_classic`]): a classic script runs in the page's global scope,
/// and a top-level `let`/`const`/`class` compiles to a binding referenced by
/// SLOT INDEX into the realm's shared, accumulating global declarative
/// environment — an index that depends on what ran before it on the page, so its
/// block is NOT valid on another page. Every real UMD/IIFE bundle (`(function(){
/// …})()` or `var Lib = (function(){…})()` at top level) is portable; anything
/// declaring a global lexical falls back cleanly to a normal per-page compile
/// and is marked [`CdnEntry::NotReusable`] so the gate isn't re-evaluated on
/// every visit. `TRUST_NO_CDN_CACHE` disables it (the A/B toggle + safety valve,
/// like `TRUST_NO_PRELUDE_CACHE`).
enum CdnEntry {
    /// A realm-portable compiled block, reusable on any page this session.
    Reusable(std::sync::Arc<boa_engine::vm::CodeBlockImage>),
    /// This source compiled to a non-portable block — don't cache or re-check it.
    NotReusable,
}

/// The result of a [`CDN_CACHE`] probe.
enum CdnLookup {
    Reusable(std::sync::Arc<boa_engine::vm::CodeBlockImage>),
    NotReusable,
    Absent,
}

/// Bounded image set (a RAM lid; a session loads a small, fixed set of CDN
/// libraries). On overflow the oldest insertion is evicted — a hostile-page
/// guard, not a working constraint.
const CDN_CACHE_MAX: usize = 64;

/// Per-script source-size cap for admission to the compile cache. A script
/// larger than this is never cached: a huge bundle is almost always FIRST-PARTY
/// and unique (YouTube's ~10 MB `kevlar_base`), so it is never reused on another
/// page and its compiled image is pure RAM cost. Every real *shared* CDN library
/// — jQuery (85 KB), D3 (273 KB), Vue (160 KB), React + react-dom (≤128 KB min,
/// ~1 MB dev) — sits below the cap, so the speed win is untouched. (2026-06-26:
/// this + [`CDN_CACHE_MAX_BYTES`] replaced the entries-only lid; a single YouTube
/// visit was pinning ~2.7 GB of bytecode images, held process-globally across
/// later navigations — measured peak RSS 3.7 GB → 1.0 GB with the cache off.)
const CDN_CACHE_MAX_SCRIPT: usize = 2 * 1024 * 1024;

/// Total source-bytes budget for cached reusable images (source length is the
/// proxy for compiled-image footprint). Past it, the oldest insertions are
/// evicted by bytes, so the cache's resident cost is bounded regardless of how
/// many distinct libraries a session touches.
const CDN_CACHE_MAX_BYTES: usize = 64 * 1024 * 1024;

/// Whether a script of this source size may be admitted to the compile cache
/// (the per-script half of the RAM lid — see [`CDN_CACHE_MAX_SCRIPT`]).
fn cdn_cacheable(body_len: usize) -> bool {
    body_len <= CDN_CACHE_MAX_SCRIPT
}

/// Discriminates cache entries by engine build: a different binary may compile
/// the same source to an incompatible image, so its hash space must not overlap.
/// The cache never persists across processes, so within one run this is
/// constant; folding it into the key is defensive and documents the keying rule
/// (source hash + engine build + flags).
const CDN_CACHE_BUILD_TAG: &str = concat!("trust-cdn-cache-v1/", env!("CARGO_PKG_VERSION"));

struct CdnCache {
    map: std::collections::HashMap<[u8; 32], CdnEntry>,
    /// `(key, source-bytes)` in insertion order, for FIFO eviction past either
    /// the entry lid (`CDN_CACHE_MAX`) or the byte budget (`CDN_CACHE_MAX_BYTES`).
    order: VecDeque<([u8; 32], usize)>,
    /// Running sum of `order`'s bytes — the cache's tracked resident footprint.
    total_bytes: usize,
}

static CDN_CACHE: std::sync::OnceLock<std::sync::Mutex<CdnCache>> = std::sync::OnceLock::new();

fn cdn_cache() -> &'static std::sync::Mutex<CdnCache> {
    CDN_CACHE.get_or_init(|| {
        std::sync::Mutex::new(CdnCache {
            map: std::collections::HashMap::new(),
            order: VecDeque::new(),
            total_bytes: 0,
        })
    })
}

/// Whether the CDN cache is active. `TRUST_NO_CDN_CACHE` forces the cold compile
/// path for every external script.
fn cdn_cache_enabled() -> bool {
    std::env::var_os("TRUST_NO_CDN_CACHE").is_none()
}

/// Cache key for a script body: a strong (collision-free in practice) hash over
/// the engine-build tag, the length, and the bytes.
fn cdn_cache_key(body: &[u8]) -> [u8; 32] {
    use sha2::Digest as _;
    let mut hasher = sha2::Sha256::new();
    hasher.update(CDN_CACHE_BUILD_TAG.as_bytes());
    hasher.update((body.len() as u64).to_le_bytes());
    hasher.update(body);
    hasher.finalize().into()
}

/// Probe the cache, cloning the (cheap, `Arc`) reusable image out under the lock.
/// A poisoned lock degrades to a miss (the cache simply stops helping).
fn cdn_cache_lookup(key: &[u8; 32]) -> CdnLookup {
    let Ok(cache) = cdn_cache().lock() else {
        return CdnLookup::Absent;
    };
    match cache.map.get(key) {
        Some(CdnEntry::Reusable(image)) => CdnLookup::Reusable(image.clone()),
        Some(CdnEntry::NotReusable) => CdnLookup::NotReusable,
        None => CdnLookup::Absent,
    }
}

/// Whether this external script body is, right now, a candidate for the CDN
/// compile cache on this page: caching enabled (`key` is only `Some` then), a
/// true miss (`Absent` — not a hit, which is excluded earlier, nor an
/// already-decided `NotReusable`), and small enough to admit. A candidate must
/// compile **eagerly** so its image can be dehydrated, so parallel parse keeps
/// it off the lazy path (and runs its page-thread compile un-suppressed). This
/// mirrors the `store_key` decision in [`run_external_classic`] exactly, so the
/// two never disagree on which scripts stay eager — the lazy-parse safety net
/// (`RawScript::was_lazy_parsed`) covers the residual race where a
/// `NotReusable` entry is evicted in between. Takes the PRECOMPUTED key (see
/// [`cdn_cache_keys`]) so the SHA-256 of a multi-MB bundle is paid once per
/// page, not once per decision point.
fn cdn_cache_candidate_keyed(key: Option<&[u8; 32]>, body_len: usize) -> bool {
    match key {
        Some(k) => cdn_cacheable(body_len) && matches!(cdn_cache_lookup(k), CdnLookup::Absent),
        None => false, // cache disabled: never a candidate (stays on the lazy path)
    }
}

/// Precompute the CDN cache key for every external classic script that has a
/// fetched body, by script index — the ONE place the (SHA-256) key is hashed
/// per page. Empty when the cache is disabled, so an absent entry doubles as
/// the "disabled" signal for [`cdn_cache_candidate_keyed`].
fn cdn_cache_keys(
    scripts: &[(Option<String>, String, Option<String>, usize)],
    externals: &[(String, Option<std::sync::Arc<Vec<u8>>>)],
) -> std::collections::HashMap<usize, [u8; 32]> {
    let mut keys = std::collections::HashMap::new();
    if !cdn_cache_enabled() {
        return keys;
    }
    for (i, (src, _inline, type_attr, _node)) in scripts.iter().enumerate() {
        if !is_classic(type_attr) {
            continue;
        }
        let Some(src) = src else { continue };
        let Some((_, Some(body))) = externals.iter().find(|(k, _)| k == src) else {
            continue;
        };
        keys.insert(i, cdn_cache_key(body));
    }
    keys
}

/// Record a cache decision for `key` (the first writer wins a race; a poisoned
/// lock silently drops the entry). `bytes` is the entry's source-length cost
/// (0 for a `NotReusable` marker). Evicts the oldest insertions past either lid.
fn cdn_cache_put(key: [u8; 32], entry: CdnEntry, bytes: usize) {
    let Ok(mut cache) = cdn_cache().lock() else {
        return;
    };
    cdn_cache_insert(&mut cache, key, entry, bytes);
}

/// The eviction policy (pure, so it's unit-testable off the process-global
/// cache): keep both the entry-count lid and the byte budget satisfied with the
/// incoming entry counted, evicting oldest-first. The `!is_empty` guard makes a
/// lone over-budget entry degrade to "cache just this one" rather than loop
/// forever — though the per-script cap keeps any single image well under budget.
fn cdn_cache_insert(cache: &mut CdnCache, key: [u8; 32], entry: CdnEntry, bytes: usize) {
    if cache.map.contains_key(&key) {
        return;
    }
    while !cache.map.is_empty()
        && (cache.map.len() >= CDN_CACHE_MAX
            || cache.total_bytes.saturating_add(bytes) > CDN_CACHE_MAX_BYTES)
    {
        match cache.order.pop_front() {
            Some((oldest, oldest_bytes)) => {
                if cache.map.remove(&oldest).is_some() {
                    cache.total_bytes = cache.total_bytes.saturating_sub(oldest_bytes);
                }
            }
            None => break,
        }
    }
    cache.order.push_back((key, bytes));
    cache.total_bytes = cache.total_bytes.saturating_add(bytes);
    cache.map.insert(key, entry);
}

/// Indices (into `scripts`) of external classic scripts whose compiled image is
/// already cached as reusable. They are rehydrated rather than compiled, so they
/// need no parse and are kept OUT of the parallel-parse pool (a worker parse of
/// a script we'll never compile would be pure waste). Reads the precomputed
/// [`cdn_cache_keys`] (empty when the cache is disabled).
fn cdn_cache_hits(
    cdn_keys: &std::collections::HashMap<usize, [u8; 32]>,
) -> std::collections::HashSet<usize> {
    cdn_keys
        .iter()
        .filter(|(_, k)| matches!(cdn_cache_lookup(k), CdnLookup::Reusable(_)))
        .map(|(&i, _)| i)
        .collect()
}

/// Run one external classic script, going through the CDN compile cache.
///
/// - **Hit** (a reusable image is cached): rehydrate + run via the carrier,
///   skipping parse AND compile. (`prepared` is `None` here — a hit is excluded
///   from the parallel-parse pool.)
/// - **Miss** (`Absent`): compile this page's copy — from the worker `prepared`
///   raw parse when present, else parsed inline — then apply the
///   realm-portability gate and, if it passes, store the detached image for
///   later pages. The gate is two cheap fork checks:
///   [`Script::global_declarations_are_replayable`] (the script declares no
///   global *lexical* — `let`/`const`/`class` — nor Annex-B block-function
///   binding, so running its `<main>` recreates all its globals; top-level
///   `var`/`function` are fine, created by name from the bytecode) AND
///   [`CodeBlock::is_realm_portable`](boa_engine::vm::CodeBlock::is_realm_portable)
///   (it reads no prior script's global-declarative slot). Both must hold; a
///   real UMD/IIFE bundle passes trivially.
/// - **`NotReusable`** (a prior page proved it non-portable): compile + run, no
///   re-check, no store.
///
/// Same budget gate, `catch_unwind`, and error/panic accounting as
/// [`run_script`], so a bad script costs only itself.
fn run_external_classic(
    ctx: &mut Context,
    name: &str,
    body: &[u8],
    // The script's precomputed cache key ([`cdn_cache_keys`]); `None` when the
    // cache is disabled OR the caller fetched the body on demand (past the
    // prefetch lid) and no key exists yet — then it is hashed here, once.
    key: Option<[u8; 32]>,
    prepared: Option<Result<boa_engine::RawScript, String>>,
    budget: &Budget,
    outcome: &mut Outcome,
) {
    let key = key.or_else(|| cdn_cache_enabled().then(|| cdn_cache_key(body)));
    let lookup = key.as_ref().map_or(CdnLookup::Absent, cdn_cache_lookup);
    if let CdnLookup::Reusable(image) = &lookup {
        phase(&format!(
            "cdn cache HIT {name} (rehydrate, no parse/compile)"
        ));
        run_rehydrated_image(ctx, name, image, budget, outcome);
        return;
    }
    // A worker that lazy-parsed this script may have left skipped (lazy) bodies
    // in it, which cannot be dehydrated into an image — so such a script is
    // never cached, regardless of the cache state. The dispatch heuristic
    // (`cdn_cache_candidate`) already keeps cache candidates EAGER; this is the
    // safety net for the residual race where that prediction and the cache
    // disagree (e.g. a `NotReusable` entry evicted between dispatch and here).
    let prepared_is_lazy = matches!(&prepared, Some(Ok(raw)) if raw.was_lazy_parsed());
    // Store the freshly compiled image only on a true miss (`Absent`) AND only
    // when the source is small enough to be worth keeping (see `cdn_cacheable` —
    // a monster first-party bundle is excluded). A `NotReusable` entry means we
    // already decided this source can't be cached.
    let store_key = match lookup {
        CdnLookup::Absent if cdn_cacheable(body.len()) && !prepared_is_lazy => key,
        _ => None,
    };

    if budget.exhausted() || outcome.elapsed >= compute_budget() {
        outcome
            .errors
            .push(format!("{name}: skipped, page JS budget exhausted"));
        return;
    }
    // A raw-parse error from the worker pool surfaces exactly like a
    // `Script::parse` error inside `run_script`.
    let prepared = match prepared {
        Some(Ok(raw)) => Some(raw),
        Some(Err(err)) => {
            outcome.errors.push(format!("{name}: {err}"));
            return;
        }
        None => None,
    };
    let started = Instant::now();
    let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(move || {
        // Suppress TRust lazy parsing + compilation when this compile's result
        // will be dehydrated into the CDN image cache — a cached image cannot
        // carry a lazy stub (a skipped/deferred body). `store_key.is_some()`
        // already implies the worker (if any) parsed this eagerly
        // (`cdn_cache_candidate` kept it off the lazy path AND `!prepared_is_lazy`
        // gates the store), so this guard governs the page-thread compile:
        // `compile_raw` no longer self-suppresses, so the guard suppresses its
        // deferral here, and the inline branch parses + compiles eagerly. A
        // non-candidate (uncached) external still lazily parses/compiles —
        // delazify re-parses from the retained span, so no interner is needed.
        let _no_lazy = store_key.is_some().then(boa_engine::vm::lazy::suppress);
        let _no_lazy_parse = store_key.is_some().then(boa_parser::lazy::suppress);
        // Obtain the compiled script: either compile the worker's raw parse
        // (parse was off-thread; `compile_raw` does scope-analysis + bytecode,
        // charged to Compile), or parse + compile inline.
        let script = match prepared {
            Some(raw) => {
                let t = phase_begin();
                let s = boa_engine::Script::compile_raw(raw, None, ctx)?;
                phase_end(Phase::Compile, t);
                s
            }
            None => {
                let src = Source::from_bytes(body).with_path(std::path::Path::new(name));
                let t = phase_begin();
                let s = boa_engine::Script::parse(src, None, ctx)?;
                phase_end(Phase::Parse, t);
                let t = phase_begin();
                s.codeblock(ctx)?;
                phase_end(Phase::Compile, t);
                s
            }
        };
        // Realm-portability gate: cache the detached image only when the script
        // neither creates nor reads a global-declarative binding (so its block
        // runs identically on any page). `codeblock` is memoized — no recompile.
        if let Some(key) = store_key {
            let cb = script.codeblock(ctx)?;
            let reusable = script.global_declarations_are_replayable() && cb.is_realm_portable();
            phase(&format!(
                "cdn cache store {name} ({})",
                if reusable { "reusable" } else { "not reusable" }
            ));
            let (entry, bytes) = if reusable {
                // Source length is the proxy for the image's resident footprint.
                (
                    CdnEntry::Reusable(std::sync::Arc::new(cb.to_image())),
                    body.len(),
                )
            } else {
                (CdnEntry::NotReusable, 0)
            };
            cdn_cache_put(key, entry, bytes);
        }
        let t = phase_begin();
        let r = script.evaluate(ctx);
        phase_end(Phase::Execute, t);
        r
    }));
    match result {
        Ok(Ok(_)) => {}
        Ok(Err(err)) => record_task_error(outcome, name, err),
        Err(_) => {
            outcome
                .errors
                .push(format!("{name}: engine panic (Boa bug) — page JS halted"));
            outcome.panicked = true;
        }
    }
    outcome.elapsed += started.elapsed();
}

/// Replace `document.currentScript` (via the `__trust` bridge, like
/// `readyState`) and return the previous node id. HTML's script-element
/// execution algorithm restores the old value rather than blindly clearing
/// it: reentrant classic-script execution must reveal the innermost script and
/// then expose its caller again when it finishes.
fn replace_current_script(ctx: &mut Context, id: Option<usize>) -> Option<usize> {
    let next = id.map_or_else(|| String::from("null"), |id| id.to_string());
    let src = format!(
        "(function(){{var old=__trust.currentScript;__trust.currentScript={next};return old;}})()"
    );
    ctx.eval(Source::from_bytes(src.as_bytes()))
        .ok()
        .and_then(|v| v.as_number())
        .filter(|n| n.is_finite() && *n >= 0.0)
        .map(|n| n as usize)
}

/// The microtask checkpoint nested inside HTML's "run a classic script".
/// This deliberately excludes `NativeAsyncJob`s: those represent later host
/// work (network/resource completion), not microtasks belonging to the active
/// script evaluation.
fn microtask_checkpoint(ctx: &mut Context) -> JsResult<()> {
    ctx.downcast_job_executor::<PageJobExecutor>()
        .expect("page contexts use PageJobExecutor")
        .run_microtask_checkpoint(ctx)
}

// ---- The DOM syscall boundary ----------------------------------------
//
// The arena lives in Rust; JS sees nodes as bare integer ids. A thin set
// of `__dom_*` globals is the entire Rust↔JS surface — flat, typed, no
// GC entanglement — and the DOM API shape (prototypes, getters, events,
// timers) is built *in JavaScript* by PRELUDE on top of them. The win is
// keeping the arena out of Boa's GC (nodes never become GC objects) and
// writing the platform concisely in the language it's specced in — NOT
// engine portability (Boa is the engine for this legacy backend; a showstopper
// means forking it).

/// The page's arena, shared with syscalls through the context's
/// host-defined storage.
#[derive(boa_engine::JsData)]
struct PageDom(Rc<RefCell<Dom>>);

impl boa_engine::gc::Finalize for PageDom {}
// SAFETY: holds no GC-managed objects.
unsafe impl boa_engine::gc::Trace for PageDom {
    boa_engine::gc::empty_trace!();
}

/// Session-lifetime, RAM-only web storage: origin-bucketed key/value
/// maps shared across pages, dead with the process — never disk.
pub type WebStorage = std::sync::Arc<
    std::sync::Mutex<std::collections::HashMap<String, std::collections::HashMap<String, String>>>,
>;

/// The Send-able result of a BACKGROUND fetch (a dispatch/at-rest `fetch()` or
/// async XHR), posted back to the actor to settle the JS promise without the
/// dispatch ever blocking on the wire. `(status, content_type, body)` on
/// success; `None` on failure (the prelude turns a null resolution into a
/// rejected fetch / failed XHR, matching the sync syscall's contract).
type FetchResult = Option<(u16, String, Vec<u8>, String)>;
/// Channel a background fetch task posts its `(promise id, result)` back on.
type FetchSender = tokio::sync::mpsc::Sender<(usize, FetchResult)>;

/// A dynamically prepared resource completes on the networking task source,
/// then its response is consumed by the resident page actor. Keeping the
/// response data (rather than a JS closure or Boa value) on the channel keeps
/// the JS realm single-threaded while allowing the wire to progress without
/// blocking user-interaction tasks.
type ResourceResult = Option<(u16, String, Vec<u8>, Vec<(String, String)>)>;

#[derive(Clone, Copy)]
enum ResourceKind {
    ClassicScript,
    ModuleScript,
    Stylesheet,
}

struct ResourceEvent {
    node_id: usize,
    name: String,
    kind: ResourceKind,
    result: ResourceResult,
    delays_load: bool,
}

type ResourceSender = tokio::sync::mpsc::Sender<ResourceEvent>;
/// Host pieces needed to turn a resident-page fetch into a later networking
/// task without retaining any GC-managed value across threads.
type BackgroundFetchContext = (
    usize,
    FetchSender,
    tokio::runtime::Handle,
    std::sync::Arc<crate::http::PageCache>,
    std::sync::Arc<std::sync::atomic::AtomicUsize>,
);

/// Web Workers (HTML §"Workers"). A `Worker` is a second JS engine running on
/// its own dedicated `trust-worker-N` OS thread (Boa's `Context` is `!Send`, so
/// there is no shared JS heap — and thus no cross-thread GC). The page and the
/// worker exchange STRUCTURED-CLONE-serialized messages over channels, exactly
/// like the WebSocket task exchanges frames (`PageWs`/`PageCmd::Ws`).
///
/// A message the worker posts back to the page (`self.postMessage`), or an
/// uncaught error in the worker. Both ride the `(worker id, WorkerOut)` channel
/// that the page actor's forwarder turns into `PageCmd::Worker`.
#[derive(Debug)]
pub enum WorkerOut {
    /// Structured-clone wire string (the `__sc_serialize` format).
    Message(String),
    /// An uncaught error in the worker → fire `error` on the page-side Worker.
    Error(String),
}

/// A control message the page sends INTO a worker (page→worker direction).
enum WorkerCtl {
    /// A `worker.postMessage(...)` — structured-clone wire string.
    Message(String),
    /// `worker.terminate()` — the worker loop breaks and the thread exits.
    Terminate,
}

/// Classic vs module worker (`new Worker(url, { type })`). v1 runs classic; a
/// module worker is recognized but loads its entry as a classic script for now
/// (module-graph-in-worker is the immediate fast-follow — see the roadmap memo).
#[derive(Clone, Copy, PartialEq, Eq)]
enum WorkerKind {
    Classic,
    Module,
}

struct WorkerLaunch {
    id: usize,
    script_url: url::Url,
    kind: WorkerKind,
    name: String,
    /// A script fetched from the page's same-partition Blob URL store. The
    /// HTML Worker algorithm fetches `blob:` URLs through the File API store,
    /// rather than through the HTTP client. `None` keeps the normal HTTP(S)
    /// fetch path.
    script_body: Option<Vec<u8>>,
    secure_context: bool,
}

/// Channel the worker threads post `(worker id, WorkerOut)` back on; the page
/// actor's forwarder relays each as a `PageCmd::Worker`.
type WorkerSender = tokio::sync::mpsc::Sender<(usize, WorkerOut)>;

/// Per-page lid on concurrent workers (a hostile page can't spawn threads
/// without bound). A real browser has no fixed cap, but each worker is a 64MB
/// thread + engine here, so this is the resource guard, not a spec limit.
const MAX_WORKERS: usize = 16;

/// Network access for page JS: requests run on the app's tokio runtime
/// from the JS thread, metered and capped. No CORS theater — there are
/// no cookies or ambient credentials to protect; the real boundary is
/// `http::subresource_allowed` (no private-address pivots) plus caps.
#[derive(boa_engine::JsData)]
struct PageNet {
    handle: tokio::runtime::Handle,
    page: url::Url,
    budget: Rc<Budget>,
    fetched: std::cell::Cell<usize>,
    /// Background-fetch result channel + id counter (resident actor only). A
    /// dispatch/at-rest `fetch()` spawns a task that sends `(id, result)` here;
    /// the actor settles promise `id` and re-renders.
    fetch_events: Option<FetchSender>,
    next_fetch_id: std::cell::Cell<usize>,
    /// Resident requests whose networking task has not posted its result yet.
    /// The initial actor classification keeps an otherwise inert document live
    /// while this is nonzero, so an async-only page can receive its result.
    pending_fetches: std::sync::Arc<std::sync::atomic::AtomicUsize>,
    /// Dynamically prepared scripts/styles use a separate networking-task
    /// lane. Their results are delivered to the actor without putting a
    /// network future in Boa's JS-thread-owned job executor.
    resource_events: Option<ResourceSender>,
    pending_resources: std::sync::Arc<std::sync::atomic::AtomicUsize>,
    pending_load_resources: std::sync::Arc<std::sync::atomic::AtomicUsize>,
    /// Separate from `dispatch`: a user interaction can occur while the
    /// initial load event is still delayed, and resources it prepares must
    /// remain load blockers until the browser-owned load task runs.
    load_complete: std::cell::Cell<bool>,
    /// The shared subresource cache, so the page's own `fetch()` can join
    /// an in-flight/done request for a chunk we already have.
    cache: std::sync::Arc<crate::http::PageCache>,
}

impl boa_engine::gc::Finalize for PageNet {}
// SAFETY: holds no GC-managed objects.
unsafe impl boa_engine::gc::Trace for PageNet {
    boa_engine::gc::empty_trace!();
}

/// Page-owned WebSockets (see `ws.rs`) — the transport socket.io rides. Each
/// `new WebSocket()` spawns a connection task; this maps the JS-visible id to
/// that task's outbound sender, and hands every task a clone of `events` so
/// inbound frames/open/close reach the actor (forwarded as `PageCmd::Ws`,
/// dispatched like a click). RAM-only, dies with the page, which drops the
/// senders → the tasks close their sockets and exit.
#[derive(boa_engine::JsData)]
struct PageWs {
    handle: tokio::runtime::Handle,
    page: url::Url,
    tasks: std::sync::Arc<crate::http::PageTaskScope>,
    events: tokio::sync::mpsc::Sender<(usize, crate::ws::WsIn)>,
    sockets: RefCell<std::collections::HashMap<usize, tokio::sync::mpsc::Sender<crate::ws::WsOut>>>,
    next_id: std::cell::Cell<usize>,
}

impl boa_engine::gc::Finalize for PageWs {}
// SAFETY: holds no GC-managed objects (channels/handle/url/RefCell map).
unsafe impl boa_engine::gc::Trace for PageWs {
    boa_engine::gc::empty_trace!();
}

/// The page-side registry of live `Worker`s (host object in the PAGE context).
/// `__worker_spawn` resolves+guards the script URL, spawns a `trust-worker-N`
/// thread, and records its control channel here. `__worker_post`/`_terminate`
/// look the worker up by id. When the page actor exits, the context — and hence
/// this struct and its `workers` map — drops; dropping a `WorkerHandle` closes
/// that worker's control channel, so the worker's event loop sees `None` and the
/// thread exits cleanly (no join needed, no leaked threads).
#[derive(boa_engine::JsData)]
struct PageWorkers {
    handle: tokio::runtime::Handle,
    page: url::Url,
    tasks: std::sync::Arc<crate::http::PageTaskScope>,
    /// Cloned into each worker's `WorkerSelf` so `self.postMessage`/errors reach
    /// the actor (forwarded as `PageCmd::Worker`).
    events: WorkerSender,
    workers: RefCell<std::collections::HashMap<usize, WorkerHandle>>,
    next_id: std::cell::Cell<usize>,
}

/// One live worker's page-side handle: the control channel into the worker
/// thread. Dropping it closes the channel → the worker exits.
struct WorkerHandle {
    ctl: tokio::sync::mpsc::Sender<WorkerCtl>,
    runtime_interrupt: std::sync::Arc<boa_engine::vm::RuntimeInterrupt>,
}

impl Drop for WorkerHandle {
    fn drop(&mut self) {
        // HTML §10.2.3 "terminate a worker" runs in parallel with the worker
        // main loop and aborts the script currently running there. Closing the
        // control channel only handles a parked worker; the VM interrupt also
        // reaches one that is currently executing author code.
        self.runtime_interrupt.cancel();
    }
}

impl boa_engine::gc::Finalize for PageWorkers {}
// SAFETY: holds no GC-managed objects (channels/handle/url/RefCell map).
unsafe impl boa_engine::gc::Trace for PageWorkers {
    boa_engine::gc::empty_trace!();
}

/// The worker-side self handle (host object in a WORKER context): how a worker's
/// own `self.postMessage`/`close` reach back to the page. `closed` is set by
/// `__worker_self_close` and read by the worker's event loop to exit.
#[derive(boa_engine::JsData)]
struct WorkerSelf {
    id: usize,
    to_page: WorkerSender,
    closed: std::cell::Cell<bool>,
}

impl boa_engine::gc::Finalize for WorkerSelf {}
// SAFETY: holds no GC-managed objects (id/channel/Cell).
unsafe impl boa_engine::gc::Trace for WorkerSelf {
    boa_engine::gc::empty_trace!();
}

/// The storage syscalls' view: the shared map plus this page's origin.
#[derive(boa_engine::JsData)]
struct PageStore {
    map: WebStorage,
    origin: String,
}

impl boa_engine::gc::Finalize for PageStore {}
// SAFETY: holds no GC-managed objects.
unsafe impl boa_engine::gc::Trace for PageStore {
    boa_engine::gc::empty_trace!();
}

/// Rust-side mirror of the page's minted `blob:` URLs → `(bytes, MIME type)`.
/// The JS realm owns the AUTHORITATIVE store (`__blobURLStore`, File API);
/// this mirror exists so the APP — outside the JS thread — can decode an
/// `<img src="blob:…">` (Steam's login QR is a client-generated blob image).
/// Entries are never removed on revoke: revocation only blocks NEW page-side
/// fetches (File API: a load already started keeps its resource), and the
/// renderer may re-decode a displayed blob image long after the page revoked
/// its URL (resize, scroll back). Page-lifetime, RAM-only — the map dies with
/// the `Doc`/history entry that carries it.
pub type BlobMap =
    std::sync::Arc<std::sync::Mutex<std::collections::HashMap<String, (Vec<u8>, String)>>>;

/// Host-defined carrier for the blob mirror (`__blob_mirror` writes to it).
#[derive(boa_engine::JsData)]
struct PageBlobs(BlobMap);

impl boa_engine::gc::Finalize for PageBlobs {}
// SAFETY: holds no GC-managed objects.
unsafe impl boa_engine::gc::Trace for PageBlobs {
    boa_engine::gc::empty_trace!();
}

/// The geometry cache: the DOM epoch it was built for, each element's pixel box
/// keyed by node, and (layout2 only) each grid container's used track sizes in
/// px `(columns, rows)` — the CSSOM resolved value for `grid-template-columns`/
/// `-rows` — and each scroll container's scrolling-area rectangle. ONE layout
/// pass fills all three, reused until the next mutation. Stale
/// (epoch mismatch) entries rebuild lazily on the next `__dom_rect`/
/// `__dom_computed` read — free for pages that never measure.
type GeomCache = (
    u64,
    std::collections::HashMap<crate::dom::NodeId, crate::layout2::PxRect>,
    std::collections::HashMap<crate::dom::NodeId, (Vec<f32>, Vec<f32>)>,
    std::collections::HashMap<crate::dom::NodeId, crate::layout2::PxRect>,
);

/// Backing for the JS geometry APIs (`getBoundingClientRect`, `offset*`/
/// `client*`, IntersectionObserver/ResizeObserver). Holds the immutable layout
/// inputs the measure pass needs (the page base and CSS-pixel viewport) plus
/// the lazily built, epoch-keyed box map. See `sys_rect` and
/// `layout2::measure_boxes_css`.
#[derive(boa_engine::JsData)]
struct PageGeom {
    base: url::Url,
    /// The current initial containing block in CSS pixels. The frontend pushes
    /// the true content viewport once displayed and on resize. Device scale and
    /// terminal cell geometry are resolved before this boundary.
    viewport: std::cell::Cell<crate::layout2::Viewport>,
    /// Output-device density for HTML's source-candidate selection only.
    device_pixel_ratio: std::cell::Cell<f32>,
    cache: Rc<RefCell<GeomCache>>,
    /// Decoded image intrinsic sizes (URL → intrinsic CSS/image pixels), pushed
    /// by the app as
    /// its image pipeline finishes (`PageCmd::ImageSizes`). The measure pass
    /// lays images from these exactly like the app's render does, so the
    /// geometry JS reads matches the page on screen (CSSOM View reports the
    /// actual rendered layout — a virtualized feed caches these heights and
    /// feeds them back as placeholder sizes, so a divergence reshapes the
    /// document under the reader). Sparse before decodes arrive.
    images: Rc<RefCell<crate::layout2::ImageSizes>>,
}

impl boa_engine::gc::Finalize for PageGeom {}
// SAFETY: holds no GC-managed objects.
unsafe impl boa_engine::gc::Trace for PageGeom {
    boa_engine::gc::empty_trace!();
}

/// WebAssembly engine state for one page. Lazily created on the first
/// `WebAssembly.*` use, so a page that never touches wasm pays nothing.
///
/// The JS-API spec gives each agent ONE abstract store; cross-instance imports
/// (instance A's memory imported by instance B) must share a wasmi `Store`, so
/// a single engine + single store per page is both correct and necessary
/// (added from Stage 2). The keystone design choice: **every JS value stays in
/// JS-land** — imports, externref identities, and wrapper caches live in prelude
/// objects (rooted by the realm); Rust holds only the wasmi handles, addressed
/// by the integer ids the prelude classes carry. So `PageWasm` owns no `JsValue`
/// and its `Trace` is empty, exactly like `PageStore`.
struct WasmState {
    /// The page's wasm engine. `wasmi::Engine` is cheap to clone (an `Arc`
    /// inside); compiled `Module`s and the `Store` bind to it.
    engine: wasmi::Engine,
    /// The page's single wasm store (the spec's per-agent abstract store) — all
    /// instances, funcs, memories, tables, and globals live in it, so externals
    /// of one instance can be imported by another.
    store: wasmi::Store<()>,
    /// Compiled modules, addressed by index — the JS `Module`'s `__id`.
    modules: Vec<wasmi::Module>,
    /// Instantiated instances, addressed by index — the JS `Instance`'s `__id`.
    instances: Vec<wasmi::Instance>,
    /// Exported/host funcs, addressed by index — the handle an Exported Function
    /// JS wrapper carries (`__wasm_call_export` looks the `Func` up here).
    funcs: Vec<wasmi::Func>,
    /// Globals (constructed, exported, or imported), addressed by index — the
    /// handle a `WebAssembly.Global` JS wrapper carries.
    globals: Vec<wasmi::Global>,
    /// Memories, addressed by index — the handle a `WebAssembly.Memory` JS
    /// wrapper carries. `last_pages` tracks the size the current `Memory.buffer`
    /// was built for, so a grow (explicit or inside a call) is detected and the
    /// stale buffer detached.
    memories: Vec<MemorySlot>,
    /// Tables, addressed by index — the handle a `WebAssembly.Table` JS wrapper
    /// carries.
    tables: Vec<wasmi::Table>,
}

/// A wasm memory plus the page count its currently-exposed buffer reflects.
struct MemorySlot {
    mem: wasmi::Memory,
    last_pages: u64,
}

impl WasmState {
    fn new() -> Self {
        let engine = wasmi::Engine::default();
        let store = wasmi::Store::new(&engine, ());
        WasmState {
            engine,
            store,
            modules: Vec::new(),
            instances: Vec::new(),
            funcs: Vec::new(),
            globals: Vec::new(),
            memories: Vec::new(),
            tables: Vec::new(),
        }
    }

    fn register_func(&mut self, value: wasmi::Func) -> usize {
        if let Some(index) = self.funcs.iter().position(|candidate| *candidate == value) {
            return index;
        }
        let index = self.funcs.len();
        self.funcs.push(value);
        index
    }

    fn register_global(&mut self, value: wasmi::Global) -> usize {
        if let Some(index) = self
            .globals
            .iter()
            .position(|candidate| *candidate == value)
        {
            return index;
        }
        let index = self.globals.len();
        self.globals.push(value);
        index
    }

    fn register_memory(&mut self, value: wasmi::Memory) -> usize {
        if let Some(index) = self
            .memories
            .iter()
            .position(|candidate| candidate.mem == value)
        {
            return index;
        }
        let index = self.memories.len();
        self.memories.push(MemorySlot {
            mem: value,
            last_pages: value.size(&self.store),
        });
        index
    }

    fn register_table(&mut self, value: wasmi::Table) -> usize {
        if let Some(index) = self.tables.iter().position(|candidate| *candidate == value) {
            return index;
        }
        let index = self.tables.len();
        self.tables.push(value);
        index
    }
}

/// The wasm state is held behind an `Rc` so a syscall that EXECUTES wasm
/// (`instantiate`'s start function, `call_export`) can clone the handle out of
/// `host_defined` and then release the `ctx` borrow before running — exactly the
/// `page_dom` pattern. That matters because a host-import callback re-enters JS
/// through `ctx`, so no `ctx` borrow may be held across wasm execution.
#[derive(boa_engine::JsData)]
struct PageWasm {
    /// The wasm engine + registries. A wasm-executing syscall clones this `Rc`
    /// and releases the `ctx` borrow before running.
    state: Rc<RefCell<Option<WasmState>>>,
    /// The live `Memory.buffer` object per memory id (a zero-copy external
    /// `ArrayBuffer` over wasm linear memory). Kept OUTSIDE `state` so GC can
    /// trace these objects even while a wasm call holds `state` borrowed;
    /// detached + rebuilt whenever the memory grows. See Stage 5.
    buffers: Rc<RefCell<Vec<Option<boa_engine::JsObject>>>>,
}

impl PageWasm {
    fn new() -> Self {
        PageWasm {
            state: Rc::new(RefCell::new(None)),
            buffers: Rc::new(RefCell::new(Vec::new())),
        }
    }

    /// The shared state cell (for the execute-wasm syscalls — clone it, drop the
    /// `ctx` borrow, then operate).
    fn cell(&self) -> Rc<RefCell<Option<WasmState>>> {
        self.state.clone()
    }

    /// The shared `Memory.buffer` handle map (memory id → current buffer object).
    fn buffers(&self) -> Rc<RefCell<Vec<Option<boa_engine::JsObject>>>> {
        self.buffers.clone()
    }

    /// Run `f` against the page's wasm state, creating it on first use. Holds the
    /// interior `RefCell` borrow for the duration of `f`, so `f` must NOT execute
    /// wasm (which can re-enter via a host import). Used by the non-executing
    /// syscalls (validate/compile/introspection/export-listing).
    fn with<R>(&self, f: impl FnOnce(&mut WasmState) -> R) -> R {
        let mut slot = self.state.borrow_mut();
        f(slot.get_or_insert_with(WasmState::new))
    }
}

impl boa_engine::gc::Finalize for PageWasm {}
// SAFETY: `state` holds only wasmi handles (no GC objects); the only GC-managed
// values are the `Memory.buffer` objects in `buffers`, traced here. `buffers` is
// never borrowed across a point that can trigger GC (a wasm call holds `state`,
// not `buffers`), so the `try_borrow` always succeeds when it matters.
unsafe impl boa_engine::gc::Trace for PageWasm {
    boa_engine::gc::custom_trace!(this, mark, {
        if let Ok(bufs) = this.buffers.try_borrow() {
            for b in bufs.iter().flatten() {
                mark(b);
            }
        }
    });
}

/// Clone out the page's wasm state cell (releasing the `ctx`/`host_defined`
/// borrow), for the syscalls that execute wasm.
fn page_wasm_cell(ctx: &mut Context) -> Option<Rc<RefCell<Option<WasmState>>>> {
    ctx.realm()
        .host_defined()
        .get::<PageWasm>()
        .map(PageWasm::cell)
}

/// Clone out the page's `Memory.buffer` handle map.
fn page_wasm_buffers(ctx: &mut Context) -> Option<Rc<RefCell<Vec<Option<boa_engine::JsObject>>>>> {
    ctx.realm()
        .host_defined()
        .get::<PageWasm>()
        .map(PageWasm::buffers)
}

thread_local! {
    /// The page `Context` while a wasm call runs, so a host-import closure can
    /// call back into JS. Single-threaded; the initiating syscall's `&mut
    /// Context` is dormant during wasmi execution (no `ctx`/`host_defined` borrow
    /// is held across the call — see `PageWasm`'s `Rc`), so reconstructing
    /// `&mut Context` from this pointer aliases only that dormant borrow.
    static WASM_CTX: std::cell::Cell<*mut Context> =
        const { std::cell::Cell::new(std::ptr::null_mut()) };
    /// A JS exception thrown by a host import, carried across the wasmi unwind so
    /// the call site can re-throw the ORIGINAL value (js-api). Taken right after
    /// the call returns — no GC runs during the synchronous Rust unwind.
    static WASM_PENDING: RefCell<Option<boa_engine::JsError>> = const { RefCell::new(None) };
    /// The Wasm state currently executing a core start function or exported
    /// function. Host imports receive a `wasmi::Caller`, which is the only
    /// valid way to touch the associated store while the outer state borrow is
    /// suspended. The raw pointer is used only while that outer borrow is
    /// dormant, to copy stable wasmi handles and register funcref handles read
    /// by a nested JS call.
    static WASM_ACTIVE_STATE: Cell<*mut WasmState> =
        const { Cell::new(std::ptr::null_mut()) };
    /// The active wasmi host-import caller. Its lifetime is limited to the
    /// callback invocation; the erased raw pointer is restored by the guard
    /// before the callback returns.
    static WASM_CALLER: Cell<*mut wasmi::Caller<'static, ()>> =
        const { Cell::new(std::ptr::null_mut()) };
}

/// Sets `WASM_CTX` for the duration of a wasm call and restores the previous
/// value on drop (so nested set/restore is correct even though re-entrant wasm
/// calls are themselves rejected).
struct WasmCtxGuard(*mut Context);
impl WasmCtxGuard {
    fn set(ctx: &mut Context) -> Self {
        let prev = WASM_CTX.with(|c| c.replace(ctx as *mut Context));
        WASM_PENDING.with(|p| *p.borrow_mut() = None);
        WasmCtxGuard(prev)
    }
}
impl Drop for WasmCtxGuard {
    fn drop(&mut self) {
        WASM_CTX.with(|c| c.set(self.0));
    }
}

/// Makes the currently executing state discoverable by WebAssembly JS-API
/// syscalls invoked from a host import. This follows the WebAssembly JS
/// Interface's associated-store rules: a host callback does not create a new
/// store, and `Table.grow` must update the same store and return its old size.
/// See WebAssembly JS Interface §§ 5.2 (instantiation) and 5.4 (Table objects).
struct WasmStateGuard(*mut WasmState);
impl WasmStateGuard {
    fn set(state: &mut WasmState) -> Self {
        let prev = WASM_ACTIVE_STATE.with(|s| s.replace(state as *mut WasmState));
        Self(prev)
    }
}
impl Drop for WasmStateGuard {
    fn drop(&mut self) {
        WASM_ACTIVE_STATE.with(|s| s.set(self.0));
    }
}

/// Exposes wasmi's `Caller` to the JS syscall reached by the host import. The
/// pointer is valid only until `make_import_func` returns; nested guards make
/// the arrangement safe for nested JS callbacks on the same page actor.
struct WasmCallerGuard(*mut wasmi::Caller<'static, ()>);
impl WasmCallerGuard {
    fn set(caller: &mut wasmi::Caller<'_, ()>) -> Self {
        // The pointer never escapes this synchronous host-import callback;
        // erase only the borrow lifetime so the thread-local guard can carry
        // it to the JS syscall and restore it before returning.
        let ptr = unsafe {
            std::mem::transmute::<*mut wasmi::Caller<'_, ()>, *mut wasmi::Caller<'static, ()>>(
                std::ptr::from_mut(caller),
            )
        };
        let prev = WASM_CALLER.with(|c| c.replace(ptr));
        Self(prev)
    }
}
impl Drop for WasmCallerGuard {
    fn drop(&mut self) {
        WASM_CALLER.with(|c| c.set(self.0));
    }
}

fn active_wasm_table(id: usize) -> Option<wasmi::Table> {
    WASM_ACTIVE_STATE.with(|s| {
        let ptr = s.get();
        (!ptr.is_null())
            .then(|| unsafe { (&*std::ptr::addr_of!((*ptr).tables)).get(id).copied() })?
    })
}

fn active_wasm_func(id: usize) -> Option<wasmi::Func> {
    WASM_ACTIVE_STATE.with(|s| {
        let ptr = s.get();
        (!ptr.is_null())
            .then(|| unsafe { (&*std::ptr::addr_of!((*ptr).funcs)).get(id).copied() })?
    })
}

/// Register a funcref read through an active host-import caller. The registry
/// is not borrowed by wasmi while the callback is running; only the copied
/// handle is used by the nested JS wrapper after this push.
fn active_wasm_register_func(func: wasmi::Func) -> Option<usize> {
    WASM_ACTIVE_STATE.with(|s| {
        let ptr = s.get();
        (!ptr.is_null()).then(|| unsafe { (*ptr).register_func(func) })
    })
}

fn with_active_wasm_caller<R>(f: impl FnOnce(&mut wasmi::Caller<'static, ()>) -> R) -> Option<R> {
    WASM_CALLER.with(|c| {
        let ptr = c.get();
        (!ptr.is_null()).then(|| unsafe { f(&mut *ptr) })
    })
}

fn active_wasm_table_element(id: usize) -> Option<wasmi::ValType> {
    let table = active_wasm_table(id)?;
    with_active_wasm_caller(|caller| table.ty(&*caller).element())
}

fn active_wasm_table_size(id: usize) -> Option<u64> {
    let table = active_wasm_table(id)?;
    with_active_wasm_caller(|caller| table.size(&*caller))
}

/// The wasmi error a host-import closure returns to unwind the call after it has
/// stashed the real JS exception in `WASM_PENDING`.
fn wasm_host_trap() -> wasmi::Error {
    wasmi::Error::new("WebAssembly host import raised a JS exception")
}

/// Invoke the prelude import dispatcher `__wasm_invoke_import(token, index,
/// argsArray)`, which applies the JS import function the page supplied.
fn invoke_js_import(
    ctx: &mut Context,
    token: u32,
    index: u32,
    js_args: Vec<JsValue>,
) -> JsResult<JsValue> {
    let dispatcher = ctx
        .global_object()
        .get(boa_engine::js_string!("__wasm_invoke_import"), ctx)?;
    let Some(callable) = dispatcher.as_callable() else {
        return Err(boa_engine::JsNativeError::typ()
            .with_message("WebAssembly: import dispatcher missing")
            .into());
    };
    let args_arr: JsValue = JsArray::from_iter(js_args, ctx).into();
    callable.call(
        &JsValue::undefined(),
        &[JsValue::from(token), JsValue::from(index), args_arr],
        ctx,
    )
}

/// Convert a host import's JS return value into the wasm result slots
/// (`ToWebAssemblyValue` per result type): 0 results ignore the value, 1 result
/// converts it, N results read an array-like of length N.
fn write_import_results(
    ctx: &mut Context,
    ret: &JsValue,
    results: &[wasmi::ValType],
    outs: &mut [wasmi::Val],
) -> JsResult<()> {
    match results.len() {
        0 => {}
        1 => outs[0] = js_to_wasm(ctx, ret, results[0])?,
        n => {
            let arr = ret
                .as_object()
                .and_then(|o| JsArray::from_object(o).ok())
                .ok_or_else(|| {
                    boa_engine::JsNativeError::typ()
                        .with_message("WebAssembly: a multi-value import must return an array")
                })?;
            for (i, ty) in results.iter().enumerate().take(n) {
                let v = arr
                    .at(i as i64, ctx)
                    .unwrap_or_else(|_| JsValue::undefined());
                outs[i] = js_to_wasm(ctx, &v, *ty)?;
            }
        }
    }
    Ok(())
}

/// Build a wasmi host function that forwards calls to the JS import at
/// `(token, index)`. The closure is `Send + Sync + 'static`: it captures only
/// the integer ids and the result types, reads the live `Context` from
/// `WASM_CTX`, and stashes any JS exception in `WASM_PENDING` before trapping so
/// the call site can re-throw the original value.
fn make_import_func(
    store: &mut wasmi::Store<()>,
    ft: wasmi::FuncType,
    token: u32,
    index: u32,
) -> wasmi::Func {
    let results: Vec<wasmi::ValType> = ft.results().to_vec();
    wasmi::Func::new(store, ft, move |mut caller, params, outs| {
        let ctx_ptr = WASM_CTX.with(|c| c.get());
        if ctx_ptr.is_null() {
            return Err(wasmi::Error::new(
                "WebAssembly host call outside a JS context",
            ));
        }
        // SAFETY: single-threaded page actor; the syscall that entered wasm holds
        // no live borrow of its `&mut Context` during execution (the wasm state
        // is reached via a separate `Rc`), so this is the only active reference.
        let ctx = unsafe { &mut *ctx_ptr };
        let mut js_args = Vec::with_capacity(params.len());
        for p in params.iter() {
            match wasm_to_js(p) {
                Ok(v) => js_args.push(v),
                Err(e) => {
                    WASM_PENDING.with(|c| *c.borrow_mut() = Some(e));
                    return Err(wasm_host_trap());
                }
            }
        }
        // Keep the Caller alive through result conversion too: ToWebAssemblyValue
        // can execute user JavaScript, which may use the same Table/Memory API.
        let _caller_guard = WasmCallerGuard::set(&mut caller);
        match invoke_js_import(ctx, token, index, js_args)
            .and_then(|ret| write_import_results(ctx, &ret, &results, outs))
        {
            Ok(()) => Ok(()),
            Err(e) => {
                WASM_PENDING.with(|c| *c.borrow_mut() = Some(e));
                Err(wasm_host_trap())
            }
        }
    })
}

/// JS-API import/export `kind` string for a wasm extern type.
fn wasm_extern_kind(ty: &wasmi::ExternType) -> &'static str {
    match ty {
        wasmi::ExternType::Func(_) => "function",
        wasmi::ExternType::Table(_) => "table",
        wasmi::ExternType::Memory(_) => "memory",
        wasmi::ExternType::Global(_) => "global",
    }
}

/// Parse a JS-API value-type string (`Global`/`Table` descriptors) into a wasm
/// `ValType`. `anyfunc` is the historical spelling of `funcref` (js-api).
fn valtype_from_str(s: &str) -> Option<wasmi::ValType> {
    match s {
        "i32" => Some(wasmi::ValType::I32),
        "i64" => Some(wasmi::ValType::I64),
        "f32" => Some(wasmi::ValType::F32),
        "f64" => Some(wasmi::ValType::F64),
        "v128" => Some(wasmi::ValType::V128),
        "externref" => Some(wasmi::ValType::ExternRef),
        "anyfunc" | "funcref" => Some(wasmi::ValType::FuncRef),
        _ => None,
    }
}

/// `ToWebAssemblyValue(v, type)` (js-api): convert a JS value to a wasm `Val`.
/// i32 = ToInt32, i64 = ToBigInt then to a 64-bit int, f32/f64 = ToNumber.
/// v128 is rejected before any call reaches here (a signature containing it
/// throws TypeError up front); reference types arrive in Stage 6.
fn js_to_wasm(ctx: &mut Context, v: &JsValue, ty: wasmi::ValType) -> JsResult<wasmi::Val> {
    Ok(match ty {
        wasmi::ValType::I32 => wasmi::Val::I32(v.to_i32(ctx)?),
        wasmi::ValType::I64 => wasmi::Val::I64(v.to_big_int64(ctx)?),
        wasmi::ValType::F32 => wasmi::Val::F32(wasmi::F32::from(v.to_number(ctx)? as f32)),
        wasmi::ValType::F64 => wasmi::Val::F64(wasmi::F64::from(v.to_number(ctx)?)),
        wasmi::ValType::V128 | wasmi::ValType::FuncRef | wasmi::ValType::ExternRef => {
            return Err(boa_engine::JsNativeError::typ()
                .with_message("WebAssembly: unsupported value type at the JS boundary")
                .into());
        }
    })
}

/// `ToJSValue(w)` (js-api): convert a wasm `Val` to a JS value. i32/f32/f64 →
/// Number, i64 → BigInt. v128 returning to JS is a TypeError (callers reject
/// such signatures first, so that arm is defensive); reference types in Stage 6.
fn wasm_to_js(v: &wasmi::Val) -> JsResult<JsValue> {
    Ok(match v {
        wasmi::Val::I32(x) => JsValue::from(*x),
        wasmi::Val::I64(x) => JsValue::from(boa_engine::JsBigInt::from(*x)),
        wasmi::Val::F32(x) => JsValue::from(x.to_float() as f64),
        wasmi::Val::F64(x) => JsValue::from(x.to_float()),
        _ => {
            return Err(boa_engine::JsNativeError::typ()
                .with_message("WebAssembly: unsupported result type at the JS boundary")
                .into());
        }
    })
}

/// Classify a wasmi instantiate/call error for the prelude error envelope: a
/// trap → `RuntimeError`, anything else (a link/type failure) → `LinkError`.
fn wasm_error_kind(e: &wasmi::Error) -> &'static str {
    if e.as_trap_code().is_some() {
        "Runtime"
    } else {
        "Link"
    }
}

/// The success arm of the fallible-wasm-syscall envelope: `[0, value]`. The
/// prelude's `unwrap` returns `value`; a non-zero first element is an error
/// kind string it maps to the right `WebAssembly.*Error`/`TypeError`.
fn wasm_ok(value: JsValue, ctx: &mut Context) -> JsValue {
    JsArray::from_iter([JsValue::from(0_i32), value], ctx).into()
}

/// The error arm of the envelope: `[kind, message]` (kind ∈ Compile|Link|Runtime).
fn wasm_err(kind: &str, msg: &str, ctx: &mut Context) -> JsValue {
    JsArray::from_iter([str_value(kind), str_value(msg)], ctx).into()
}

/// Read an `ArrayBuffer` syscall argument into owned bytes exactly. The
/// latin1-string body path used elsewhere would corrupt bytes ≥ 0x80 via
/// UTF-8 re-encoding, so binary APIs pass an `ArrayBuffer` across this seam.
/// `None` means that the argument is not an `ArrayBuffer` or is detached.
fn arg_array_buffer_bytes(args: &[JsValue], i: usize) -> Option<Vec<u8>> {
    let obj = args.get(i)?.as_object()?.clone();
    let ab = boa_engine::object::builtins::JsArrayBuffer::from_object(obj).ok()?;
    Some(ab.data()?.to_vec())
}

/// Read any Web Crypto `BufferSource` without first copying a typed-array view
/// through JavaScript. The resulting owned slice is exact for ArrayBuffer,
/// TypedArray, and DataView inputs, including non-zero view offsets.
fn arg_buffer_source_bytes(args: &[JsValue], i: usize, ctx: &mut Context) -> Option<Vec<u8>> {
    let obj = args.get(i)?.as_object()?.clone();
    if let Ok(ab) = boa_engine::object::builtins::JsArrayBuffer::from_object(obj.clone()) {
        return Some(ab.data()?.to_vec());
    }
    let (buffer, offset, length) =
        if let Ok(view) = boa_engine::object::builtins::JsTypedArray::from_object(obj.clone()) {
            (
                view.buffer(ctx).ok()?.as_object()?.clone(),
                view.byte_offset(ctx).ok()?,
                view.byte_length(ctx).ok()?,
            )
        } else if let Ok(view) = boa_engine::object::builtins::JsDataView::from_object(obj) {
            (
                view.buffer(ctx).ok()?.as_object()?.clone(),
                view.byte_offset(ctx).ok()? as usize,
                view.byte_length(ctx).ok()? as usize,
            )
        } else {
            return None;
        };
    let ab = boa_engine::object::builtins::JsArrayBuffer::from_object(buffer).ok()?;
    let end = offset.checked_add(length)?;
    Some(ab.data()?.get(offset..end)?.to_vec())
}

fn arg_wasm_bytes(args: &[JsValue], i: usize) -> Option<Vec<u8>> {
    arg_array_buffer_bytes(args, i)
}

/// A non-negative integer id argument (module/instance/etc.), or `None`.
fn arg_id(args: &[JsValue], i: usize) -> Option<usize> {
    let n = args.get(i)?.as_number()?;
    (n >= 0.0 && n.fract() == 0.0).then_some(n as usize)
}

/// Most page-initiated requests (fetch/XHR/module loads) per page.
/// Was 24 (Phase 2a); archive.org's home alone needs ~32 module loads
/// before any data — at 24 the app's chunks were cut off mid-graph.
/// 96 covered its full boot (62 observed); 256 covers a large static
/// module graph too (css3test's `tests.js` statically imports 154 spec
/// modules — under 96 the graph never linked). Still a hard envelope
/// against runaway pages; `subresource_allowed` separately blocks
/// private-address pivots regardless of count. PROVISIONAL — her call.
pub(crate) const MAX_PAGE_FETCHES: usize = 256;

/// Most import specifiers we'll speculatively prefetch from one module's
/// source. Bounds the wasted bandwidth of a false-positive scan; the
/// per-page `MAX_PAGE_FETCHES` cap still governs the total.
pub(crate) const MAX_SPECULATIVE_IMPORTS: usize = 64;

fn page_dom(ctx: &mut Context) -> Rc<RefCell<Dom>> {
    ctx.realm()
        .host_defined()
        .get::<PageDom>()
        .expect("PageDom installed before any syscall")
        .0
        .clone()
}

/// Node id from a JS argument; None for null/undefined/out-of-range.
fn arg_node(dom: &Dom, args: &[JsValue], i: usize) -> Option<usize> {
    let n = args.get(i)?.as_number()?;
    let id = n as usize;
    (n >= 0.0 && dom.is_valid(id)).then_some(id)
}

fn arg_str(args: &[JsValue], i: usize, ctx: &mut Context) -> String {
    args.get(i)
        .and_then(|v| {
            // Web IDL string arguments from the prelude are already JS
            // strings.  ToString on a primitive string is identity-preserving
            // (ECMAScript ToString), so skip Boa's generic conversion path in
            // that overwhelmingly common case.  Non-strings still use the
            // full coercion path because user objects can run observable
            // `toString`/`Symbol.toPrimitive` code.
            v.as_string()
                .map(|s| s.to_std_string_lossy())
                .or_else(|| v.to_string(ctx).ok().map(|s| s.to_std_string_lossy()))
        })
        .unwrap_or_default()
}

/// Decode a JS string the prelude built as a LATIN1 byte-string (one code unit
/// per byte) back into the exact bytes. A request body must travel byte-exact:
/// the prelude flattens it to such a string (`__bodyWire` — text UTF-8-encoded,
/// binary `Uint8Array`/`ArrayBuffer`/`Blob` already one-byte-per-unit), so we
/// take the low byte of each UTF-16 code unit instead of `to_std_string_lossy`'s
/// UTF-8 re-encode, which would expand every byte >= 0x80 into two and corrupt a
/// gzipped/protobuf/binary body (YouTube gzips its `youtubei` POSTs in-page, so
/// the UTF-8 mangling made the server reject the search continuation with 400).
fn arg_bytes_latin1(v: &JsValue, ctx: &mut Context) -> Vec<u8> {
    v.to_string(ctx)
        .map(|s| s.iter().map(|u| u as u8).collect())
        .unwrap_or_default()
}

fn id_value(id: Option<usize>) -> JsValue {
    match id {
        Some(id) => JsValue::from(id as f64),
        None => JsValue::null(),
    }
}

fn str_value(s: &str) -> JsValue {
    JsValue::from(JsString::from(s))
}

fn ids_array(ids: Vec<usize>, ctx: &mut Context) -> JsValue {
    JsArray::from_iter(ids.into_iter().map(|i| JsValue::from(i as f64)), ctx).into()
}

/// Diagnostic (`TRUST_JS_PROFILE`): dump and reset the Boa VM sampling
/// profile — the hottest JS leaf frames since the last dump, each as
/// `source-url :: function`. The profiler samples the synchronous and async
/// instruction loops; it's zero-cost when the env var is unset. Invaluable for
/// engine-perf dives because hardware perf counters are locked on this host
/// — and it disambiguates "stuck in JS" from "stuck in Rust"
/// (a phase with elapsed wall time but no samples is Rust-side, e.g. layout or
/// the cascade, not the engine).
fn dump_vm_profile(tag: &str) {
    let (total, prof) = boa_engine::vm::profile::take_vm_profile();
    if total == 0 {
        return;
    }
    eprintln!(
        "js : @{:>6}ms VM profile [{tag}] ({total} samples, hottest leaf frames)",
        crate::http::trace_ms()
    );
    for (k, n) in prof.iter().take(25) {
        eprintln!("{n:>10} ({:>4.1}%)  {k}", 100.0 * *n as f64 / total as f64);
    }
}

type BoaHostFn = fn(&JsValue, &[JsValue], &mut Context) -> JsResult<JsValue>;

