    #[test]
    fn shadow_boundaries_retarget_event_target() {
        // DOM §2.9 retargeting: a listener OUTSIDE a shadow tree sees the HOST
        // as `ev.target`; one inside (on the shadow root) sees the real inner
        // target; `ev.target` is restored after dispatch.
        let mut ctx = platform_ctx();
        let budget = Budget::new(TEST_BUDGET);
        let mut outcome = Outcome::default();
        run_script(
            &mut ctx,
            "retarget.js",
            br##"
            globalThis.out = {};
            const host = document.createElement("x-host");
            host.id = "host";
            document.getElementById("outer").appendChild(host);
            const sr = host.attachShadow({ mode: "open" });
            const inner = document.createElement("button");
            inner.id = "inner";
            sr.appendChild(inner);
            sr.addEventListener("ping", (e) => { out.inside = e.target.id; });
            document.addEventListener("ping", (e) => { out.outside = e.target.id; });
            const ev = new Event("ping", { bubbles: true, composed: true });
            inner.dispatchEvent(ev);
            out.after = ev.target.id;
            "##,
            &budget,
            &mut outcome,
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        let s = |ctx: &mut Context, expr: &[u8]| {
            ctx.eval(Source::from_bytes(expr))
                .unwrap()
                .to_string(ctx)
                .unwrap()
                .to_std_string_escaped()
        };
        assert_eq!(s(&mut ctx, b"out.inside"), "inner");
        assert_eq!(s(&mut ctx, b"out.outside"), "host");
        assert_eq!(s(&mut ctx, b"out.after"), "inner");
    }

    #[test]
    fn non_composed_events_stop_at_the_shadow_root() {
        // DOM: a shadow root's "get the parent" returns null when the event's
        // composed flag is unset — a non-composed event dispatched inside a
        // shadow tree reaches listeners in THAT tree (up to its root) and
        // nothing outside it: not the host, not the document, not window.
        let mut ctx = platform_ctx();
        let budget = Budget::new(TEST_BUDGET);
        let mut outcome = Outcome::default();
        run_script(
            &mut ctx,
            "composed-clip.js",
            br##"
            globalThis.out = { seen: [] };
            const host = document.createElement("x-clip");
            document.getElementById("outer").appendChild(host);
            const sr = host.attachShadow({ mode: "open" });
            const inner = document.createElement("button");
            sr.appendChild(inner);
            sr.addEventListener("ping", () => out.seen.push("sr"));
            host.addEventListener("ping", () => out.seen.push("host"));
            document.addEventListener("ping", () => out.seen.push("doc"));
            window.addEventListener("ping", () => out.seen.push("win"));
            inner.dispatchEvent(new Event("ping", { bubbles: true })); // composed: false
            out.clipped = out.seen.join(",");
            out.seen.length = 0;
            inner.dispatchEvent(new Event("ping", { bubbles: true, composed: true }));
            out.escaped = out.seen.join(",");
            "##,
            &budget,
            &mut outcome,
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        let s = |ctx: &mut Context, expr: &[u8]| {
            ctx.eval(Source::from_bytes(expr))
                .unwrap()
                .to_string(ctx)
                .unwrap()
                .to_std_string_escaped()
        };
        assert_eq!(s(&mut ctx, b"out.clipped"), "sr");
        assert_eq!(s(&mut ctx, b"out.escaped"), "sr,host,doc,win");
    }

    #[test]
    fn related_targets_retarget_and_internal_hovers_stay_internal() {
        // DOM §2.9 relatedTarget handling: (a) a mouseover wholly inside a
        // component (target AND relatedTarget in the same shadow tree) never
        // escapes it — the hop where both retarget to the host ends
        // propagation; (b) dispatching AT the host with a relatedTarget from
        // its own shadow tree collapses at the entry check → no dispatch at
        // all; (c) an outside listener sees a shadow-internal relatedTarget
        // retargeted to its host.
        let mut ctx = platform_ctx();
        let budget = Budget::new(TEST_BUDGET);
        let mut outcome = Outcome::default();
        run_script(
            &mut ctx,
            "related.js",
            br##"
            globalThis.out = { seen: [] };
            const host = document.createElement("x-rel");
            document.getElementById("outer").appendChild(host);
            const sr = host.attachShadow({ mode: "open" });
            const a = document.createElement("i"), b = document.createElement("s");
            sr.appendChild(a); sr.appendChild(b);
            sr.addEventListener("mouseover", (e) => out.insideRelated = e.relatedTarget.localName);
            document.addEventListener("mouseover", (e) => out.seen.push("doc:" + (e.relatedTarget && e.relatedTarget.localName)));
            // (a) inside -> inside: stays inside the shadow tree.
            a.dispatchEvent(new MouseEvent("mouseover", { bubbles: true, composed: true, relatedTarget: b }));
            out.internalStayed = out.seen.length === 0 && out.insideRelated === "s";
            // (b) at the host with an internal relatedTarget: skipped entirely.
            let hostRan = false;
            host.addEventListener("mouseover", () => { hostRan = true; });
            host.dispatchEvent(new MouseEvent("mouseover", { bubbles: true, composed: true, relatedTarget: a }));
            out.entrySkipped = !hostRan && out.seen.length === 0;
            // (c) light-DOM target, shadow-internal relatedTarget: the outside
            // listener sees the HOST as relatedTarget.
            document.getElementById("b").dispatchEvent(new MouseEvent("mouseover", { bubbles: true, composed: true, relatedTarget: a }));
            out.retargeted = out.seen.join(",");
            "##,
            &budget,
            &mut outcome,
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        let s = |ctx: &mut Context, expr: &[u8]| {
            ctx.eval(Source::from_bytes(expr))
                .unwrap()
                .to_string(ctx)
                .unwrap()
                .to_std_string_escaped()
        };
        assert_eq!(s(&mut ctx, b"String(out.internalStayed)"), "true");
        assert_eq!(s(&mut ctx, b"String(out.entrySkipped)"), "true");
        assert_eq!(s(&mut ctx, b"out.retargeted"), "doc:x-rel");
    }

    #[test]
    fn composed_path_hides_closed_shadow_internals() {
        // DOM §2.2 composedPath(): a listener outside a CLOSED shadow tree
        // gets a path with the tree's internals hidden (host outward only); a
        // listener inside it sees the full path; and outside dispatch the
        // path is empty (the spec clears it when dispatch unwinds).
        let mut ctx = platform_ctx();
        let budget = Budget::new(TEST_BUDGET);
        let mut outcome = Outcome::default();
        run_script(
            &mut ctx,
            "composed-path.js",
            br##"
            globalThis.out = {};
            const host = document.createElement("x-closed");
            document.getElementById("outer").appendChild(host);
            const sr = host.attachShadow({ mode: "closed" });
            const inner = document.createElement("button");
            sr.appendChild(inner);
            const names = (p) => p.map((n) => n === window ? "window" : (n.localName || (n.nodeType === 9 ? "#document" : "#fragment"))).join(",");
            sr.addEventListener("ping", (e) => { out.inside = names(e.composedPath()); });
            document.addEventListener("ping", (e) => { out.outside = names(e.composedPath()); });
            const ev = new Event("ping", { bubbles: true, composed: true });
            inner.dispatchEvent(ev);
            out.after = ev.composedPath().length;
            "##,
            &budget,
            &mut outcome,
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        let s = |ctx: &mut Context, expr: &[u8]| {
            ctx.eval(Source::from_bytes(expr))
                .unwrap()
                .to_string(ctx)
                .unwrap()
                .to_std_string_escaped()
        };
        assert_eq!(
            s(&mut ctx, b"out.inside"),
            "button,#fragment,x-closed,div,body,html,#document,window"
        );
        assert_eq!(
            s(&mut ctx, b"out.outside"),
            "x-closed,div,body,html,#document,window"
        );
        assert_eq!(s(&mut ctx, b"String(out.after)"), "0");
    }

    #[test]
    fn location_component_setters_navigate_per_the_spec() {
        // HTML §Location: protocol/host/hostname/port setters copy the URL,
        // apply the component, and navigate. An unparseable protocol is a
        // SyntaxError; a valid non-HTTP(S) protocol terminates silently
        // (Location can't leave the HTTP family).
        let mut ctx = platform_ctx();
        let budget = Budget::new(TEST_BUDGET);
        let mut outcome = Outcome::default();
        run_script(
            &mut ctx,
            "loc-setters.js",
            br##"
            globalThis.out = {};
            location.port = "8080";
            out.port = __trust.takeNavigation();
            location.hostname = "example.org";
            out.hostname = __trust.takeNavigation();
            location.host = "example.net:9000";
            out.host = __trust.takeNavigation();
            location.port = "";
            out.noPort = __trust.takeNavigation();
            try { location.protocol = "://"; } catch (e) { out.protoErr = e.name; }
            location.protocol = "ftp";
            out.ftpNav = String(__trust.takeNavigation());
            location.protocol = "http:";
            out.http = __trust.takeNavigation();
            "##,
            &budget,
            &mut outcome,
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        let s = |ctx: &mut Context, expr: &[u8]| {
            ctx.eval(Source::from_bytes(expr))
                .unwrap()
                .to_string(ctx)
                .unwrap()
                .to_std_string_escaped()
        };
        assert_eq!(s(&mut ctx, b"out.port"), "https://example.com:8080/");
        assert_eq!(s(&mut ctx, b"out.hostname"), "https://example.org:8080/");
        assert_eq!(s(&mut ctx, b"out.host"), "https://example.net:9000/");
        assert_eq!(s(&mut ctx, b"out.noPort"), "https://example.net/");
        assert_eq!(s(&mut ctx, b"out.protoErr"), "SyntaxError");
        assert_eq!(s(&mut ctx, b"out.ftpNav"), "null");
        assert_eq!(s(&mut ctx, b"out.http"), "http://example.net/");
    }

    #[test]
    fn new_date_and_date_now_share_the_virtual_clock() {
        // `new Date()` reads the same virtual clock as `Date.now()` (the
        // Rust-side PageClock mirrors `timers.now` via `__clock_set`), so a
        // fast-forward settle advances BOTH in lockstep — a page diffing them
        // used to see the real clock in one and the virtual clock in the
        // other. Event.timeStamp rides the same clock (was a constant 0).
        let mut ctx = platform_ctx();
        let budget = Budget::new(TEST_BUDGET);
        let mut outcome = Outcome::default();
        run_script(
            &mut ctx,
            "virtual-date.js",
            br##"
            globalThis.out = {};
            const t0 = Date.now();
            out.anchorDelta = new Date().getTime() - t0;
            __trust.oneShot = true;
            setTimeout(() => {
                out.nowDelta = Date.now() - t0;
                out.dateDelta = new Date().getTime() - t0;
                out.ts = new Event("x").timeStamp;
            }, 600);
            __trust.tick();
            "##,
            &budget,
            &mut outcome,
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        let s = |ctx: &mut Context, expr: &[u8]| {
            ctx.eval(Source::from_bytes(expr))
                .unwrap()
                .to_string(ctx)
                .unwrap()
                .to_std_string_escaped()
        };
        assert_eq!(
            s(
                &mut ctx,
                b"String(out.anchorDelta >= 0 && out.anchorDelta < 100)"
            ),
            "true"
        );
        // A one-shot snapshot advances by AT LEAST the requested 600ms. The
        // host monotonic clock keeps running during and between reads, so a
        // preempted test may legitimately observe more than exactly 600ms.
        assert_eq!(
            s(
                &mut ctx,
                b"String(out.nowDelta >= 600 && out.nowDelta < 3000)"
            ),
            "true"
        );
        assert_eq!(
            s(
                &mut ctx,
                b"String(out.dateDelta >= out.nowDelta && out.dateDelta - out.nowDelta < 100)"
            ),
            "true"
        );
        assert_eq!(
            s(
                &mut ctx,
                // The test process can be preempted between these adjacent JS
                // reads under a parallel full-suite run. Monotonic ordering is
                // the contract; use the same bounded scheduling allowance as
                // the timer assertion above.
                b"String(out.ts >= out.dateDelta && out.ts - out.dateDelta < 3000)"
            ),
            "true"
        );
    }

    #[test]
    fn page_clocks_advance_synchronously_and_timer_tasks_get_separate_turns() {
        // High Resolution Time §§2.1/7.1: performance.now() uses a monotonic
        // clock which keeps counting while script runs. YouTube's scheduler
        // budgets a rendering slice with exactly this loop shape; a frozen
        // clock made the slice run until Boa's loop guard instead of yielding.
        // HTML timers queue tasks, so tickTo must expose one callback per turn
        // (and therefore a microtask checkpoint between overdue callbacks).
        let mut ctx = platform_ctx();
        let budget = Budget::new(TEST_BUDGET);
        let mut outcome = Outcome::default();
        run_script(
            &mut ctx,
            "monotonic-clock.js",
            br##"
            globalThis.out = {};
            const p0 = performance.now();
            while (performance.now() - p0 < 4) {}
            out.performanceDelta = performance.now() - p0;
            const d0 = Date.now();
            while (Date.now() - d0 < 4) {}
            out.dateDelta = Date.now() - d0;
            out.eventTime = new Event("after-work").timeStamp;

            const order = [];
            setTimeout(() => order.push(1), 0);
            setTimeout(() => order.push(2), 0);
            out.firstCount = __trust.tickTo(__trust.now() + 100);
            out.afterFirst = order.join(",");
            out.secondCount = __trust.tickTo(__trust.now() + 100);
            out.afterSecond = order.join(",");
            "##,
            &budget,
            &mut outcome,
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        let n = |ctx: &mut Context, expr: &[u8]| {
            ctx.eval(Source::from_bytes(expr))
                .unwrap()
                .as_number()
                .unwrap()
        };
        let s = |ctx: &mut Context, expr: &[u8]| {
            ctx.eval(Source::from_bytes(expr))
                .unwrap()
                .to_string(ctx)
                .unwrap()
                .to_std_string_escaped()
        };
        assert!(n(&mut ctx, b"out.performanceDelta") >= 4.0);
        assert!(n(&mut ctx, b"out.dateDelta") >= 4.0);
        assert!(n(&mut ctx, b"out.eventTime") >= 8.0);
        assert_eq!(n(&mut ctx, b"out.firstCount"), 1.0);
        assert_eq!(s(&mut ctx, b"out.afterFirst"), "1");
        assert_eq!(n(&mut ctx, b"out.secondCount"), 1.0);
        assert_eq!(s(&mut ctx, b"out.afterSecond"), "1,2");
    }

    #[test]
    fn timer_initialization_uses_nesting_clamp_and_window_callback_this() {
        // HTML §8.7 "timer initialization steps": a timer task carries its
        // nesting level, only a parent level greater than five clamps a delay
        // below 4 ms, and a Window callback receives its WindowProxy as `this`.
        // Web IDL converts an infinite `long` timeout to zero before those
        // steps run.
        let mut ctx = platform_ctx();
        let budget = Budget::new(TEST_BUDGET);
        let mut outcome = Outcome::default();
        run_script(
            &mut ctx,
            "timer-nesting.js",
            br##"
            globalThis.out = { nesting: [], waits: [], thisValues: [] };
            function chain() {
                out.thisValues.push(this === window);
                if (out.nesting.length < 7) {
                    setTimeout(chain, 0);
                    const info = __trust.nextTimerInfo();
                    out.nesting.push(info.nesting);
                    out.waits.push(info.wait);
                }
            }
            setTimeout(chain, Infinity);
            out.initialWait = __trust.nextTimerInfo().wait;
            "##,
            &budget,
            &mut outcome,
        );
        for _ in 0..8 {
            let deadline = ctx
                .eval(Source::from_bytes(b"__trust.nextDeadline()"))
                .unwrap()
                .as_number()
                .unwrap();
            let source = format!("__trust.tickTo({deadline})");
            ctx.eval(Source::from_bytes(source.as_bytes())).unwrap();
            run_jobs_into(&mut ctx, &budget, &mut outcome);
        }
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        let string = |ctx: &mut Context, expression: &[u8]| {
            ctx.eval(Source::from_bytes(expression))
                .unwrap()
                .to_string(ctx)
                .unwrap()
                .to_std_string_escaped()
        };
        assert_eq!(string(&mut ctx, b"String(out.initialWait)"), "0");
        assert_eq!(string(&mut ctx, b"out.nesting.join(',')"), "2,3,4,5,6,7,8");
        assert_eq!(string(&mut ctx, b"out.waits.join(',')"), "0,0,0,0,0,4,4");
        assert_eq!(
            string(&mut ctx, b"String(out.thisValues.every(Boolean))"),
            "true"
        );
    }

    #[test]
    fn animation_frame_callbacks_run_as_one_snapshot_per_rendering_opportunity() {
        // HTML §8.10 requestAnimationFrame/run the animation frame callbacks:
        // one rendering opportunity snapshots the callback-map keys, removes
        // each callback before invocation, and gives every callback the same
        // timestamp. Cancellation during an earlier callback is honored, while
        // a callback requested during the pass waits for the next opportunity.
        let mut ctx = platform_ctx();
        let budget = Budget::new(TEST_BUDGET);
        let mut outcome = Outcome::default();
        run_script(
            &mut ctx,
            "animation-frame-snapshot.js",
            br##"
            globalThis.out = { order: [], timestamps: [] };
            let third;
            requestAnimationFrame((timestamp) => {
                out.order.push("first");
                out.timestamps.push(timestamp);
                cancelAnimationFrame(third);
                requestAnimationFrame((nextTimestamp) => {
                    out.order.push("nested");
                    out.timestamps.push(nextTimestamp);
                });
            });
            requestAnimationFrame((timestamp) => {
                out.order.push("second");
                out.timestamps.push(timestamp);
            });
            third = requestAnimationFrame(() => out.order.push("cancelled"));
            try { requestAnimationFrame(1); }
            catch (error) { out.typeError = error.name; }

            out.firstCount = __trust.tickTo(__trust.nextDeadline());
            out.afterFirst = out.order.join(",");
            out.sameTimestamp = out.timestamps[0] === out.timestamps[1];
            out.secondCount = __trust.tickTo(__trust.nextDeadline());
            out.afterSecond = out.order.join(",");
            out.timestampAdvanced = out.timestamps[2] > out.timestamps[1];
            "##,
            &budget,
            &mut outcome,
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        let value = |ctx: &mut Context, expression: &[u8]| {
            ctx.eval(Source::from_bytes(expression))
                .unwrap()
                .to_string(ctx)
                .unwrap()
                .to_std_string_escaped()
        };
        assert_eq!(value(&mut ctx, b"String(out.firstCount)"), "2");
        assert_eq!(value(&mut ctx, b"out.afterFirst"), "first,second");
        assert_eq!(value(&mut ctx, b"String(out.sameTimestamp)"), "true");
        assert_eq!(value(&mut ctx, b"String(out.secondCount)"), "1");
        assert_eq!(value(&mut ctx, b"out.afterSecond"), "first,second,nested");
        assert_eq!(value(&mut ctx, b"String(out.timestampAdvanced)"), "true");
        assert_eq!(value(&mut ctx, b"out.typeError"), "TypeError");
    }

    #[test]
    fn idle_callbacks_run_only_in_host_started_idle_periods_or_after_timeout() {
        // W3C requestIdleCallback §§4–5: registration appends to the pending
        // list without creating a normal timer; starting an idle period moves
        // that snapshot to the runnable list, invokes one callback per task,
        // and leaves callbacks reposted during invocation for the next period.
        // IdleDeadline measures the actual remaining period dynamically.
        let mut ctx = platform_ctx();
        let budget = Budget::new(TEST_BUDGET);
        let mut outcome = Outcome::default();
        run_script(
            &mut ctx,
            "idle-callback-periods.js",
            br##"
            globalThis.idleResult = { order: [] };
            const cancelled = requestIdleCallback(() => idleResult.order.push("cancelled"));
            cancelIdleCallback(cancelled);
            requestIdleCallback((deadline) => {
                idleResult.order.push("first");
                idleResult.didTimeout = deadline.didTimeout;
                idleResult.before = deadline.timeRemaining();
                const started = performance.now();
                while (performance.now() - started < 2) {}
                idleResult.after = deadline.timeRemaining();
                idleResult.tag = Object.prototype.toString.call(deadline);
                requestIdleCallback(() => idleResult.order.push("nested"));
            });
            idleResult.timerBeforePeriod = __trust.nextDeadline();
            idleResult.ranBeforePeriod = idleResult.order.length;
            __trust.startIdlePeriod(__trust.now() + 50);
            idleResult.firstTask = __trust.runPlatformTask();
            idleResult.afterFirst = idleResult.order.join(",");
            idleResult.samePeriodHasTask = __trust.hasPlatformTask();
            __trust.startIdlePeriod(__trust.now() + 50);
            idleResult.secondTask = __trust.runPlatformTask();
            idleResult.afterSecond = idleResult.order.join(",");

            requestIdleCallback((deadline) => {
                idleResult.order.push("timeout");
                idleResult.timeoutDidTimeout = deadline.didTimeout;
                idleResult.timeoutRemaining = deadline.timeRemaining();
            }, { timeout: 5 });
            __trust.tickTo(__trust.now() + 10);
            idleResult.timeoutQueued = __trust.hasPlatformTask();
            __trust.runPlatformTask();
            idleResult.afterTimeout = idleResult.order.join(",");
            "##,
            &budget,
            &mut outcome,
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        let value = |ctx: &mut Context, expression: &[u8]| {
            ctx.eval(Source::from_bytes(expression))
                .unwrap()
                .to_string(ctx)
                .unwrap()
                .to_std_string_escaped()
        };
        assert_eq!(
            value(&mut ctx, b"String(idleResult.timerBeforePeriod)"),
            "null"
        );
        assert_eq!(value(&mut ctx, b"String(idleResult.ranBeforePeriod)"), "0");
        assert_eq!(value(&mut ctx, b"String(idleResult.firstTask)"), "true");
        assert_eq!(value(&mut ctx, b"idleResult.afterFirst"), "first");
        assert_eq!(
            value(&mut ctx, b"String(idleResult.samePeriodHasTask)"),
            "false"
        );
        assert_eq!(value(&mut ctx, b"String(idleResult.secondTask)"), "true");
        assert_eq!(value(&mut ctx, b"idleResult.afterSecond"), "first,nested");
        assert_eq!(value(&mut ctx, b"String(idleResult.didTimeout)"), "false");
        assert_eq!(
            value(&mut ctx, b"String(idleResult.before > idleResult.after)"),
            "true"
        );
        assert_eq!(value(&mut ctx, b"idleResult.tag"), "[object IdleDeadline]");
        assert_eq!(value(&mut ctx, b"String(idleResult.timeoutQueued)"), "true");
        assert_eq!(
            value(&mut ctx, b"String(idleResult.timeoutDidTimeout)"),
            "true"
        );
        assert_eq!(value(&mut ctx, b"String(idleResult.timeoutRemaining)"), "0");
        assert_eq!(
            value(&mut ctx, b"idleResult.afterTimeout"),
            "first,nested,timeout"
        );
    }

    #[test]
    fn element_attributes_is_the_same_live_named_node_map() {
        // DOM: the `attributes` getter is [SameObject] — one NamedNodeMap per
        // element, identity-stable across accesses, its contents fresh after
        // attribute writes (rebuilt lazily off the setAttribute funnels).
        let mut ctx = platform_ctx();
        let budget = Budget::new(TEST_BUDGET);
        let mut outcome = Outcome::default();
        run_script(
            &mut ctx,
            "attr-map.js",
            br##"
            globalThis.out = {};
            const el = document.getElementById("b");
            const map = el.attributes;
            out.same = map === el.attributes;
            const before = map.length;
            el.setAttribute("data-x", "1");
            out.stillSame = el.attributes === map;
            out.grew = map.length === before + 1;
            out.named = el.attributes["data-x"].value;
            el.setAttribute("data-x", "2");
            out.freshValue = el.attributes["data-x"].value;
            el.removeAttribute("data-x");
            out.dropped = el.attributes.length === before && el.attributes["data-x"] === undefined;
            "##,
            &budget,
            &mut outcome,
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        let s = |ctx: &mut Context, expr: &[u8]| {
            ctx.eval(Source::from_bytes(expr))
                .unwrap()
                .to_string(ctx)
                .unwrap()
                .to_std_string_escaped()
        };
        assert_eq!(s(&mut ctx, b"String(out.same)"), "true");
        assert_eq!(s(&mut ctx, b"String(out.stillSame)"), "true");
        assert_eq!(s(&mut ctx, b"String(out.grew)"), "true");
        assert_eq!(s(&mut ctx, b"out.named"), "1");
        assert_eq!(s(&mut ctx, b"out.freshValue"), "2");
        assert_eq!(s(&mut ctx, b"String(out.dropped)"), "true");
    }

    #[test]
    fn xhr_timeout_follows_the_sync_rules() {
        // XHR: `timeout` set on an already-sync request throws
        // InvalidStateError; `open(…, false)` with a non-zero timeout (or a
        // responseType) already set throws InvalidAccessError.
        let mut ctx = platform_ctx();
        let budget = Budget::new(TEST_BUDGET);
        let mut outcome = Outcome::default();
        run_script(
            &mut ctx,
            "xhr-timeout.js",
            br##"
            globalThis.out = {};
            const x = new XMLHttpRequest();
            x.timeout = 5; // fine while async (the default)
            try { x.open("GET", "/x", false); } catch (e) { out.openErr = e.name; }
            const y = new XMLHttpRequest();
            y.open("GET", "/y", false);
            try { y.timeout = 10; } catch (e) { out.setErr = e.name; }
            out.kept = y.timeout;
            "##,
            &budget,
            &mut outcome,
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        let s = |ctx: &mut Context, expr: &[u8]| {
            ctx.eval(Source::from_bytes(expr))
                .unwrap()
                .to_string(ctx)
                .unwrap()
                .to_std_string_escaped()
        };
        assert_eq!(s(&mut ctx, b"out.openErr"), "InvalidAccessError");
        assert_eq!(s(&mut ctx, b"out.setErr"), "InvalidStateError");
        assert_eq!(s(&mut ctx, b"String(out.kept)"), "0");
    }

    #[test]
    fn structured_clone_reconstructs_error_subclasses() {
        // HTML structured serialize: names in the native-error set come back
        // as that subclass (instanceof survives); DOMException round-trips
        // through its constructor keeping its name; other names ride Error.
        let mut ctx = platform_ctx();
        let budget = Budget::new(TEST_BUDGET);
        let mut outcome = Outcome::default();
        run_script(
            &mut ctx,
            "clone-errors.js",
            br##"
            globalThis.out = {};
            const t = structuredClone(new TypeError("boom"));
            out.te = (t instanceof TypeError) && t.message === "boom";
            const r = structuredClone(new RangeError("r"));
            out.re = r instanceof RangeError;
            const d = structuredClone(new DOMException("gone", "AbortError"));
            out.de = (d instanceof DOMException) && d.name === "AbortError" && d.message === "gone";
            const custom = new Error("odd"); custom.name = "MyAppError";
            const c = structuredClone(custom);
            out.custom = c.name === "MyAppError" && !(c instanceof TypeError);
            "##,
            &budget,
            &mut outcome,
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        let s = |ctx: &mut Context, expr: &[u8]| {
            ctx.eval(Source::from_bytes(expr))
                .unwrap()
                .to_string(ctx)
                .unwrap()
                .to_std_string_escaped()
        };
        assert_eq!(s(&mut ctx, b"String(out.te)"), "true");
        assert_eq!(s(&mut ctx, b"String(out.re)"), "true");
        assert_eq!(s(&mut ctx, b"String(out.de)"), "true");
        assert_eq!(s(&mut ctx, b"String(out.custom)"), "true");
    }

    #[test]
    fn fetch_method_tokens_keep_their_dash_and_case() {
        // Fetch §2.2.1: methods are HTTP tokens; only the six listed methods
        // normalize to uppercase. `M-SEARCH` used to lose its dash and
        // extension methods were force-uppercased.
        let mut ctx = page_context();
        let m = |ctx: &mut Context, method: &str| {
            let args = [str_value("http://x/"), str_value(method)];
            fetch_args(&args, ctx).1
        };
        assert_eq!(m(&mut ctx, "M-SEARCH"), "M-SEARCH");
        assert_eq!(m(&mut ctx, "m-search"), "m-search");
        assert_eq!(m(&mut ctx, "get"), "GET");
        assert_eq!(m(&mut ctx, "PoSt"), "POST");
        assert_eq!(m(&mut ctx, "patch"), "patch");
        assert_eq!(m(&mut ctx, ""), "GET");
    }

    #[test]
    fn url_host_setter_applies_the_port() {
        // WHATWG URL host setter: `u.host = "h:9000"` runs the basic parser
        // through host state INTO port state — host AND port both apply. The
        // url crate's `set_host` alone is hostname-only and silently dropped
        // the ":port" tail (found via Location.host, which shares __url_set).
        let mut ctx = platform_ctx();
        let budget = Budget::new(TEST_BUDGET);
        let mut outcome = Outcome::default();
        run_script(
            &mut ctx,
            "url-host.js",
            br##"
            globalThis.out = {};
            const u = new URL("https://a.example/p?q=1#f");
            u.host = "b.example:9000";
            out.href = u.href;
            out.port = u.port;
            u.host = "c.example"; // no port section: the port is kept
            out.kept = u.host;
            "##,
            &budget,
            &mut outcome,
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        let s = |ctx: &mut Context, expr: &[u8]| {
            ctx.eval(Source::from_bytes(expr))
                .unwrap()
                .to_string(ctx)
                .unwrap()
                .to_std_string_escaped()
        };
        assert_eq!(s(&mut ctx, b"out.href"), "https://b.example:9000/p?q=1#f");
        assert_eq!(s(&mut ctx, b"out.port"), "9000");
        assert_eq!(s(&mut ctx, b"out.kept"), "c.example:9000");
    }

    #[test]
    fn an_injected_data_url_script_runs_and_fires_load() {
        // The runtime-injected twin of the parse-time data: script path — it
        // used to hit the http(s)-only net gate and fire `error` for a script
        // a real browser runs.
        let mut ctx = platform_ctx();
        let budget = Budget::new(TEST_BUDGET);
        let mut outcome = Outcome::default();
        run_script(
            &mut ctx,
            "inject-data.js",
            br##"
            globalThis.out = { events: [] };
            const sc = document.createElement("script");
            globalThis.__injectedScript = sc;
            sc.addEventListener("load", () => {
                out.events.push("load");
                out.currentAtLoad = document.currentScript;
            });
            sc.addEventListener("error", () => out.events.push("error"));
            sc.src = "data:text/javascript,globalThis.__injected = document.currentScript === globalThis.__injectedScript ? 7 : -7; Promise.resolve().then(function(){ globalThis.__injectedMicro = document.currentScript === globalThis.__injectedScript; });";
            document.querySelector("body").appendChild(sc);
            "##,
            &budget,
            &mut outcome,
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        settle(&mut ctx, &budget, 4, &mut outcome);
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        let s = |ctx: &mut Context, expr: &[u8]| {
            ctx.eval(Source::from_bytes(expr))
                .unwrap()
                .to_string(ctx)
                .unwrap()
                .to_std_string_escaped()
        };
        assert_eq!(s(&mut ctx, b"String(globalThis.__injected)"), "7");
        assert_eq!(s(&mut ctx, b"String(globalThis.__injectedMicro)"), "true");
        assert_eq!(s(&mut ctx, b"out.events.join(',')"), "load");
        assert_eq!(s(&mut ctx, b"String(out.currentAtLoad)"), "null");
    }

    #[test]
    fn websocket_constructor_and_close_validation_are_synchronous() {
        // WebSockets §3.1 constructor/close steps run before any parallel connection work:
        // URL/subprotocol failures throw SyntaxError, send while CONNECTING throws
        // InvalidStateError, and close validates its status and UTF-8 reason length first.
        let mut ctx = platform_ctx();
        let budget = Budget::new(TEST_BUDGET);
        let mut outcome = Outcome::default();
        run_script(
            &mut ctx,
            "websocket-validation.js",
            br##"
            globalThis.wsChecks = [];
            try { new WebSocket("ftp://example.test/socket"); }
            catch (error) { wsChecks.push("url:" + error.name); }
            try { new WebSocket("/socket", ["chat", "chat"]); }
            catch (error) { wsChecks.push("protocol:" + error.name); }
            const socket = new WebSocket("https://example.test/socket", ["chat"]);
            wsChecks.push("serialized:" + socket.url);
            try { socket.binaryType = "bytes"; }
            catch (error) { wsChecks.push("binary:" + error.name); }
            try { socket.send("early"); }
            catch (error) { wsChecks.push("send:" + error.name); }
            try { socket.close(2000); }
            catch (error) { wsChecks.push("code:" + error.name); }
            try { socket.close(1000, "\u00e9".repeat(62)); }
            catch (error) { wsChecks.push("reason:" + error.name); }
            "##,
            &budget,
            &mut outcome,
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        let checks = ctx
            .eval(Source::from_bytes(b"wsChecks.join('|')"))
            .unwrap()
            .to_string(&mut ctx)
            .unwrap()
            .to_std_string_escaped();
        assert_eq!(
            checks,
            "url:SyntaxError|protocol:SyntaxError|serialized:wss://example.test/socket|\
             binary:TypeError|send:InvalidStateError|code:InvalidAccessError|reason:SyntaxError"
        );
    }

    #[test]
    fn injected_script_promise_all_resumes_after_load_handlers_remove_scripts() {
        // HTML script processing fires one `load` event at a successfully
        // executed external classic script. Webpack-style loaders install an
        // `onload` IDL handler, remove the script in that handler, and await a
        // Promise.all of several chunks before mounting the application.
        let mut ctx = platform_ctx();
        let budget = Budget::new(TEST_BUDGET);
        let mut outcome = Outcome::default();
        run_script(
            &mut ctx,
            "inject-promise-all.js",
            br##"
            globalThis.out = { events: [] };
            const loads = [];
            for (let i = 0; i < 7; ++i) {
                loads.push(new Promise((resolve, reject) => {
                    const sc = document.createElement("script");
                    sc.onload = function (event) {
                        out.events.push(event.type + i);
                        sc.onerror = sc.onload = null;
                        sc.remove();
                        resolve(i);
                    };
                    sc.onerror = reject;
                    sc.src = "data:text/javascript,globalThis.__chunk" + i + "=" + i;
                    document.head.appendChild(sc);
                }));
            }
            Promise.all(loads).then(values => {
                out.mounted = values.join(",");
            });
            "##,
            &budget,
            &mut outcome,
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        settle(&mut ctx, &budget, 16, &mut outcome);
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        let s = |ctx: &mut Context, expr: &[u8]| {
            ctx.eval(Source::from_bytes(expr))
                .unwrap()
                .to_string(ctx)
                .unwrap()
                .to_std_string_escaped()
        };
        assert_eq!(
            s(&mut ctx, b"out.events.join(',')"),
            "load0,load1,load2,load3,load4,load5,load6"
        );
        assert_eq!(s(&mut ctx, b"out.mounted"), "0,1,2,3,4,5,6");
        assert_eq!(
            s(
                &mut ctx,
                b"String(document.head.querySelectorAll('script').length)"
            ),
            "0"
        );
    }

