    /// The acceptance canary: real framework bundles against the REAL
    /// arena DOM, through the full `transform` pipeline — no stubs.
    /// Each bundle loads as the page's external script, then a probe
    /// script drives it: jQuery manipulates the page, Vue mounts a
    /// component, D3 appends elements. Manual because it wants
    /// release-mode timings and local bundle files:
    ///
    /// ```sh
    /// mkdir -p target/canary && cd target/canary
    /// curl -LO https://code.jquery.com/jquery-3.7.1.min.js
    /// curl -LO https://unpkg.com/vue@3/dist/vue.global.prod.js
    /// curl -LO https://d3js.org/d3.v7.min.js
    /// cargo test --release canary -- --ignored --nocapture
    /// ```
    /// Run `transform` on a dedicated 64MB-stack thread, exactly as production
    /// does (`spawn_page`). The plain `transform` runs on the caller's thread;
    /// for big real-world bundles the parser/scope-analyzer recursion needs the
    /// big stack, and lazy compilation moves that deep recursion into
    /// EXECUTION (re-analysis at delazify), so a test driving a big bundle with
    /// `TRUST_LAZY_PARSE=1` must use the same big stack the live page actor does.
    /// Takes ownership (the engine env is `Send`, as `spawn_page` relies on).
    fn transform_on_page_stack(html: String, env: PageEnv) -> (String, Outcome) {
        std::thread::Builder::new()
            .stack_size(PAGE_STACK)
            .name("trust-test-transform".into())
            .spawn(move || transform(&html, &env))
            .expect("spawn transform thread")
            .join()
            .expect("transform thread panicked")
    }

    #[test]
    #[ignore = "manual canary: needs bundles in target/canary/ and --release timings"]
    fn canary_real_world_bundles() {
        const PROBE: &str = r##"
            var msg = [];
            function out(s) { document.body.appendChild(document.createTextNode("\n" + s)); }
            if (typeof jQuery !== "undefined") {
                msg.push("jQuery " + jQuery.fn.jquery);
                jQuery("#target").text("jQuery drives the real DOM");
                jQuery("<p class='made-by-jq'>and builds new elements</p>").appendTo(document.body);
                jQuery("p.made-by-jq").addClass("found-again");
            }
            if (typeof Vue !== "undefined") {
                msg.push("Vue " + Vue.version);
                try {
                    Vue.createApp({
                        data: function () { return { who: "TRust" }; },
                        // A render function, as precompiled Vue apps ship.
                        // (Template strings need the in-browser compiler,
                        // whose `with` blocks trip a Boa VM bug.)
                        render: function () { return Vue.h("p", {}, "Vue renders inside " + this.who); },
                    }).mount("#target");
                } catch (e) { out("vue mount failed: " + (e && e.message)); }
            }
            if (typeof d3 !== "undefined") {
                msg.push("d3 " + d3.version);
                try {
                    d3.select("#target").append("p").attr("class", "made-by-d3").text("d3 appended this");
                } catch (e) { out("d3 select failed: " + (e && e.message)); }
            }
            out("BOOTED: " + (msg.join(", ") || "nothing"));
        "##;

        let dir = std::path::Path::new("target/canary");
        let mut entries: Vec<_> = match std::fs::read_dir(dir) {
            Ok(rd) => rd
                .filter_map(Result::ok)
                .map(|e| e.path())
                .filter(|p| p.extension().is_some_and(|e| e == "js"))
                // React ships as two bundles (react + react-dom) that must
                // load together; the dedicated `react_canary` drives them.
                // Loading react-dom alone here would falsely error.
                .filter(|p| {
                    !p.file_name()
                        .and_then(|n| n.to_str())
                        .is_some_and(|n| n.starts_with("react"))
                })
                .collect(),
            Err(_) => {
                eprintln!("no target/canary/ directory — see the doc comment for setup");
                return;
            }
        };
        entries.sort();
        assert!(
            !entries.is_empty(),
            "target/canary/ exists but holds no .js bundles"
        );

        for path in entries {
            let name = path.file_name().unwrap().to_string_lossy().into_owned();
            let source = std::fs::read(&path).unwrap();
            let kb = source.len() / 1024;
            // ES-module bundles (lit-core) need a module script tag; a
            // classic load chokes on `export`. Booting without errors is
            // the whole smoke here — lit_canary in http.rs drives Lit.
            let module = source
                .windows(7)
                .any(|w| w == b"export{" || w == b"import ");
            let tag = if module { " type=\"module\"" } else { "" };
            let html = format!(
                "<html><head><script{tag} src=\"/bundle.js\"></script></head>\
                 <body><div id=\"target\">static placeholder</div>\
                 <script>{PROBE}</script></body></html>"
            );
            let mut env = PageEnv::bare("https://example.com/");
            env.externals = vec![("/bundle.js".to_string(), Some(std::sync::Arc::new(source)))];
            let started = Instant::now();
            // Big-stack thread, like production — see `transform_on_page_stack`
            // (lazy delazify re-analyzes on the execution stack).
            let (out, outcome) = transform_on_page_stack(html, env);
            let booted = out
                .lines()
                .find(|l| l.contains("BOOTED:"))
                .unwrap_or("(no probe output)")
                .trim()
                .to_string();
            eprintln!(
                "{name} ({kb} KB): {:?} total ({:?} in scripts), {} — errors: {:?}",
                started.elapsed(),
                outcome.elapsed,
                booted,
                outcome.errors,
            );
            for marker in ["made-by-jq", "Vue renders inside TRust", "made-by-d3"] {
                if out.contains(marker) {
                    eprintln!("    proof in the rendered HTML: {marker}");
                }
            }
            for line in out.lines().filter(|l| l.contains("failed:")) {
                eprintln!("    {}", line.trim());
            }
            assert!(
                outcome.elapsed < COMPUTE_BUDGET,
                "{name} blew the page compute budget: {:?}",
                outcome.elapsed
            );
        }
    }

    /// React canary: boots the real React 18 + ReactDOM UMD bundles and
    /// renders a tree via `createRoot`. React is the biggest framework gap
    /// (no React in the jQuery/D3/Vue/Lit set); its scheduler
    /// (MessageChannel-driven) and synthetic-event system exercise platform
    /// primitives the others don't. Set TRUST_REACT_DEV=1 to load the
    /// development bundles (better error messages, far slower).
    ///
    /// ```sh
    /// cd target/canary
    /// curl -LO https://unpkg.com/react@18/umd/react.production.min.js
    /// curl -LO https://unpkg.com/react-dom@18/umd/react-dom.production.min.js
    /// cargo test --release react_canary -- --ignored --nocapture
    /// ```
    #[test]
    #[ignore = "manual canary: needs React bundles in target/canary/ and --release timings"]
    fn react_canary() {
        let dev = std::env::var("TRUST_REACT_DEV").is_ok();
        let (rf, rdf) = if dev {
            ("react.development.js", "react-dom.development.js")
        } else {
            ("react.production.min.js", "react-dom.production.min.js")
        };
        let (Ok(react), Ok(react_dom)) = (
            std::fs::read(format!("target/canary/{rf}")),
            std::fs::read(format!("target/canary/{rdf}")),
        ) else {
            eprintln!("no React bundles in target/canary/ — see the doc comment");
            return;
        };
        const PROBE: &str = r##"
            function out(s) { document.body.appendChild(document.createTextNode("\n" + s)); }
            try {
                out("React " + React.version);
                var e = React.createElement;
                var App = function () {
                    var st = React.useState("initial");
                    var count = st[0];
                    var setCount = st[1];
                    React.useEffect(function () {
                        setCount("after-effect");
                    }, []);
                    return e("div", { className: "react-app" }, [
                        e("h1", { key: "h" }, "React renders inside TRust"),
                        e("p", { key: "p", className: "made-by-react" }, "a paragraph from React"),
                        e("span", { key: "s", className: "effect-state" }, "state: " + count),
                        e("button", { key: "b", onClick: function () { setCount("clicked"); } }, "click me"),
                    ]);
                };
                var root = ReactDOM.createRoot(document.getElementById("target"));
                root.render(e(App));
                out("BOOTED-REACT");
            } catch (err) { out("react boot failed: " + (err && (err.stack || err.message) || err)); }
        "##;
        let html = format!(
            "<html><head>\
             <script src=\"/react.js\"></script>\
             <script src=\"/react-dom.js\"></script>\
             </head><body><div id=\"target\">static placeholder</div>\
             <script>{PROBE}</script></body></html>"
        );
        let mut env = PageEnv::bare("https://example.com/");
        env.externals = vec![
            ("/react.js".to_string(), Some(std::sync::Arc::new(react))),
            (
                "/react-dom.js".to_string(),
                Some(std::sync::Arc::new(react_dom)),
            ),
        ];
        let started = Instant::now();
        let (out, outcome) = transform(&html, &env);
        eprintln!(
            "react canary: {:?} total ({:?} in scripts), panicked={}, errors={:?}",
            started.elapsed(),
            outcome.elapsed,
            outcome.panicked,
            outcome.errors,
        );
        for line in out
            .lines()
            .filter(|l| l.contains("BOOTED-REACT") || l.contains("failed") || l.contains("React "))
        {
            eprintln!("  probe> {}", line.trim());
        }
        for marker in ["react-app", "made-by-react", "React renders inside TRust"] {
            if out.contains(marker) {
                eprintln!("  proof in rendered HTML: {marker}");
            }
        }
    }

    // ---- Phase 1: scripts against the real DOM ----

    fn page(html: &str) -> (String, Outcome) {
        transform(html, &PageEnv::bare("https://example.com/a/page"))
    }

    #[test]
    fn bytecode_optimizations_preserve_order_and_loop_results() {
        let (out, outcome) = page(
            r#"<body><pre id=o></pre><script>
                const order = [];
                function left() { order.push('left'); return { valueOf() { order.push('coerce-left'); return 1; } }; }
                function right() { order.push('right'); return 2; }
              function loopResult() {
                  let i = 0;
                  let sum = 0;
                  while (i < 3) {
                      if (i < 2) sum += i;
                        i++;
                    }
                    do { sum++; } while (sum < 4);
                  for (let j = 0; j < 2; j++) sum += j;
                  return sum;
              }
              function relationalBranches() {
                  let result = '';
                  if (1 <= 1) result += 'le';
                  if (2 > 1) result += 'gt';
                  if (2 >= 2) result += 'ge';
                  return result;
              }
              function argumentResult() {
                  let value = 7;
                  const array = [value, value + 1, ...[value + 2]];
                  const called = (function(a, b, c) { return a + b + c; })(value, value + 1, ...[value + 2]);
                  return array.join(',') + '|' + called;
                }
                const branch = left() < right() ? 'yes' : 'no';
              document.getElementById('o').textContent = [
                  order.join(','), branch, loopResult(), relationalBranches(), argumentResult()
              ].join('|');
            </script></body>"#,
        );
        assert!(
            outcome.errors.is_empty(),
            "page JS errors: {:?}",
            outcome.errors
        );
        assert!(
            out.contains("left,right,coerce-left|yes|5|legtge|7,8,9|24"),
            "{out}"
        );
    }

    #[test]
    fn parent_node_selector_methods_are_not_exposed_on_text_nodes() {
        // DOM Standard ParentNode: querySelector/querySelectorAll and the
        // getElementsBy* methods belong to Element, Document, and
        // DocumentFragment. CharacterData (including Text) must not expose
        // them; libraries use this distinction while processing mutation
        // records containing both elements and text nodes.
        let (out, outcome) = page(
            r#"<body><pre id=o></pre><script>
                const text = document.createTextNode('x');
                const element = document.createElement('div');
                const fragment = document.createDocumentFragment();
                document.getElementById('o').textContent = [
                    'querySelectorAll' in text,
                    'getElementsByTagName' in text,
                    'getElementsByClassName' in text,
                    typeof element.querySelectorAll,
                    typeof fragment.querySelectorAll
                ].join('|');
            </script></body>"#,
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(out.contains("false|false|false|function|function"), "{out}");
    }

    #[test]
    fn focus_management_exposes_stable_active_elements_and_tab_indices() {
        // HTML §6.6: the viewport's DOM anchor reads as body, focus() runs the
        // focus update steps, activeElement retargets through shadow roots, and
        // a detached focused area is fixed up to the viewport. React's modal
        // teardown relies on every one of these properties.
        let (out, outcome) = page(
            r#"<body><button id=a>A</button><button id=b>B</button><div id=host></div><pre id=o></pre><script>
                const a = document.getElementById('a');
                const b = document.getElementById('b');
                const log = [];
                for (const type of ['focus', 'focusin', 'blur', 'focusout']) {
                    a.addEventListener(type, () => log.push('a:' + type));
                    b.addEventListener(type, () => log.push('b:' + type));
                }
                const initial = document.activeElement === document.body;
                a.click();
                const syntheticDidNotFocus = document.activeElement === document.body;
                a.focus({preventScroll:true});
                const aFocused = document.activeElement === a;
                b.focus({preventScroll:true});
                const bFocused = document.activeElement === b;
                b.remove();
                const detachedFixedUp = document.activeElement === document.body;

                const host = document.getElementById('host');
                const root = host.attachShadow({mode:'open'});
                root.innerHTML = '<button id=inner>inner</button>';
                const inner = root.getElementById('inner');
                inner.focus({preventScroll:true});
                const retargeted = document.activeElement === host && root.activeElement === inner;

                const generic = document.createElement('div');
                generic.setAttribute('disabled', '');
                generic.tabIndex = 0;
                document.body.appendChild(generic);
                generic.focus({preventScroll:true});
                const genericDisabledAttrIgnored = document.activeElement === generic;
                const fieldset = document.createElement('fieldset');
                fieldset.setAttribute('disabled', '');
                fieldset.innerHTML = '<legend><button id=legendButton>L</button></legend><button id=blocked>blocked</button>';
                document.body.appendChild(fieldset);
                fieldset.querySelector('#blocked').focus({preventScroll:true});
                const disabledFieldsetBlocked = document.activeElement === generic;
                const legendButton = fieldset.querySelector('#legendButton');
                legendButton.focus({preventScroll:true});
                const firstLegendEscaped = document.activeElement === legendButton;

                const detached = document.createElement('button');
                const indexed = document.createElement('div');
                indexed.setAttribute('tabindex', '  +12tail');
                document.getElementById('o').textContent = [
                    initial, syntheticDidNotFocus, aFocused, bFocused, detachedFixedUp,
                    retargeted, genericDisabledAttrIgnored, disabledFieldsetBlocked,
                    firstLegendEscaped, document.hasFocus(), detached.tabIndex,
                    document.createElement('a').tabIndex, document.createElement('div').tabIndex,
                    indexed.tabIndex, log.join(',')
                ].join('|');
            </script></body>"#,
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(
            out.contains(
                "true|true|true|true|true|true|true|true|true|true|0|0|-1|12|a:focus,a:focusin,a:blur,a:focusout,b:focus,b:focusin"
            ),
            "{out}"
        );
    }

    #[test]
    fn dom_string_getters_cache_only_within_one_mutation_epoch() {
        // DOM/HTML serialization getters return the current tree state. A
        // repeated read may reuse an immutable value, but a text or attribute
        // mutation must make the next read observe the new state.
        let (out, outcome) = page(
            r#"<body><div id=a><span>old</span></div><pre id=o></pre><script>
                const a = document.getElementById('a');
                const first = [a.textContent, a.innerHTML, a.outerHTML].join('~');
                const repeat = [a.textContent, a.innerHTML, a.outerHTML].join('~');
                a.firstChild.textContent = 'new';
                const second = [a.textContent, a.innerHTML, a.outerHTML].join('~');
                a.setAttribute('data-state', 'updated');
                const third = [a.textContent, a.innerHTML, a.outerHTML].join('~');
                document.getElementById('o').textContent = [
                    first === repeat, first.includes('old'), second.includes('new'),
                    !second.includes('old'), third.includes('data-state="updated"')
                ].join('|');
            </script></body>"#,
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(out.contains("true|true|true|true|true"), "{out}");
    }

    #[test]
    fn contextual_of_can_name_a_strict_lexical_binding() {
        // ECMAScript reserves `of` only in contextual grammar positions (most
        // visibly as the separator in `for (x of y)`). It remains a valid
        // BindingIdentifier, including after `let` in strict code. Minifiers
        // legitimately emit this compact declaration shape.
        let (out, outcome) = page(
            "<body><p id=o></p><script>\"use strict\";\
             let of = 'contextual identifier';\
             document.getElementById('o').textContent = of;\
             </script></body>",
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(out.contains("contextual identifier"), "{out}");
    }

    /// Diagnostic: run an arbitrary local HTML file through the full
    /// transform and dump the result. `TRUST_JS_DIAG=/path/page.html
    /// cargo test js_diag -- --ignored --nocapture`
    #[test]
    #[ignore = "manual canary: needs target/canary/vue.global.prod.js"]
    fn vue_template_compiler_canary() {
        let Ok(vue) = std::fs::read("target/canary/vue.global.prod.js") else {
            eprintln!("no target/canary/vue.global.prod.js");
            return;
        };
        let html = "<html><head><script src='/vue.js'></script></head>\n             <body><div id='target'>{{ who }}</div><script>\n             Vue.createApp({ data: function () { return { who: 'TRust template' }; } }).mount('#target');\n             </script></body></html>";
        let mut env = PageEnv::bare("https://example.com/");
        env.externals = vec![("/vue.js".to_string(), Some(std::sync::Arc::new(vue)))];
        let (out, outcome) = transform(html, &env);
        eprintln!("vue template outcome: {:?}", outcome);
        for line in out
            .lines()
            .filter(|line| line.contains("TRust") || line.contains("failed"))
        {
            eprintln!("{}", line.trim());
        }
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(
            !outcome.panicked,
            "Vue template compiler panicked the engine"
        );
        assert!(out.contains("TRust template"), "{out}");
    }

    #[test]
    #[ignore = "manual canary: needs target/canary/vue.global.prod.js"]
    fn vue_v_for_template_compiler_canary() {
        // The real Vue in-browser compiler path for `v-for`: it builds a
        // `new Function` render whose `with(_ctx)` body feeds `_renderList` a
        // per-item closure. This is what the boa_ast scope-index fix unblocked;
        // before it, the per-item binding resolved to the wrong environment and
        // the list never rendered. Uses the shipped Vue bundle end-to-end.
        let Ok(vue) = std::fs::read("target/canary/vue.global.prod.js") else {
            eprintln!("no target/canary/vue.global.prod.js");
            return;
        };
        let html = "<html><head><script src='/vue.js'></script></head>\n             <body><ul id='target'><li v-for='item in items'>{{ item.name }}</li></ul><script>\n             Vue.createApp({ data: function () { return { items: [{ name: 'alpha' }, { name: 'beta' }, { name: 'gamma' }] }; } }).mount('#target');\n             </script></body></html>";
        let mut env = PageEnv::bare("https://example.com/");
        env.externals = vec![("/vue.js".to_string(), Some(std::sync::Arc::new(vue)))];
        let (out, outcome) = transform(html, &env);
        eprintln!("vue v-for outcome: {outcome:?}");
        for line in out.lines().filter(|line| {
            line.contains("alpha") || line.contains("beta") || line.contains("gamma")
        }) {
            eprintln!("{}", line.trim());
        }
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(!outcome.panicked, "Vue v-for compiler panicked the engine");
        assert!(
            out.contains("alpha") && out.contains("beta") && out.contains("gamma"),
            "{out}"
        );
    }

    /// Stimulus is the purest MutationObserver-driven framework: it connects a
    /// controller to any element that GAINS `data-controller`, via a
    /// MutationObserver watching the document. Here the element is injected
    /// AFTER `Application.start()` is already observing, so ONLY our
    /// MutationObserver can connect it — `connect()` running proves live MO
    /// delivery end-to-end through a real framework.
    ///   cd target/canary && curl -LO https://unpkg.com/@hotwired/stimulus@3/dist/stimulus.umd.js
    #[test]
    #[ignore = "manual canary: needs target/canary/stimulus.umd.js"]
    fn stimulus_mutation_observer_canary() {
        let Ok(stimulus) = std::fs::read("target/canary/stimulus.umd.js") else {
            eprintln!("no target/canary/stimulus.umd.js");
            return;
        };
        let html = "<html><head><script src='/stimulus.js'></script></head>\
            <body><div id='host'></div><script>\
            var app = Stimulus.Application.start();\
            app.register('hello', class extends Stimulus.Controller {\
              connect() { this.element.textContent = 'STIMULUS-CONNECTED'; }\
            });\
            setTimeout(function () {\
              var d = document.createElement('div');\
              d.setAttribute('data-controller', 'hello');\
              document.getElementById('host').appendChild(d);\
            }, 10);\
            </script></body></html>";
        let mut env = PageEnv::bare("https://example.com/");
        env.externals = vec![(
            "/stimulus.js".to_string(),
            Some(std::sync::Arc::new(stimulus)),
        )];
        let (out, outcome) = transform(html, &env);
        eprintln!("stimulus outcome: {outcome:?}");
        assert!(!outcome.panicked, "Stimulus panicked the engine");
        assert!(
            out.contains("STIMULUS-CONNECTED"),
            "Stimulus's MutationObserver must connect a dynamically-added controller: {out}"
        );
    }

    /// Alpine uses a MutationObserver to initialize `x-data` components added
    /// after start. We inject the component only after `alpine:initialized`
    /// (observer live), so it is Alpine's MutationObserver — not its initial
    /// tree walk — that runs the new node's `x-init`.
    ///   cd target/canary && curl -L -o alpine.min.js https://unpkg.com/alpinejs@3/dist/cdn.min.js
    #[test]
    #[ignore = "manual canary: needs target/canary/alpine.min.js"]
    fn alpine_mutation_observer_canary() {
        let Ok(alpine) = std::fs::read("target/canary/alpine.min.js") else {
            eprintln!("no target/canary/alpine.min.js");
            return;
        };
        // Alpine's CDN auto-start uses a readiness helper that doesn't fire in
        // our load sequence, so start it explicitly (the documented manual
        // path; Alpine guards against a double start). By `alpine:initialized`
        // its MutationObserver is live, so the node injected then is initialized
        // by that observer — exactly what we're proving.
        let html = "<html><head><script src='/alpine.js'></script></head>\
            <body><div id='host'></div><script>\
            document.addEventListener('alpine:initialized', function () {\
              var d = document.createElement('div');\
              d.setAttribute('x-data', '{}');\
              d.setAttribute('x-init', \"$el.textContent = 'ALPINE-INIT'\");\
              document.getElementById('host').appendChild(d);\
            });\
            window.Alpine.start();\
            </script></body></html>";
        let mut env = PageEnv::bare("https://example.com/");
        env.externals = vec![("/alpine.js".to_string(), Some(std::sync::Arc::new(alpine)))];
        let (out, outcome) = transform(html, &env);
        eprintln!("alpine outcome: {outcome:?}");
        assert!(!outcome.panicked, "Alpine panicked the engine");
        assert!(
            out.contains("ALPINE-INIT"),
            "Alpine's MutationObserver must initialize a dynamically-added x-data node: {out}"
        );
    }

    /// htmx 2.x uses NO MutationObserver (it processes content via
    /// `htmx.process()` / swaps), so it was never an MO proof — it was vendored
    /// alongside the MO canaries as a common-framework boot check. The honest
    /// finding: htmx is CURRENTLY BLOCKED at module init by a missing
    /// `XPathEvaluator` global — it does
    /// `(new XPathEvaluator).createExpression('.//*[@*[starts-with(name(),"hx-")…]]')`
    /// to find `hx-*` elements (CSS can't match an attribute-name prefix).
    /// Unblocking htmx needs a real XPath engine — a separate compat task, NOT
    /// part of MutationObserver. What this canary DOES pin is the robustness
    /// property that matters here: a missing platform global makes htmx DEGRADE
    /// GRACEFULLY (the page still renders, the engine does not abort), surfacing
    /// the gap as an `outcome.error` rather than a crash.
    ///   cd target/canary && curl -L -o htmx.min.js https://unpkg.com/htmx.org@2/dist/htmx.min.js
    #[test]
    #[ignore = "manual canary: needs target/canary/htmx.min.js"]
    fn htmx_boot_documents_xpath_gap() {
        let Ok(htmx) = std::fs::read("target/canary/htmx.min.js") else {
            eprintln!("no target/canary/htmx.min.js");
            return;
        };
        let html = "<html><head><script src='/htmx.js'></script></head>\
            <body><div id='present' hx-get='/x'>present</div></body></html>";
        let mut env = PageEnv::bare("https://example.com/");
        env.externals = vec![("/htmx.js".to_string(), Some(std::sync::Arc::new(htmx)))];
        let (out, outcome) = transform(html, &env);
        eprintln!("htmx outcome: {outcome:?}");
        // Graceful degrade: no engine abort, the page content survives.
        assert!(
            !outcome.panicked,
            "a missing global must not abort the engine"
        );
        assert!(out.contains("present"), "the page must still render: {out}");
        // Document the known blocker (a tripwire: if htmx ever boots clean here,
        // this flips and we update the note — htmx still wouldn't use MO).
        assert!(
            outcome.errors.iter().any(|e| e.contains("XPathEvaluator")),
            "expected the XPathEvaluator boot gap; htmx errors were: {:?}",
            outcome.errors
        );
    }

    #[test]
    fn vue_v_for_style_render_closure_runs() {
        // Vue's full template compiler emits, for `v-for`, a `new Function`-built
        // render whose `with(_ctx)` body declares block-scoped consts captured by
        // a per-item closure that takes the item as a parameter. That shape
        // tripped a Boa scope-index divergence: dynamic functions skipped the
        // `optimize_scope_indicies` pass, so the captured const resolved one
        // environment too high and the per-item closure read the wrong env.
        // Fixed in the vendored boa_ast (`optimize_function_scope_indicies`).
        // This pins the whole transform pipeline, no Vue bundle required.
        let html = r##"<body><ul id="t"></ul><script>
            var _src = {
              renderList: function (arr, cb) { return arr.map(cb).join(','); },
              display: function (x) { return String(x); }
            };
            var makeRender = new Function(
              'lib',
              "const _lib = lib\n" +
              "return function render(ctx) {\n" +
              "  with (ctx) {\n" +
              "    const { renderList: _rl, display: _ds } = _lib;\n" +
              "    return _rl(items, function (it) { return _ds(it.name); });\n" +
              "  }\n" +
              "}"
            );
            var render = makeRender(_src);
            document.getElementById('t').textContent =
              render({ items: [{ name: 'a' }, { name: 'b' }] });
            </script></body>"##;
        let (out, outcome) = transform(html, &PageEnv::bare("https://example.com/"));
        assert!(!outcome.panicked, "engine panicked: {outcome:?}");
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(out.contains("a,b"), "{out}");
    }

    #[test]
    fn switch_discriminant_function_shadow_does_not_leak_binding() {
        // chatgpt.com rendered a blank page: React Compiler ("use forget")
        // output for a component (`cEn`) shaped like this. A function-local memo
        // array `n` is used inside a `switch`'s case bodies, and the switch
        // DISCRIMINANT contains a nested arrow that declares its OWN `let n`.
        // Boa's `LexicallyScopedDeclarations(Switch)` recursed into the
        // discriminant expression and, via the `visit_function_body` override,
        // harvested the nested function's top-level `let n` — creating a PHANTOM
        // `n` binding in the switch's CaseBlock scope. A case body's use of the
        // real `n` then resolved to that phantom binding, which never received a
        // register, so the bytecompiler emitted a hard `ReferenceError: access of
        // uninitialized binding` at COMPILE time. React can't recover from a
        // render throw during hydration and unmounted the whole tree → blank
        // <body>. Fixed in vendored boa_ast: the LexicallyScopedDeclarations
        // visitor now overrides `visit_switch` to collect ONLY the case bodies,
        // never the discriminant or case conditions. General engine-correctness.
        let html = r##"<body><div id="o">?</div><script>
            function f(t) {
              let n = ['MEMO'];
              let out = [];
              switch ((() => { let n = 99; return n; }), t) {
                case 1: { let x = 'c1'; out.push(x); out.push(n[0]); }
                case 2: { let x = 'c2'; out.push(x); break; }
                default: { let x = 'def'; out.push(x); out.push(n[0]); }
              }
              return out.join(',');
            }
            document.getElementById('o').textContent =
              f(1) + ' | ' + f(2) + ' | ' + f(9);
            </script></body>"##;
        let (out, outcome) = transform(html, &PageEnv::bare("https://example.com/"));
        assert!(!outcome.panicked, "engine panicked: {outcome:?}");
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        // The memo `n` resolves correctly in every case body — and the real
        // scoping is preserved (JS fallthrough: case 1 has no `break`, so it also
        // runs case 2's body; each case's own `let x` shadows independently).
        assert!(
            out.contains("c1,MEMO,c2 | c2 | def,MEMO"),
            "switch scoping wrong: {out}"
        );
    }

    #[test]
    fn switch_case_lexical_tdz_is_preserved() {
        // Guard the fix from over-correcting: a GENUINE temporal-dead-zone access
        // (use of a `let` before its declaration in the same block) must still
        // throw a `ReferenceError` — the fix removes only the PHANTOM switch-scope
        // binding, never real TDZ semantics.
        let html = r##"<body><div id="o">?</div><script>
            function g() { let r; { r = (x); let x = 1; } return r; }
            try { g(); document.getElementById('o').textContent = 'NO-THROW'; }
            catch (e) { document.getElementById('o').textContent = 'THREW:' + e.constructor.name; }
            </script></body>"##;
        let (out, outcome) = transform(html, &PageEnv::bare("https://example.com/"));
        assert!(!outcome.panicked, "engine panicked: {outcome:?}");
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(
            out.contains("THREW:ReferenceError"),
            "TDZ not preserved: {out}"
        );
    }

    #[test]
    fn array_length_truncation_survives_inline_cache() {
        // A Boa inline-cache bug surfaced by Apollo Client's `optimism` cache
        // (and thus every Apollo + React page, e.g. Twitch channel content):
        // `arr.length = 0` compiles to SetPropertyByName, which inline-caches
        // the array's `length` storage slot. On a cache hit it wrote the new
        // length straight into storage and SKIPPED `ArraySetLength`'s element
        // truncation, so the dense backing vector kept its old elements. A
        // following `arr[0] = x` then overwrote that in-bounds (stale) slot
        // without growing `length`, leaving `length === 0` — the impossible
        // "empty but clean" state optimism reports as "unknown value". The
        // cache only fired once the `length = 0` site had run twice (a function
        // called repeatedly on a reused array). Fixed in the vendored boa fork
        // by marking the array `length` slot NOT_CACHABLE. This pins the exact
        // pattern without Apollo.
        let html = r##"<body><div id="t"></div><script>
            function recomp(o, v) { o.value.length = 0; o.value[0] = v; return o.value.length; }
            var o = { value: [] };
            var first = recomp(o, "a");   // fresh array: appends -> length 1
            var second = recomp(o, "b");  // reused: length=0 then [0]= -> must be 1
            document.getElementById('t').textContent =
              "first=" + first + " second=" + second + " v0=" + o.value[0];
            </script></body>"##;
        let (out, outcome) = transform(html, &PageEnv::bare("https://example.com/"));
        assert!(!outcome.panicked, "engine panicked: {outcome:?}");
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(out.contains("first=1 second=1 v0=b"), "{out}");
    }

    #[test]
    fn dom_parser_document_backs_a_view_transitions_swap() {
        // Astro's ClientRouter (view transitions) fetches the destination page,
        // parses it with `new DOMParser().parseFromString(html, "text/html")`,
        // then swaps: iterates `newDoc.scripts`, reads `newDoc.documentElement`
        // attributes + `newDoc.head`, and `document.body.replaceWith(newDoc.body)`.
        // The old body-fragment DOMParser lacked `.scripts` (crash) and had no
        // head/body split; a real detached Document fixes both.
        let html = r##"<html data-old><head><title>Old</title></head>
            <body><p id="here">grid</p><div id="log"></div><script>
            const src = '<html data-new><head><title>New</title></head>'
                + '<body><h1>Entry</h1><article>hello world</article></body></html>';
            const nd = new DOMParser().parseFromString(src, 'text/html');
            const parts = [];
            parts.push('type=' + nd.nodeType);
            parts.push('scripts=' + (typeof nd.scripts) + ':' + Array.from(nd.scripts).length);
            let sc = 0; for (const s of nd.scripts) sc++; parts.push('iter=' + sc);
            parts.push('docEl=' + (nd.documentElement ? nd.documentElement.tagName : 'null'));
            parts.push('head=' + (nd.head ? nd.head.children.length : -1));
            parts.push('title=' + nd.title);
            parts.push('body=' + (nd.body ? nd.body.tagName : 'null'));
            // The actual swap: replace the live body with the parsed one.
            document.body.replaceWith(nd.body);
            document.getElementById('log') && 0; // (log is inside the old body, now detached)
            // Prove the live document now shows the entry.
            window.__result = parts.join('|') + ' :: body=' + document.body.innerHTML;
            </script></body></html>"##;
        let (out, outcome) = transform(html, &PageEnv::bare("https://example.com/"));
        assert!(!outcome.panicked, "{outcome:?}");
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        // The swapped-in entry content reaches the serialized output.
        assert!(
            out.contains("Entry"),
            "swapped body should render the entry: {out}"
        );
        assert!(out.contains("hello world"), "{out}");
        // And the old grid paragraph is gone (body was replaced, not appended).
        assert!(!out.contains(">grid<"), "old body should be gone: {out}");
    }

    #[test]
    fn dom_parser_drives_a_sanitizer_style_walk() {
        // DOMPurify's core path: `new DOMParser().parseFromString(s,'text/html')`,
        // then walk it via `node.ownerDocument.createNodeIterator(body, …)`,
        // then read `body.innerHTML`. Without DOMParser the bundle threw
        // "DOMParser is not defined" / "not a callable function" and dropped
        // its content (archive.org collection pages).
        let html = r##"<body><div id="out"></div><script>
            const doc = new DOMParser().parseFromString('<p>hi</p><b>bold</b><!--c-->', 'text/html');
            const body = doc.body;
            const it = body.ownerDocument.createNodeIterator(
                body, NodeFilter.SHOW_ELEMENT | NodeFilter.SHOW_TEXT | NodeFilter.SHOW_COMMENT, null);
            const seen = [];
            let n;
            while ((n = it.nextNode())) {
                seen.push(n.nodeType === 1 ? n.tagName.toLowerCase()
                        : n.nodeType === 3 ? 't:' + n.textContent : 'comment');
            }
            document.getElementById('out').textContent = seen.join('|') + ' :: ' + body.innerHTML;
        </script></body>"##;
        let (out, outcome) = transform(html, &PageEnv::bare("https://example.com/"));
        assert!(!outcome.panicked, "{outcome:?}");
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        // Root (body) first, then descendants in document order.
        assert!(
            out.contains("body|p|t:hi|b|t:bold|comment"),
            "node iterator walked the parsed tree: {out}"
        );
        assert!(
            out.contains("&lt;p&gt;hi&lt;/p&gt;&lt;b&gt;bold&lt;/b&gt;"),
            "{out}"
        );
    }

    #[test]
    fn document_adopt_node_moves_subtrees_and_updates_owner_document() {
        let (out, outcome) = page(
            r##"<body><pre id="out"></pre><script>
                const parsed = new DOMParser().parseFromString(
                    '<div id="adopted"><span>child</span></div>', 'text/html');
                const node = parsed.body.firstElementChild;
                const before = node.ownerDocument === parsed && node.parentNode === parsed.body;
                const returned = document.adoptNode(node);
                const detached = node.parentNode === null;
                const owner = node.ownerDocument === document
                    && node.firstElementChild.ownerDocument === document;
                document.body.appendChild(returned);
                document.getElementById('out').textContent =
                    [before, detached, owner, returned === node, node.textContent].join('|');
            </script></body>"##,
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(out.contains("true|true|true|true|child"), "{out}");
    }

    #[test]
    fn document_adopt_node_runs_adopted_callback_and_rejects_special_nodes() {
        let (out, outcome) = page(
            r##"<body><pre id="out"></pre><script>
                const parsed = new DOMParser().parseFromString('', 'text/html');
                let callback = '';
                class AdoptedThing extends HTMLElement {
                    adoptedCallback(oldDocument, newDocument) {
                        callback = (oldDocument === parsed) + '|' + (newDocument === document);
                    }
                }
                customElements.define('adopted-thing', AdoptedThing);
                const custom = parsed.createElement('adopted-thing');
                parsed.body.appendChild(custom);
                document.adoptNode(custom);
                let documentError = '', shadowError = '';
                try { document.adoptNode(document); }
                catch (e) { documentError = e.name; }
                try {
                    const host = document.createElement('div');
                    document.adoptNode(host.attachShadow({mode: 'open'}));
                } catch (e) { shadowError = e.name; }
                document.getElementById('out').textContent =
                    [callback, documentError, shadowError].join('|');
            </script></body>"##,
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(
            out.contains("true|true|NotSupportedError|HierarchyRequestError"),
            "{out}"
        );
    }

    #[test]
    fn node_mutations_reject_foreign_children_before_side_effects() {
        // WHATWG DOM §4.2.3: ensure pre-insert validity rejects a reference whose parent is not
        // the insertion parent, and pre-remove rejects a node whose parent is not the receiver.
        // Both checks precede mutation-observer/custom-element side effects.
        let (out, outcome) = page(
            r##"<body><pre id="out"></pre><script>
                const left = document.createElement('section');
                const right = document.createElement('aside');
                const foreign = document.createElement('b');
                const candidate = document.createElement('i');
                right.appendChild(foreign);
                let insertError = '', removeError = '';
                try { left.insertBefore(candidate, foreign); }
                catch (error) { insertError = error.name; }
                try { left.removeChild(foreign); }
                catch (error) { removeError = error.name; }
                document.getElementById('out').textContent = [
                    insertError,
                    candidate.parentNode === null,
                    removeError,
                    foreign.parentNode === right
                ].join('|');
            </script></body>"##,
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(
            out.contains("NotFoundError|true|NotFoundError|true"),
            "{out}"
        );
    }

    // ---- CSSOM surface: CSS.supports, <style>.sheet, on* handlers ----

    #[test]
    fn css_supports_and_escape() {
        let html = r##"<body><pre id="o"></pre><script>
            function L(k,v){ document.getElementById('o').textContent += k+'='+v+'\n'; }
            L('disp', CSS.supports('display','flex'));
            L('emptyval', CSS.supports('display',''));
            L('cond', CSS.supports('(display: grid)'));
            L('sel', CSS.supports('selector(a > b.c)'));
            L('emptysel', CSS.supports('selector()'));
            L('escape', CSS.escape('#id.cls'));
            L('escdigit', CSS.escape('1a'));
        </script></body>"##;
        let (out, outcome) = transform(html, &PageEnv::bare("https://example.com/"));
        assert!(!outcome.panicked, "{outcome:?}");
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(out.contains("disp=true"), "{out}");
        // An empty value is rejected (the declaration doesn't stick).
        assert!(out.contains("emptyval=false"), "{out}");
        assert!(out.contains("cond=true"), "{out}");
        // The selector form runs the real selector engine.
        assert!(out.contains("sel=true"), "{out}");
        assert!(out.contains("emptysel=false"), "{out}");
        // CSSOM escape: non-ident chars escaped, leading digit hex-escaped.
        assert!(out.contains(r"escape=\#id\.cls"), "{out}");
        assert!(out.contains(r"escdigit=\31 a"), "{out}");
    }

    #[test]
    fn style_sheet_exposes_cssom_rules() {
        // <style>.sheet.cssRules: a style rule (with its declaration block),
        // a nested @media, an @font-face descriptor block, and an UNKNOWN
        // at-rule that must be DROPPED (real browsers omit unrecognized
        // at-rules — feature detection relies on it).
        let html = r##"<body><pre id="o"></pre><style id="s"></style><script>
            function L(k,v){ document.getElementById('o').textContent += k+'='+v+'\n'; }
            var st = document.getElementById('s');
            st.textContent = 'a.x{color:red;margin:0}'
                + '@media (min-width:1px){p{display:block}}'
                + '@font-face{font-family:Z;src:url(z)}'
                + '@totallyunknown foo{bar:1}';
            var r = st.sheet.cssRules;
            L('len', r.length);
            L('r0', r[0].constructor.name);
            L('sel', r[0].selectorText);
            L('r0len', r[0].style.length);
            L('color', r[0].style.getPropertyValue('color'));
            L('media', r[1].constructor.name);
            L('mq', r[1].media.mediaText);
            L('child', r[1].cssRules[0].selectorText);
            L('ff', r[2].constructor.name);
            L('ffdesc', r[2].style.length >= 1);
        </script></body>"##;
        let (out, outcome) = transform(html, &PageEnv::bare("https://example.com/"));
        assert!(!outcome.panicked, "{outcome:?}");
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(out.contains("len=3"), "unknown at-rule dropped: {out}");
        assert!(out.contains("r0=CSSStyleRule"), "{out}");
        assert!(out.contains("sel=a.x"), "{out}");
        assert!(out.contains("r0len=2"), "{out}");
        assert!(out.contains("color=red"), "{out}");
        assert!(out.contains("media=CSSMediaRule"), "{out}");
        assert!(out.contains("mq=(min-width:1px)"), "{out}");
        assert!(out.contains("child=p"), "{out}");
        assert!(out.contains("ff=CSSFontFaceRule"), "{out}");
        assert!(out.contains("ffdesc=true"), "{out}");
    }

