    #[test]
    fn dropping_the_handle_interrupts_a_running_actor_task() {
        let (handle, mut events) = live(
            "<body><button onclick=\"let n=0; while(true) { n = Math.imul(n + 1, 2654435761); }\">run</button><script>void 0;</script></body>",
        );
        let Some(PageEvt::Updated { html, .. }) = events.blocking_recv() else {
            panic!("expected first Updated");
        };
        let id = html
            .split("x-trust-js:")
            .nth(1)
            .and_then(|rest| rest.split(':').next())
            .unwrap()
            .parse::<usize>()
            .unwrap();
        handle.cmds.blocking_send(PageCmd::Click(id)).unwrap();
        // Drop immediately: even if the click is already executing, retirement
        // must abort it instead of waiting for its JavaScript to return.
        drop(handle);

        let deadline = Instant::now() + Duration::from_secs(2);
        loop {
            match events.try_recv() {
                Err(tokio::sync::mpsc::error::TryRecvError::Disconnected) => break,
                Err(tokio::sync::mpsc::error::TryRecvError::Empty) => {
                    assert!(
                        Instant::now() < deadline,
                        "retired actor stayed alive in running JavaScript"
                    );
                    std::thread::sleep(Duration::from_millis(10));
                }
                Ok(_) => {}
            }
        }
    }

    #[test]
    fn style_display_toggling_shows_and_hides_content() {
        // Modeled on her expandtest.html: the canonical pure-JS
        // show/hide. style writes are real DOM mutations and the
        // serializer honors display:none.
        let (handle, mut events) = live(
            "<body><a href=\"#\" id=\"toggleLink\">show/hide</a>\
             <div id=\"hiddenLinks\">\
             <a href=\"#\">Additional Link 1</a>\
             <a href=\"#\">Additional Link 2</a>\
             </div><script>\
             document.addEventListener('DOMContentLoaded', () => {\
               const t = document.getElementById('toggleLink');\
               const h = document.getElementById('hiddenLinks');\
               h.style.display = 'none';\
               t.addEventListener('click', (e) => {\
                 e.preventDefault();\
                 h.style.display = h.style.display === 'none' ? 'block' : 'none';\
               });\
             });</script></body>",
        );
        let Some(PageEvt::Updated { html, .. }) = events.blocking_recv() else {
            panic!("expected first Updated");
        };
        // The initial JS hide already took: links absent at first paint.
        assert!(!html.contains("Additional Link 1"), "{html}");
        let toggle = html
            .split("x-trust-js:")
            .nth(1)
            .and_then(|r| r.split(':').next())
            .unwrap()
            .parse::<usize>()
            .unwrap();

        // Click: shown.
        handle.cmds.blocking_send(PageCmd::Click(toggle)).unwrap();
        let Some(PageEvt::Updated { html, .. }) = events.blocking_recv() else {
            panic!("expected Updated after show");
        };
        assert!(html.contains("Additional Link 1"), "{html}");
        assert!(html.contains("Additional Link 2"), "{html}");

        // Click again: hidden, and no navigation ever happened.
        handle.cmds.blocking_send(PageCmd::Click(toggle)).unwrap();
        let Some(PageEvt::Updated { html, .. }) = events.blocking_recv() else {
            panic!("expected Updated after hide");
        };
        assert!(!html.contains("Additional Link 1"), "{html}");
    }

    #[test]
    fn inline_modules_execute_against_the_dom() {
        let (out, outcome) = page(
            "<body><div id=t></div><script type=module>\
             const t = document.getElementById('t');\
             t.textContent = 'module ran';\
             export const x = 1;\
             </script></body>",
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert_eq!(outcome.modules_skipped, 0);
        assert!(out.contains("module ran"), "{out}");
    }

    /// A function DEFERRED from Module code that references `import.meta`
    /// delazifies on first call without a parse error. Regression for
    /// fosstodon.org (Mastodon): Vite emits a lazy-import helper
    /// `function $(e){return()=>s(()=>import(`…`)…,import.meta.url)}` inside a
    /// `<script type=module>`. Lazy parsing skipped its body, and the first-call
    /// re-parse ran in the default Script goal — where `import.meta` is a
    /// SyntaxError ("invalid `import.meta` expression outside a module") — so the
    /// function became a throwing stub ("deferred function body failed to
    /// parse") and the whole app bundle died. The delazify re-parse must use the
    /// SAME goal symbol (Module) as the original parse. The body is padded past
    /// the lazy size gate (100 code points) so it is actually deferred; `meta()`
    /// is called to force the delazify.
    #[test]
    fn deferred_module_function_using_import_meta_delazifies() {
        let (out, outcome) = page(
            "<body><div id=t></div><script type=module>\
             function meta() {\
               /* padding to clear the lazy-parse size gate so this body defers */\
               var parts = [];\
               parts.push('meta');\
               parts.push(String(typeof import.meta));\
               parts.push(String(typeof import.meta.url));\
               return parts.join(':');\
             }\
             document.getElementById('t').textContent = meta();\
             export const x = 1;\
             </script></body>",
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        // `import.meta` is an object; delazify ran the real body, not the stub.
        assert!(out.contains("meta:object:"), "{out}");
    }

    #[test]
    fn dynamic_function_nested_callbacks_do_not_use_missing_lazy_source() {
        // ECMAScript CreateDynamicFunction builds source from strings rather
        // than from the page script's retained source text. Nested functions
        // therefore must not be lazy-parsed/compiled: their first-call reparse
        // would otherwise have no source span and could panic the JS engine.
        let padding = "x".repeat(180);
        let body = format!("return function generated() {{ return 42; /* {padding} */ }};");
        let html = format!(
            "<body><pre id=o></pre><script>\
             var factory = new Function({body:?});\
             var generated = factory();\
             document.getElementById('o').textContent = generated();\
             </script></body>"
        );
        let (out, outcome) = page(&html);
        assert!(
            !outcome.panicked,
            "dynamic function panicked: {:?}",
            outcome.errors
        );
        assert!(outcome.errors.is_empty(), "{outcome:?}");
        assert!(out.contains("42"), "{out}");
    }

    #[test]
    fn bare_specifier_imports_reject_without_recursive_formatting() {
        let (out, outcome) = page(
            "<body><p>kept</p><script type=module>\
             import {LitElement} from 'lit';\
             </script></body>",
        );
        assert_eq!(outcome.errors.len(), 1, "{:?}", outcome.errors);
        // Real rejection reason now (was a generic "module rejected" while
        // the cyclic-module `Debug` recursion made formatting dangerous).
        // Reaching this assert at all proves formatting didn't blow up.
        assert!(
            outcome.errors[0].contains("cannot resolve module specifier")
                && outcome.errors[0].contains("lit"),
            "{:?}",
            outcome.errors
        );
        assert!(out.contains("kept"), "{out}");
    }

    #[test]
    fn thrown_errors_carry_a_js_readable_stack() {
        // Boa captures a backtrace on every throw (backtrace_limit 50) and
        // its Display renders it, but materializing the JS error object used
        // to drop it — page JS saw no `.stack`. The fork surfaces it at the
        // `JsError::to_opaque` boundary that both catch and rejection use.
        let (out, outcome) = page(
            "<body><pre id=out></pre><script>\
             function inner() { throw new TypeError('boom'); }\
             function outer() { inner(); }\
             try { outer(); } catch (e) { \
               document.getElementById('out').textContent = e.stack || 'NO STACK'; }\
             </script></body>",
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(!out.contains("NO STACK"), "stack was empty: {out}");
        assert!(out.contains("boom"), "{out}");
        // The new capability: real call-frame lines, V8-style.
        assert!(out.contains("    at "), "no stack frames: {out}");
    }

    #[test]
    fn class_constructor_const_captured_by_closure_does_not_panic() {
        // Trap #6 (Boa fork fix): a `const`/`let` in a class-constructor body
        // captured by a closure used to abort the VM. The constructor pushed a
        // function scope UNCONDITIONALLY, but boa_parser assigns binding
        // scope-indices assuming an all-local one is elided — so the captured
        // const resolved to the empty function env (0 slots) and the define
        // opcode wrote out of bounds. Real pages (archive.org home, danbooru
        // tiles, Lit) trip exactly this. The fix makes the constructor honor
        // the same conditional-push rule regular functions use.
        let (out, outcome) = page(
            "<body><pre id=out></pre><script>\
             class C { constructor() { const x = 7; this.cmp = (a,b) => (a-b) + (x-x); } }\
             var arr=[3,1,2]; arr.sort(new C().cmp);\
             document.getElementById('out').textContent = 'sorted=' + arr.join(',');\
             </script></body>",
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(!outcome.panicked, "engine panicked (trap #6 regressed)");
        // Correct VALUE, not just non-panic: x-x=0 keeps the numeric sort.
        assert!(out.contains("sorted=1,2,3"), "{out}");
    }

    #[test]
    fn inline_cache_revalidates_prototype_shape_on_mutation() {
        // Boa fork fix: the monomorphic property inline cache guarded only the
        // RECEIVER shape. For a direct-prototype hit the cached slot indexes the
        // PROTOTYPE's own storage, so mutating the prototype (delete/redefine)
        // shifts those slots while the receiver shape is untouched — leaving the
        // cached index stale. Before the fix case (1) ABORTED the VM with an
        // out-of-bounds (len 1, index 1) and case (2) could return a silently
        // WRONG value. The fork now also pins the prototype-holder shape and
        // re-validates it on every hit.
        let (out, outcome) = page(
            "<body><pre id=out></pre><script>\
             var log = [];\
             (function () {\
               var proto = { a: 1, b: 2 };\
               var o = Object.create(proto);\
               function read() { return o.b; }\
               read(); read();           /* warm the cache (prototype hit) */\
               delete proto.a;           /* b shifts from slot 1 -> slot 0 */\
               log.push('b=' + read());  /* must be 2, must not panic */\
             })();\
             (function () {\
               var proto = { x: 10, y: 20 };\
               var o = Object.create(proto);\
               function readY() { return o.y; }\
               readY(); readY();\
               delete proto.x;           /* y -> slot 0 */\
               proto.z = 99;             /* z reuses the old slot 1 */\
               log.push('y=' + readY()); /* must still be 20, not 99 */\
             })();\
             document.getElementById('out').textContent = log.join(' ');\
             </script></body>",
        );
        assert!(
            !outcome.panicked,
            "engine panicked (inline-cache prototype OOB regressed)"
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(
            out.contains("b=2"),
            "stale prototype slot (OOB case): {out}"
        );
        assert!(
            out.contains("y=20"),
            "stale prototype slot (wrong-value case): {out}"
        );
    }

    #[test]
    fn custom_elements_render_through_shadow_dom() {
        // The Lit shape, hand-rolled: define, attachShadow, render into
        // it, slots project, attributes react, clicks work inside the
        // shadow tree.
        let (handle, mut events) = live(
            "<body><greeting-card who=\"sister\"><span slot=name>Ruby</span></greeting-card>\
             <script type=module>\
             class GreetingCard extends HTMLElement {\
               static get observedAttributes() { return ['who']; }\
               constructor() { super(); this.attachShadow({ mode: 'open' }); }\
               connectedCallback() { this.render(); }\
               attributeChangedCallback() { if (this.isConnected) this.render(); }\
               render() {\
                 this.shadowRoot.innerHTML =\
                   '<h2>Hello <slot name=name>stranger</slot>, the ' +\
                   (this.getAttribute('who') || '?') +\
                   '</h2><button id=b>rename</button>';\
                 this.shadowRoot.querySelector('#b').addEventListener('click', () => {\
                   this.setAttribute('who', 'captain');\
                 });\
               }\
             }\
             customElements.define('greeting-card', GreetingCard);\
             </script></body>",
        );
        let Some(PageEvt::Updated { html, .. }) = events.blocking_recv() else {
            panic!("expected first Updated");
        };
        // Shadow content rendered, slot projected the light child.
        assert!(
            html.contains("Hello <span slot=\"name\">Ruby</span>, the sister"),
            "{html}"
        );
        let button = html
            .split("x-trust-js:")
            .nth(1)
            .and_then(|r| r.split(':').next())
            .unwrap()
            .parse::<usize>()
            .unwrap();

        // A click inside the shadow tree mutates an observed attribute,
        // which re-renders through attributeChangedCallback.
        handle.cmds.blocking_send(PageCmd::Click(button)).unwrap();
        match events.blocking_recv() {
            Some(PageEvt::Updated { html, outcome }) => {
                assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
                assert!(html.contains("the captain"), "{html}");
                assert!(html.contains("Ruby"), "{html}");
            }
            other => panic!("expected Updated, got {other:?}"),
        }
    }

    #[test]
    fn custom_action_listener_invokes_dialog_method_on_click() {
        let (handle, mut events) = live(
            r##"<body><rpl-dialog-sheet id="consent-sheet"><button id="b"><span>Accept
             <ac-call></ac-call></span></button></rpl-dialog-sheet><script>
             class AcCall extends HTMLElement {
               connectedCallback() {
                 const parent = this.parentElement;
                 const trigger = parent && parent.matches('button') ? parent
                   : parent && parent.parentElement;
                 trigger.addEventListener('click', () => {
                   document.querySelector('#consent-sheet').hide();
                 });
                 this.remove();
               }
             }
             class RplDialogSheet extends HTMLElement {
               hide() { this.setAttribute('hidden', ''); }
             }
             customElements.define('ac-call', AcCall);
             customElements.define('rpl-dialog-sheet', RplDialogSheet);
             </script></body>"##,
        );
        let Some(PageEvt::Updated { html, outcome }) = events.blocking_recv() else {
            panic!("expected initial Updated");
        };
        assert!(outcome.errors.is_empty(), "{outcome:?}");
        let button = html
            .split("x-trust-js:")
            .nth(1)
            .and_then(|r| r.split(':').next())
            .unwrap()
            .parse::<usize>()
            .unwrap();
        handle.cmds.blocking_send(PageCmd::Click(button)).unwrap();
        let Some(PageEvt::Updated { html, outcome }) = events.blocking_recv() else {
            panic!("expected click Updated");
        };
        assert!(outcome.errors.is_empty(), "{outcome:?}");
        // The live serializer omits disconnected/hidden elements from the
        // presentation snapshot; the important observable is that the host
        // no longer survives in the rendered tree after its action runs.
        assert!(!html.contains("consent-sheet"), "{html}");
    }

    #[test]
    fn nested_shadow_slots_flatten_forwarded_gallery_pages() {
        // HTML §4.12.4: assignedNodes({flatten:true}) recursively replaces
        // slot elements with their assigned nodes. A gallery-carousel uses
        // exactly this forwarding shape: its shadow slot feeds a nested
        // faceplate-carousel slot, while the actual image pages remain light
        // children of the outer host. The serializer must retain those pages
        // for the presentation adapter instead of emitting an empty `<slot>`.
        let (out, outcome) = page(
            r##"<body><gallery-carousel>
              <ul><li slot="page-1"><img src="one.webp" width="4" height="3"></li>
                  <li slot="page-2"><img src="two.webp" width="4" height="3"></li></ul>
            </gallery-carousel><script>
              class FaceplateCarousel extends HTMLElement {
                constructor() { super(); this.attachShadow({mode:'open'}); }
                connectedCallback() { this.shadowRoot.innerHTML = '<div><slot></slot></div>'; }
              }
              class GalleryCarousel extends HTMLElement {
                constructor() { super(); this.attachShadow({mode:'open'}); }
                connectedCallback() {
                  this.shadowRoot.innerHTML = '<faceplate-carousel><slot></slot></faceplate-carousel>';
                }
              }
              customElements.define('faceplate-carousel', FaceplateCarousel);
              customElements.define('gallery-carousel', GalleryCarousel);
            </script></body>"##,
        );
        assert!(outcome.errors.is_empty(), "{outcome:?}");
        assert!(
            out.contains("one.webp") && out.contains("two.webp"),
            "{out}"
        );
        assert!(
            !out.contains("<slot"),
            "forwarding slots must not replace pages: {out}"
        );
    }

    #[test]
    fn slotchange_drives_named_shadow_slot_carousel() {
        // WHATWG DOM §4.2.2.3/4: inserting the initial default slot assigns
        // the host's light children, queues one bubbling/non-composed
        // `slotchange`, and exposes those children through assignedElements().
        // Web-component carousels use that callback to name their slides.
        let (out, outcome) = page(
            "<body><x-carousel id=c><a>One</a><a>Two</a></x-carousel><script>\
             const host = document.getElementById('c');\
             const root = host.attachShadow({ mode: 'open' });\
             const initial = document.createElement('slot');\
             initial.addEventListener('slotchange', (event) => {\
               const items = initial.assignedElements();\
               document.body.setAttribute('data-slotchange',\
                 event.bubbles + ':' + event.composed + ':' + items.length);\
               root.innerHTML = '<ul><li><slot name=slide-0></slot></li>' +\
                 '<li><slot name=slide-1></slot></li></ul>';\
               items.forEach((item, index) => item.slot = 'slide-' + index);\
             });\
             root.appendChild(initial);\
             </script></body>",
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(
            out.contains("data-slotchange=\"true:false:2\""),
            "slotchange or assignedElements regressed: {out}"
        );
        assert!(
            out.contains("<li><a slot=\"slide-0\">One</a></li>"),
            "{out}"
        );
        assert!(
            out.contains("<li><a slot=\"slide-1\">Two</a></li>"),
            "{out}"
        );
    }

    #[test]
    fn a_custom_element_defined_after_insertion_into_shadow_upgrades() {
        // archive.org's router renders the page component into a shadow
        // tree BEFORE its module defines it; define()'s catch-up upgrade
        // must pierce shadow roots (document.querySelectorAll does not),
        // or the element never constructs and the page stays an empty
        // shell. The connectedCallback writing a LIGHT-dom node proves it
        // upgraded AND connected through the shadow boundary.
        let (out, outcome) = page(
            "<body><div id=host></div><p id=result>NOT</p><script>\
             const host = document.getElementById('host');\
             const sr = host.attachShadow({ mode: 'open' });\
             sr.innerHTML = '<late-el></late-el>';\
             class LateEl extends HTMLElement {\
               connectedCallback() { document.getElementById('result').textContent = 'UPGRADED'; }\
             }\
             customElements.define('late-el', LateEl);\
             </script></body>",
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(out.contains(">UPGRADED<"), "{out}");
    }

    #[test]
    fn define_catch_up_upgrades_every_existing_instance_in_order() {
        // define()'s catch-up upgrade is now backed by a Rust composed-tree
        // walk (__dom_upgrade_candidates), not a JS per-node recursion — it
        // must still find EVERY pre-existing instance (GitHub SSRs many of one
        // custom element) and upgrade them in document order, including one
        // inside a shadow root. Each connectedCallback appends its data-n to a
        // shared log; the log proves count, completeness, and order.
        let (out, outcome) = page(
            "<body><div id=log></div>\
             <my-el data-n=1></my-el><my-el data-n=2></my-el>\
             <div id=host></div>\
             <my-el data-n=4></my-el><script>\
             const host = document.getElementById('host');\
             const sr = host.attachShadow({ mode: 'open' });\
             sr.innerHTML = '<my-el data-n=3></my-el>';\
             class MyEl extends HTMLElement {\
               connectedCallback() {\
                 const l = document.getElementById('log');\
                 l.textContent = l.textContent + this.getAttribute('data-n');\
               }\
             }\
             customElements.define('my-el', MyEl);\
             </script></body>",
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        // All four instances upgraded+connected, in document (pre-)order — the
        // shadow instance (#3) sits at its host's tree position.
        assert!(out.contains(">1234<"), "expected log 1234, got: {out}");
    }

    #[test]
    fn import_node_upgrades_defined_custom_elements_before_returning() {
        // DOM §4.5 `importNode` passes the importing document and its custom
        // element registry into "clone a node". Creating each defined clone
        // therefore queues an upgrade reaction, and [CEReactions] invokes the
        // constructors after the complete clone but BEFORE importNode returns.
        // Template binders depend on that ordering: assigning `.data` to the
        // detached imported element must hit its reactive prototype setter,
        // not create an own property that shadows the setter at insertion.
        let (out, outcome) = page(
            "<body><template id=t><reactive-card></reactive-card></template>\
             <p id=state></p><script>\
             let constructed = 0, connected = 0;\
             class ReactiveCard extends HTMLElement {\
               constructor() { super(); constructed++; this._data = 'default'; }\
               set data(value) { this._data = value; }\
               get data() { return this._data; }\
               connectedCallback() { connected++; this.textContent = this._data; }\
             }\
             customElements.define('reactive-card', ReactiveCard);\
             const fragment = document.importNode(\
               document.getElementById('t').content, true);\
             const card = fragment.firstElementChild;\
             document.getElementById('state').textContent =\
               (card instanceof ReactiveCard) + ':' + constructed + ':' + connected\
               + ':' + Object.prototype.hasOwnProperty.call(card, 'data');\
             card.data = 'Bound before insertion';\
             document.body.appendChild(fragment);\
             </script></body>",
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(
            out.contains(">true:1:0:false<"),
            "import must upgrade, but not connect, before returning: {out}"
        );
        assert!(out.contains(">Bound before insertion<"), "{out}");
    }

    #[test]
    fn crypto_subtle_digest_and_random_work() {
        // Real SHA-1/256/384/512 (libraries hash request ids before they
        // fetch — archive.org's collection search gates its tile fetch
        // on a SHA-1 uid; ChatGPT's boot hashes with SHA-512) plus
        // functional getRandomValues/randomUUID. Known-answer vectors for
        // the input 'abc' (FIPS 180-4).
        let (out, outcome) = page(
            "<body><p id=s1></p><p id=s256></p><p id=s384></p><p id=s512></p><p id=rng></p><script>\
             const hex = (b) => [...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('');\
             const enc = new TextEncoder();\
             Promise.all([\
               crypto.subtle.digest('SHA-1', enc.encode('abc')).then(b=>{document.getElementById('s1').textContent=hex(b);}),\
               crypto.subtle.digest('SHA-256', enc.encode('abc')).then(b=>{document.getElementById('s256').textContent=hex(b);}),\
               crypto.subtle.digest('SHA-384', enc.encode('abc')).then(b=>{document.getElementById('s384').textContent=hex(b);}),\
               crypto.subtle.digest({name:'SHA-512'}, enc.encode('abc')).then(b=>{document.getElementById('s512').textContent=hex(b);}),\
             ]);\
             const u = crypto.randomUUID();\
             const r = crypto.getRandomValues(new Uint8Array(8));\
             document.getElementById('rng').textContent =\
               (u.length === 36 && u[14] === '4' && r.length === 8 && typeof r[0] === 'number') ? 'ok' : 'bad';\
             </script></body>",
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(
            out.contains("a9993e364706816aba3e25717850c26c9cd0d89d"),
            "sha1: {out}"
        );
        assert!(
            out.contains("ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad"),
            "sha256: {out}"
        );
        assert!(
            out.contains("cb00753f45a35e8bb5a03d699ac65007272c32ab0eded1631a8b605a43ff5bed8086072ba1e7cc2358baeca134c825a7"),
            "sha384: {out}"
        );
        assert!(
            out.contains("ddaf35a193617abacc417349ae20413112e6fa4e89a97ea20a9eeee64b55d39a2192992a274fc1a836ba3c23a3feebbd454d4423643ce80e2a9ac94fa54ca49f"),
            "sha512: {out}"
        );
        assert!(out.contains(">ok<"), "rng: {out}");
    }

    #[test]
    fn attr_node_methods_round_trip() {
        // DOM §4.9.2 Attr-node surface: React DOM's property commit reads
        // getAttributeNode then removeAttributeNode (a missing removeAttributeNode
        // threw "undefined is not a callable" on chatgpt.com). Exercise the whole
        // set: getAttributeNode, removeAttributeNode, createAttribute +
        // setAttributeNode, and the NamedNodeMap set/removeNamedItem twins.
        let (out, outcome) = page(
            "<body><div id=d data-x=1 title=hi></div><p id=o></p><script>\
             const d = document.getElementById('d');\
             const parts = [];\
             const an = d.getAttributeNode('data-x');\
             parts.push('n=' + an.name + ',v=' + an.value + ',owner=' + (an.ownerElement === d));\
             const removed = d.removeAttributeNode(an);\
             parts.push('rm=' + removed.name + ',has=' + d.hasAttribute('data-x'));\
             const na = document.createAttribute('data-y');\
             na.value = 'yes';\
             d.setAttributeNode(na);\
             parts.push('set=' + d.getAttribute('data-y'));\
             d.attributes.setNamedItem(document.createAttribute('data-z'));\
             parts.push('map=' + d.hasAttribute('data-z'));\
             d.attributes.removeNamedItem('title');\
             parts.push('rmmap=' + d.hasAttribute('title'));\
             parts.push('gone=' + (d.getAttributeNode('nope') === null));\
             document.getElementById('o').textContent = parts.join('|');\
             </script></body>",
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(
            out.contains("n=data-x,v=1,owner=true"),
            "getAttributeNode: {out}"
        );
        assert!(
            out.contains("rm=data-x,has=false"),
            "removeAttributeNode: {out}"
        );
        assert!(out.contains("set=yes"), "setAttributeNode: {out}");
        assert!(out.contains("map=true"), "setNamedItem: {out}");
        assert!(out.contains("rmmap=false"), "removeNamedItem: {out}");
        assert!(out.contains("gone=true"), "missing node null: {out}");
    }

    #[test]
    fn dom_exception_is_a_real_constructor() {
        // core-js's DOMException polyfill reads getBuiltIn("DOMException")
        // .prototype during detection; undefined → ToObject throw that
        // tore down danbooru's init. It must be a real Error subclass.
        let (out, outcome) = page(
            "<body><p id=o></p><script>\
             const e = new DOMException('boom', 'NotFoundError');\
             document.getElementById('o').textContent = [\
               e instanceof Error, e.name, e.message, e.code,\
               DOMException.NOT_FOUND_ERR, Object.prototype.toString.call(e)\
             ].join('|');\
             </script></body>",
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(
            out.contains("true|NotFoundError|boom|8|8|[object DOMException]"),
            "{out}"
        );
    }

    #[test]
    fn host_objects_are_tagged_not_plain() {
        // window/document must report a host tag, else a deep-merge/clone
        // (jQuery UI widget.extend via isPlainObject) follows window.window
        // / document.defaultView in an infinite cycle (broke danbooru).
        let (out, outcome) = page(
            "<body><p id=o></p><script>\
             const t = (x) => Object.prototype.toString.call(x);\
             document.getElementById('o').textContent =\
               [t(window), t(document), t({})].join('|');\
             </script></body>",
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(
            out.contains("[object Window]|[object HTMLDocument]|[object Object]"),
            "{out}"
        );
    }

    #[test]
    fn element_attributes_is_an_array_like_named_node_map() {
        // Alpine.js morphs the DOM with `Array.from(el.attributes)`;
        // a missing `attributes` made that `Array.from(undefined)` →
        // ToObject throw that aborted danbooru's post-grid render.
        let (out, outcome) = page(
            "<body><div id=root title=hi data-x=7></div><p id=o></p><script>\
             const d = document.getElementById('root');\
             const attrs = Array.from(d.attributes);\
             const by = (n) => attrs.find((a) => a.name === n);\
             document.getElementById('o').textContent = [\
               attrs.length, d.attributes.length, by('data-x').value,\
               by('title').value, by('id').value, d.attributes.getNamedItem('id').value\
             ].join('|');\
             </script></body>",
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(out.contains(">3|3|7|hi|root|root<"), "{out}");
    }

    #[test]
    fn named_node_map_supports_named_property_access() {
        // A real NamedNodeMap exposes each attribute by name as well as by
        // index (WebIDL named getter): `el.attributes["title"]` returns the
        // Attr. jQuery's event-support probe reads
        // `div.attributes[eventName].expando` after setAttribute; without the
        // named getter that was `undefined.expando` → a ToObject throw that
        // aborted jQuery's boot on humblebundle.com.
        let (out, outcome) = page(
            "<body><div id=root title=hi></div><p id=o></p><script>\
             const d = document.getElementById('root');\
             d.setAttribute('onsubmit', 't');\
             const named = d.attributes['title'];\
             const probe = false === d.attributes['onsubmit'].expando;\
             document.getElementById('o').textContent =\
               [named.value, named.name, probe, String(d.attributes['nope'])].join('|');\
             </script></body>",
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        // named['title'] resolves to its Attr; the jQuery probe runs without
        // throwing; a missing name is undefined (not an error).
        assert!(out.contains(">hi|title|false|undefined<"), "{out}");
    }

    #[test]
    fn webcomponents_loader_feature_probes_pass() {
        // The exact probes @webcomponents/webcomponents-loader.js runs
        // (archive.org ships it). Failing any of them makes a real page
        // try to polyfill itself to death: template content must survive
        // cloneNode, innerHTML, and report as a DocumentFragment; module
        // bundles also want TextEncoder/TextDecoder.
        let (out, outcome) = page(
            r##"<body><div id=out></div><script>
            var t = document.createElement('template');
            var ok = [];
            ok.push('content' in t);
            ok.push(t.content.cloneNode() instanceof DocumentFragment);
            var t2 = document.createElement('template');
            t2.content.appendChild(document.createElement('div'));
            t.content.appendChild(t2);
            var clone = t.cloneNode(true);
            ok.push(clone.content.childNodes.length === 1
                && clone.content.firstChild.content.childNodes.length === 1);
            var holder = document.createElement('div');
            holder.innerHTML = '<template><p>parsed</p></template>';
            ok.push(holder.firstChild.content.childNodes.length === 1);
            var enc = new TextEncoder().encode("héllo ☃");
            ok.push(enc instanceof Uint8Array && enc.length === 10);
            ok.push(new TextDecoder().decode(enc) === "héllo ☃");
            document.getElementById('out').textContent = ok.join(' ');
            </script></body>"##,
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(
            out.contains("true true true true true true"),
            "feature probes failed: {out}"
        );
    }

    #[test]
    fn intl_shim_formats_honestly_and_passes_feature_detection() {
        // The en-only prelude shim (measured against Boa's
        // half-built intl_bundled and chosen over it). Output is honest
        // English, and the detection surface (resolvedOptions,
        // supportedLocalesOf) exists so i18n libraries take their
        // native path instead of polyfilling or dying.
        let (out, outcome) = page(
            r##"<body><div id=out></div><script>
            var ok = [];
            ok.push(new Intl.NumberFormat().format(1234567.5) === "1,234,567.5");
            ok.push(new Intl.NumberFormat("en", { style: "currency", currency: "USD" }).format(-5) === "-$5.00");
            ok.push(new Intl.NumberFormat("en", { style: "percent" }).format(0.12) === "12%");
            ok.push((1234.5).toLocaleString() === "1,234.5");
            ok.push(new Intl.DateTimeFormat("en", { year: "numeric", month: "short", day: "numeric" })
                .format(new Date(2026, 5, 12)) === "2026-06-12");
            var c = new Intl.Collator("en", { sensitivity: "base", numeric: true });
            ok.push(["b10", "A2", "a1"].sort(c.compare).join(",") === "a1,A2,b10");
            ok.push(new Intl.DisplayNames("en", { type: "region" }).of("US") === "US");
            ok.push(new Intl.PluralRules().select(1) === "one" && new Intl.PluralRules().select(3) === "other");
            ok.push(new Intl.RelativeTimeFormat().format(-2, "day") === "2 days ago");
            ok.push(Intl.NumberFormat.supportedLocalesOf(["en-US", "fr"]).join(",") === "en-US");
            ok.push(new Intl.NumberFormat().resolvedOptions().locale === "en-US");
            // NumberFormat/DateTimeFormat/Collator are specced callable WITHOUT
            // `new` (Humble Bundle does `Intl.NumberFormat(loc,opts).format(x)`);
            // instanceof and the prototype methods must still work either way.
            ok.push(Intl.NumberFormat("en", { style: "currency", currency: "EUR" }).format(12.99) === "€12.99");
            ok.push(Intl.NumberFormat() instanceof Intl.NumberFormat);
            ok.push(Intl.DateTimeFormat(0, { year: "numeric", month: "numeric", day: "numeric" })
                .format(new Date(2026, 5, 12)) === "2026-06-12");
            ok.push(typeof Intl.Collator("en").compare === "function");
            // Intl.Locale (ECMA-402): parse subtags + -u- keywords, maximize
            // via the likely-subtags map. @formatjs/intl-localematcher builds
            // `new Intl.Locale(tag).maximize()` at Mastodon boot; a missing
            // ctor blanked the whole SPA.
            ok.push(new Intl.Locale("en").maximize().toString() === "en-Latn-US");
            ok.push(new Intl.Locale("EN-us").language === "en" && new Intl.Locale("en-US").region === "US");
            ok.push(new Intl.Locale("zh").maximize().script === "Hans");
            var loc = new Intl.Locale("ja-Jpan-JP-u-ca-japanese-hc-h12");
            ok.push(loc.language === "ja" && loc.script === "Jpan" && loc.region === "JP");
            ok.push(loc.calendar === "japanese" && loc.hourCycle === "h12" && loc.baseName === "ja-Jpan-JP");
            ok.push(new Intl.Locale("en-Latn-US").minimize().toString() === "en");
            ok.push(new Intl.Locale("en", { region: "GB", numeric: true }).toString() === "en-GB-u-kn-true");
            document.getElementById('out').textContent = ok.join(' ');
            </script></body>"##,
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(
            out.contains(
                "true true true true true true true true true true true true true true true \
                 true true true true true true true"
            ),
            "Intl probes failed: {out}"
        );
    }

    /// Intl.Segmenter (ECMA-402): chatgpt.com/auth/login does `new
    /// Intl.Segmenter(...)` for text metrics — without it that threw "not a
    /// constructor". en/approximate like the rest of the shim: grapheme clusters
    /// merge combining marks/ZWJ/flags, word segments carry `isWordLike` and
    /// cover the whole string, sentences split on terminators.
    #[test]
    fn intl_segmenter_segments_graphemes_words_and_sentences() {
        let (out, outcome) = page(
            r##"<body><div id=out></div><script>
            var ok = [];
            ok.push(typeof Intl.Segmenter === "function");
            var g = new Intl.Segmenter("en", { granularity: "grapheme" });
            ok.push(Array.from(g.segment("Hi!"), function (s) { return s.segment; }).join("|") === "H|i|!");
            ok.push(Array.from(g.segment("café")).length === 4);
            var w = new Intl.Segmenter("en", { granularity: "word" });
            var wsegs = Array.from(w.segment("Hello, world!"));
            ok.push(wsegs.map(function (s) { return s.segment; }).join("") === "Hello, world!");
            ok.push(wsegs[0].isWordLike === true && wsegs[0].segment === "Hello" && wsegs[0].index === 0);
            ok.push(wsegs[1].isWordLike === false && wsegs[1].segment === ",");
            ok.push(wsegs[0].input === "Hello, world!");
            ok.push(w.segment("Hello, world!").containing(8).segment === "world");
            var s = new Intl.Segmenter("en", { granularity: "sentence" });
            ok.push(Array.from(s.segment("Hi there. How are you?")).length === 2);
            ok.push(new Intl.Segmenter().resolvedOptions().granularity === "grapheme");
            ok.push(Object.prototype.toString.call(new Intl.Segmenter()) === "[object Intl.Segmenter]");
            var threw = false; try { new Intl.Segmenter("en", { granularity: "bogus" }); } catch (e) { threw = (e.name === "RangeError"); }
            ok.push(threw);
            document.getElementById('out').textContent = ok.join(' ');
            </script></body>"##,
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(
            out.contains("true true true true true true true true true true true true"),
            "Intl.Segmenter probes failed: {out}"
        );
    }

    #[test]
    fn date_parses_microsecond_timestamps_like_a_browser() {
        // Real-world servers emit sub-millisecond ISO timestamps (Python
        // `isoformat`, databases): `…02.200128Z` (microseconds). Browsers
        // accept any number of fractional digits, truncating to milliseconds;
        // Boa rejected anything but exactly 3 → an Invalid Date that threw in
        // humblebundle.com's bundle-page DOMContentLoaded handler. Fixed in the
        // Boa fork (lenient fractional-seconds parse).
        let (out, outcome) = page(
            "<body><p id=o></p><script>\
             const ms = Date.parse('2026-06-20T11:52:02.200128Z');\
             const ns = new Date('2026-06-20T11:52:02.200128456Z');\
             document.getElementById('o').textContent =\
               [!isNaN(ms), new Date(ms).getUTCMilliseconds(), ns.toISOString()].join('|');\
             </script></body>",
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(out.contains(">true|200|2026-06-20T11:52:02.200Z<"), "{out}");
    }

    #[test]
    fn element_geometry_reports_fractional_css_pixel_boxes() {
        // getBoundingClientRect / offset* now return the element's REAL laid-out
        // CSS-pixel box (a layout pass over the live DOM), not the viewport
        // fiction and not terminal-cell-rounded geometry. Its left edge sits at
        // the body's 8px UA margin; fractional specified dimensions survive the
        // layout/JS boundary.
        let (out, outcome) = page(
            r##"<body><div id=probe style="display:inline-block;width:123.5px;height:45.25px">HELLO</div><div id=out></div><script>
            var p = document.getElementById('probe');
            var r = p.getBoundingClientRect();
            document.getElementById('out').textContent =
                [r.left, r.width, r.height, p.offsetWidth, p.offsetHeight].join(' ');
            </script></body>"##,
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(
            out.contains("8 123.5 45.25 123.5 45.25"),
            "geometry should preserve the real CSS-pixel box, got: {out}"
        );
    }

    #[test]
    fn scroll_width_is_scrolling_area_not_border_box() {
        // CSSOM View §6: getBoundingClientRect()/clientWidth report the
        // element's 320px box, while scrollWidth reports the full 720px flex
        // strip. Components use this comparison to show carousel controls.
        let (out, outcome) = page(
            r##"<body><div id=strip style="display:flex;width:320px;overflow-x:scroll">
              <div style="min-width:max-content"><div style="width:240px">one</div></div>
              <div style="min-width:max-content"><div style="width:240px">two</div></div>
              <div style="min-width:max-content"><div style="width:240px">three</div></div>
            </div><p id=out></p><script>
            var s = document.getElementById('strip');
            document.getElementById('out').textContent =
              [s.getBoundingClientRect().width, s.clientWidth, s.scrollWidth].join('|');
            </script></body>"##,
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(out.contains(">320|320|720<"), "{out}");
    }

    #[test]
    fn scroll_by_moves_a_snapping_element_and_queues_scroll_events() {
        // CSSOM View §6 + CSS Scroll Snap 1 §§4/6, end to end. This is the
        // standards-shaped interaction used by archive.org's basic-carousel:
        // an arrow calls scrollBy(clientWidth), the x/mandatory strip selects
        // the nearest start snap position, the app receives the new horizontal
        // offset, and the element's async scroll/scrollend handlers run. The
        // modern API also returns the completion Promise from "perform a
        // scroll" rather than undefined.
        fn id_after(html: &str, marker: &str) -> usize {
            let start = html
                .find(marker)
                .unwrap_or_else(|| panic!("marker {marker} not in {html}"))
                + marker.len();
            html[start..]
                .chars()
                .take_while(char::is_ascii_digit)
                .collect::<String>()
                .parse()
                .unwrap()
        }
        fn next_render(events: &mut tokio::sync::mpsc::Receiver<PageEvt>) -> String {
            let deadline = std::time::Instant::now() + Duration::from_secs(10);
            while std::time::Instant::now() < deadline {
                match events.try_recv() {
                    Ok(PageEvt::Updated { html, .. }) | Ok(PageEvt::Static { html, .. }) => {
                        return html;
                    }
                    Ok(_) => {}
                    Err(tokio::sync::mpsc::error::TryRecvError::Empty) => {
                        std::thread::sleep(Duration::from_millis(20));
                    }
                    Err(_) => break,
                }
            }
            panic!("no render received");
        }

        let html = r##"<body>
          <div id=host>
            <div slot=slide-0>one</div>
            <div slot=slide-1>two</div>
            <div slot=slide-2>three</div>
          </div>
          <p id=out>idle</p>
          <a href="#" onclick="window.scrollPromise=window.strip.scrollBy({left:window.strip.clientWidth,behavior:'smooth'});return false">next</a>
          <a href="#" onclick="window.scrollPromise=window.strip.scrollBy({left:-window.strip.clientWidth,behavior:'smooth'});return false">previous</a>
          <script>
            var root=document.getElementById('host').attachShadow({mode:'open'});
            root.innerHTML='<div id="strip" style="display:flex;width:90px;overflow-x:scroll;scroll-snap-type:x mandatory">'+
              '<div style="flex:0 0 100px;scroll-snap-align:start"><slot name="slide-0"></slot></div>'+
              '<div style="flex:0 0 100px;scroll-snap-align:start"><slot name="slide-1"></slot></div>'+
              '<div style="flex:0 0 100px;scroll-snap-align:start"><slot name="slide-2"></slot></div></div>';
            window.strip=root.getElementById('strip');
            var ends=0;
            document.getElementById('out').textContent='initial='+strip.clientWidth+'/'+strip.scrollWidth+'/'+root.querySelectorAll('slot').length;
            strip.addEventListener('scroll',function(){
              document.getElementById('out').textContent='scroll='+strip.scrollLeft+' promise='+(!!scrollPromise&&typeof scrollPromise.then==='function')+' ends='+ends;
            });
            strip.addEventListener('scrollend',function(){
              ends++; document.getElementById('out').textContent='scroll='+strip.scrollLeft+' promise='+(!!scrollPromise&&typeof scrollPromise.then==='function')+' ends='+ends;
            });
          </script>
        </body>"##;
        let (handle, mut events) =
            spawn_page(html.to_string(), PageEnv::bare("https://example.com/"));
        let first = next_render(&mut events);
        assert!(
            first.contains("initial=90/300/3"),
            "slotted strip should expose its 90px scrollport and 300px scrolling area: {first}"
        );
        let strip_at = first
            .find("id=\"strip\"")
            .unwrap_or_else(|| panic!("strip not serialized: {first}"));
        let strip_node = id_after(&first[strip_at..], "data-trust-node=\"");
        let next_marker = first.find("x-trust-js:").unwrap();
        let next_id = id_after(&first[next_marker..], "x-trust-js:");
        let previous_id = id_after(&first[next_marker + "x-trust-js:".len()..], "x-trust-js:");

        handle.cmds.blocking_send(PageCmd::Click(next_id)).unwrap();
        let deadline = std::time::Instant::now() + Duration::from_secs(10);
        let mut moved = false;
        let mut rendered = None;
        while std::time::Instant::now() < deadline && (!moved || rendered.is_none()) {
            match events.try_recv() {
                Ok(PageEvt::Scrolled { node, top, left }) => {
                    assert_eq!(node, strip_node);
                    assert_eq!(top, 0.0);
                    assert_eq!(left, 100.0, "90px intended endpoint snaps to 100px");
                    moved = true;
                }
                Ok(PageEvt::Updated { html, .. }) | Ok(PageEvt::Static { html, .. }) => {
                    if html.contains("scroll=100 promise=true ends=1") {
                        rendered = Some(html);
                    }
                }
                Ok(_) => {}
                Err(tokio::sync::mpsc::error::TryRecvError::Empty) => {
                    std::thread::sleep(Duration::from_millis(20));
                }
                Err(_) => break,
            }
        }
        assert!(moved, "scrollBy did not emit the horizontal Scrolled state");
        assert!(
            rendered.is_some(),
            "queued scroll/scrollend events or completion Promise semantics failed"
        );

        handle
            .cmds
            .blocking_send(PageCmd::Click(previous_id))
            .unwrap();
        let deadline = std::time::Instant::now() + Duration::from_secs(10);
        let mut returned = false;
        let mut rerendered = false;
        while std::time::Instant::now() < deadline && (!returned || !rerendered) {
            match events.try_recv() {
                Ok(PageEvt::Scrolled { node, top, left }) => {
                    assert_eq!(node, strip_node);
                    assert_eq!((top, left), (0.0, 0.0));
                    returned = true;
                }
                Ok(PageEvt::Updated { html, .. }) | Ok(PageEvt::Static { html, .. }) => {
                    rerendered |= html.contains("scroll=0 promise=true ends=2");
                }
                Ok(_) => {}
                Err(tokio::sync::mpsc::error::TryRecvError::Empty) => {
                    std::thread::sleep(Duration::from_millis(20));
                }
                Err(_) => break,
            }
        }
        drop(handle);
        assert!(returned, "the previous arrow did not restore scrollLeft=0");
        assert!(rerendered, "the reverse scroll events did not rerender");
    }

    #[test]
    fn opacity_zero_placeholder_reports_its_real_clipped_height() {
        // React virtualized-list
        // placeholder is `opacity:0` + a cached height + `overflow:hidden`
        // (Mastodon's off-screen articles). `opacity:0` suppresses PAINT not box
        // generation, so getBoundingClientRect must report the real 128px box —
        // NOT the collapsed/viewport-fallback height that made the list mis-size
        // its scroll extent and stop windowing. The 8-row (128px) box also CLIPS
        // the taller content, so the reported height is exactly 128, never the
        // unclipped article's extent. cell_px 8x16 ⇒ 128px = 8 rows.
        let (out, outcome) = page(
            r##"<body>
            <div id=ph style="height:128px;overflow:hidden;opacity:0">l1<br>l2<br>l3<br>l4<br>l5<br>l6<br>l7<br>l8<br>l9<br>l10<br>l11<br>l12</div>
            <div id=out></div><script>
            var r = document.getElementById('ph').getBoundingClientRect();
            document.getElementById('out').textContent =
                r.height + '|' + document.getElementById('ph').offsetHeight;
            </script></body>"##,
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(
            out.contains(">128|128<"),
            "opacity:0 placeholder reports its real (clipped) 128px box, got: {out}"
        );
    }

    #[test]
    fn visibility_hidden_element_reports_its_real_box() {
        // Phase 2: `visibility:hidden` is paint suppression (CSS2 §11.2), not box
        // removal — the element is fully laid out, so getBoundingClientRect
        // reports its real fractional CSS-pixel box (not 0, not the viewport).
        // Exercises the visibility bake through the JS
        // serialize→re-parse→measure pipeline.
        let (out, outcome) = page(
            r##"<body><div id=probe style="visibility:hidden;display:inline-block;width:123.5px;height:45.25px">HELLO</div><div id=out></div><script>
            var r = document.getElementById('probe').getBoundingClientRect();
            document.getElementById('out').textContent = [r.width, r.height].join(' ');
            </script></body>"##,
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(
            out.contains(">123.5 45.25<"),
            "visibility:hidden keeps its real CSS-pixel box, got: {out}"
        );
    }

    #[test]
    fn boxless_elements_report_a_zero_rect_not_the_viewport() {
        // Phase 3 (CSSOM View): an element with NO CSS layout box —
        // `display:none` or detached — returns an ALL-ZERO rect (and
        // offsetWidth/Height 0), NOT the whole viewport. A connected replaced
        // element the measurement pass SKIPs (`<svg>`) keeps a non-zero hedge
        // (it has a real box in a browser; our layout just can't compute it). A
        // visible element still reports its real box.
        let (out, outcome) = page(
            r##"<body>
            <div id=vis>shown</div>
            <div id=none style="display:none">hidden</div>
            <div id=out></div><script>
            var none = document.getElementById('none').getBoundingClientRect();
            var noneW = document.getElementById('none').offsetWidth;
            var noneH = document.getElementById('none').offsetHeight;
            var det = document.createElement('div').getBoundingClientRect();  // detached
            var svg = document.createElement('svg'); document.body.appendChild(svg);
            var svgr = svg.getBoundingClientRect();
            var vis = document.getElementById('vis').getBoundingClientRect();
            document.getElementById('out').textContent = [
              none.width, none.height, noneW, noneH,   // display:none -> 0 0 0 0
              det.width, det.height,                   // detached -> 0 0
              svgr.width > 0,                          // connected <svg> hedge -> true
              vis.width > 0 && vis.height > 0          // visible -> true
            ].join('|');
            </script></body>"##,
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(
            out.contains(">0|0|0|0|0|0|true|true<"),
            "boxless elements report a zero rect; svg keeps a hedge; visible has a box: {out}"
        );
    }

    #[test]
    fn computed_style_reports_ua_default_display() {
        // getComputedStyle(el).display reports the HTML UA stylesheet default
        // for an element with no author `display` (block/inline/list-item/…).
        // jQuery's `.show()` reads this to learn an element's default display;
        // an empty value sent it down a temp-`<iframe>` probe
        // (`iframe.contentWindow.document`) the prelude can't satisfy, throwing
        // and tearing down Marionette's render path on humblebundle.com. An
        // author rule still wins over the UA default.
        let (out, outcome) = page(
            "<head><style>#styled{display:flex}</style></head>\
             <body><div id=d>x</div><span id=s>y</span><li id=l>z</li>\
             <div id=styled>w</div><p id=o></p><script>\
             const g = (id) => getComputedStyle(document.getElementById(id)).display;\
             document.getElementById('o').textContent =\
               [g('d'), g('s'), g('l'), g('styled')].join('|');\
             </script></body>",
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(out.contains(">block|inline|list-item|flex<"), "{out}");
    }

    #[test]
    fn reflected_string_attributes_return_empty_not_undefined() {
        // HTML reflected string IDL attributes (lang/dir/title/slot) must return
        // the content attribute or "" — NEVER undefined. pixiv boots with
        // `document.documentElement.lang.toLowerCase()`; an undefined `lang`
        // made `.toLowerCase()` throw "cannot convert undefined to object"
        // (Boa's wording for a property read off undefined), killing its whole
        // bundle before `window.pixiv` was defined.
        let (out, outcome) = page(
            "<html lang=\"JA\"><head></head><body dir=rtl title=hi>\
             <div id=o></div><script>\
             const h = document.documentElement;\
             document.getElementById('o').textContent = [\
               h.lang.toLowerCase(), typeof h.dir, document.body.dir,\
               document.body.title, typeof document.body.slot,\
             ].join('|');\
             document.documentElement.lang = 'en';\
             document.getElementById('o').setAttribute('data-set', document.documentElement.getAttribute('lang'));\
             </script></body></html>",
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        // lang reflects (lowercased by the caller), absent attrs are "" (string).
        assert!(out.contains(">ja|string|rtl|hi|string<"), "{out}");
        // The setter reflects back to the content attribute.
        assert!(out.contains("data-set=\"en\""), "{out}");
    }

    #[test]
    fn meta_content_reflects_its_attribute_for_json_boot_config() {
        // HTMLMetaElement.content reflects the `content` attribute. pixiv stashes
        // its boot config as JSON in `<meta id=meta-global-data content='{…}'>`
        // and does `JSON.parse(meta.content)`; an expando-`undefined` content
        // made that a SyntaxError. A non-<meta> element still gets a plain
        // `.content` expando (lit's `.content=` property binding) and <template>
        // keeps its fragment.
        let (out, outcome) = page(
            "<head><meta id=cfg content='{\"token\":\"abc\",\"n\":1}'></head>\
             <body><div id=o></div><div id=lit></div><script>\
             const cfg = JSON.parse(document.getElementById('cfg').content);\
             document.getElementById('lit').content = 42;\
             document.getElementById('o').textContent =\
               cfg.token + '|' + cfg.n + '|' + document.getElementById('lit').content;\
             </script></body>",
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(out.contains(">abc|1|42<"), "{out}");
    }

    #[test]
    fn iframe_content_document_and_window_are_a_real_same_arena_document() {
        // `iframe.contentDocument || iframe.contentWindow.document` is the
        // universal frame-access idiom (analytics beacons, the Cloudflare
        // JS-detection script pixiv embeds). We hand back a real same-arena
        // FrameDocument: the idiom doesn't throw, `contentWindow.document` is
        // the SAME object, and a fresh frame has the `<html><head><body>`
        // skeleton. Content written into it renders inline (covered by
        // `iframe_scripted_document_write_renders_inline`); a non-frame element
        // has no such property (undefined).
        let (out, outcome) = page(
            r##"<body><div id=o></div><script>
            var f = document.createElement('iframe');
            document.body.appendChild(f);
            // The exact CF beacon shape: contentDocument first, else window.document.
            var d = f.contentDocument || f.contentWindow.document;
            var s = d.createElement('script');
            d.getElementsByTagName('head')[0].appendChild(s);
            var div = document.createElement('div');
            document.getElementById('o').textContent = [
              typeof d, d === f.contentWindow.document,
              d.getElementsByTagName('head').length, typeof div.contentDocument,
            ].join('|');
            </script></body>"##,
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        // a document facade, window.document is the SAME object, head exists,
        // and a plain <div> has no contentDocument.
        assert!(out.contains(">object|true|1|undefined<"), "{out}");
    }

    #[test]
    fn frame_context_restore_does_not_write_a_page_owned_frame_element() {
        // HTML exposes Window.frameElement as a readonly IDL getter. A
        // challenge may install an own non-writable property while probing the
        // environment; the browser's frame bookkeeping must not assign through
        // that page-owned descriptor when a timer task returns to its frame.
        let (out, outcome) = page(
            r#"<body><pre id=o></pre><script>
            'use strict';
            Object.defineProperty(window, 'frameElement', { value: null });
            setTimeout(function () {
                document.getElementById('o').textContent = 'timer survived';
            }, 0);
            </script></body>"#,
        );
        assert!(!outcome.panicked, "{outcome:?}");
        assert!(outcome.errors.is_empty(), "{outcome:?}");
        assert!(out.contains("timer survived"), "{out}");
    }

    #[test]
    fn iframe_scripted_document_write_renders_inline() {
        // The W3Schools tryit-editor pattern (and every code-playground result
        // pane): create an iframe, append it, then `contentWindow.document
        // .open()/write()/close()` a whole HTML document into it. The nested
        // body must flow into the page so the written content actually renders
        // (here, a table) rather than being inert.
        let (out, outcome) = page(
            r##"<body><div id=wrap></div><script>
            var ifr = document.createElement('iframe');
            document.getElementById('wrap').appendChild(ifr);
            var w = ifr.contentWindow;
            w.document.open();
            w.document.write('<!DOCTYPE html><html><head><style>td{border:1px solid}</style></head><body><h1>A Fancy Table</h1><table><tr><th>Company</th><th>Country</th></tr><tr><td>Alfreds</td><td>Germany</td></tr></table></body></html>');
            w.document.close();
            </script></body>"##,
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(
            out.contains("data-trust-frame"),
            "frame wrapper missing: {out}"
        );
        assert!(
            out.contains("A Fancy Table"),
            "frame heading missing: {out}"
        );
        assert!(
            out.contains("Alfreds") && out.contains("Germany"),
            "table cells missing: {out}"
        );
        // The frame's own <style> is dropped by the serializer (baked already),
        // and the content is a normal block (no <iframe> RAWTEXT in the output).
        assert!(
            !out.contains("<iframe"),
            "iframe element should not survive: {out}"
        );
    }

    #[test]
    fn iframe_srcdoc_renders_inline() {
        // A declarative `srcdoc` frame renders its content even when no script
        // touches it (`hydrateFrames` realizes it at DOMContentLoaded).
        let (out, outcome) =
            page(r##"<body><iframe srcdoc="<p>SANDBOXED CONTENT</p>"></iframe></body>"##);
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(
            out.contains("SANDBOXED CONTENT"),
            "srcdoc content missing: {out}"
        );
    }

    #[test]
    fn iframe_srcdoc_executes_in_frame_scope() {
        // HTML creates a nested browsing context for srcdoc, and scripts in
        // that context execute even when the parent is cross-origin. This
        // regression covers the reCAPTCHA shape: the child script sees its
        // own document and can register a listener/timer, while the parent
        // document remains the visible top-level document after execution.
        let (out, outcome) = page(
            r##"<body><div id=top>top</div><iframe srcdoc="<p id=child>before</p><script>var made=document.createElement('span'); made.textContent='|made'; document.getElementById('child').appendChild(made); document.getElementById('child').addEventListener('click',function(){this.textContent+='|clicked'}); var ch=new MessageChannel(); ch.port1.onmessage=function(e){document.getElementById('child').textContent+='|port'+e.data}; window.addEventListener('message',function(e){if(e.data && e.data.kind==='self') document.getElementById('child').textContent+='|self'; if(e.data && e.data.kind==='port' && e.ports[0]) e.ports[0].postMessage('ok'); if(e.data && e.data.kind==='deliver'){document.getElementById('child').textContent+='|down'; if(e.ports[0]) e.ports[0].postMessage('reply')}}); parent.postMessage({kind:'up'},'*'); window.postMessage({kind:'self'},'*'); window.postMessage({kind:'port'},'*',[ch.port2]); document.getElementById('child').dispatchEvent(new Event('click')); setTimeout(function(){document.getElementById('child').textContent+='|timer'},0)</script>"></iframe><script>window.addEventListener('message',function(e){if(e.data && e.data.kind==='up') document.getElementById('top').textContent+='|got-up'}); var f=document.querySelector('iframe'), up=new MessageChannel(), topEl=document.getElementById('top'); up.port1.onmessage=function(){topEl.textContent+='|reply'}; setTimeout(function(){f.contentWindow.postMessage({kind:'deliver'},'*',[up.port2])},0); void 0</script></body>"##,
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(
            out.contains("before|made|clicked")
                && out.contains("|self")
                && out.contains("|portok")
                && out.contains("|timer"),
            "frame script did not run: {out}"
        );
        assert!(
            out.contains("|got-up") && out.contains("|down") && out.contains("|reply"),
            "top document was not restored: {out}"
        );
    }

    #[test]
    fn iframe_window_uses_its_own_content_viewport() {
        // CSSOM View §4: innerWidth/innerHeight expose the viewport of the
        // relevant Window. A nested browsing context therefore uses the
        // iframe content box, while leaving the parent Window dimensions
        // unchanged. The percentage also covers a dynamically loaded frame
        // whose script runs before the next presentation/layout pass.
        let (out, outcome) = page(
            r##"<body><div style="width:200px"><iframe id=f style="width:80%;height:74px" srcdoc="<p id=child></p><script>document.getElementById('child').textContent='child:'+window.innerWidth+'x'+window.innerHeight+' media:'+matchMedia('(max-width:160px)').matches+'/'+matchMedia('(min-width:161px)').matches</script>"></iframe></div><p id=report></p><script>var f=document.getElementById('f');document.getElementById('report').textContent='parent:'+window.innerWidth+'x'+window.innerHeight+' proxy:'+f.contentWindow.innerWidth+'x'+f.contentWindow.innerHeight+' media:'+matchMedia('(min-width:600px)').matches+'/'+f.contentWindow.matchMedia('(max-width:160px)').matches</script></body>"##,
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(
            out.contains("child:160x74 media:true/false"),
            "child Window should use the iframe content viewport: {out}"
        );
        assert!(
            out.contains("parent:640x384 proxy:160x74 media:true/true"),
            "parent dimensions or child WindowProxy dimensions are wrong: {out}"
        );
    }

    #[test]
    fn hyperlink_target_navigates_named_iframe_not_top_page() {
        // HTML §7.4.4 chooses the existing child navigable whose name matches
        // target. The URL is resolved using the subject node's Document; only
        // a top-level destination is handed back to the frontend.
        let (out, outcome) = page(
            r#"<body><iframe id=frame name=content srcdoc="<p>old</p>"></iframe>
               <a id=inside href="data:text/html,new" target=content>inside</a>
               <a id=top href="../next" target=_top>top</a><script>
               var frame = document.getElementById('frame');
               var local = __trust.followAnchorDefault(document.getElementById('inside').__id);
               var top = __trust.followAnchorDefault(document.getElementById('top').__id);
               document.body.setAttribute('data-local', String(local));
               document.body.setAttribute('data-frame-src', frame.getAttribute('src'));
               document.body.setAttribute('data-srcdoc', String(frame.hasAttribute('srcdoc')));
               document.body.setAttribute('data-top', String(top));
               </script></body>"#,
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(out.contains("data-local=\"null\""), "{out}");
        assert!(
            out.contains("data-frame-src=\"data:text/html,new\""),
            "{out}"
        );
        assert!(out.contains("data-srcdoc=\"false\""), "{out}");
        assert!(
            out.contains("data-top=\"https://example.com/next\""),
            "{out}"
        );
    }

    #[test]
    fn trusted_click_uses_named_iframe_default_instead_of_top_navigation() {
        // Exercise the same trusted-click dispatcher as the resident actor,
        // directly. Keeping this as a task-local conformance test avoids making
        // its result depend on wall-clock actor scheduling while ~1,300 tests
        // run concurrently.
        let html = r#"<body><iframe name=content srcdoc='<p>old</p>'></iframe>
            <a href='about:blank?inside' target=content>inside</a>
            <script>document.querySelector('a').addEventListener('click', function () {})</script></body>"#;
        let env = PageEnv::bare("https://example.com/dir/page");
        let mut page = load_page(html, &env, None, None, None, None, None).unwrap();
        let node = page
            .ctx
            .eval(Source::from_bytes(b"document.querySelector('a').__id"))
            .unwrap()
            .as_number()
            .unwrap() as usize;

        let top_navigation = dispatch_click_in(&mut page, node);
        assert_eq!(top_navigation, None);
        assert!(page.outcome.errors.is_empty(), "{:?}", page.outcome.errors);
        let frame_state = page
            .ctx
            .eval(Source::from_bytes(
                b"var f=document.querySelector('iframe'); f.getAttribute('src')+'|'+f.hasAttribute('srcdoc')",
            ))
            .unwrap()
            .to_string(&mut page.ctx)
            .unwrap()
            .to_std_string_lossy();
        assert_eq!(frame_state, "about:blank?inside|false");
    }

    #[test]
    fn intersection_observer_reports_the_targets_real_box() {
        // A target IN the viewport at load (the probe sits at the very top, so
        // it's inside the 0..384px viewport) reports `isIntersecting:true` with
        // its REAL box for `boundingClientRect` and a full ratio (1) — honest
        // viewport intersection. (A below-the-fold target would report false; see
        // `a_below_fold_lazy_image_loads_when_scrolled_into_view`.) The probe is
        // `inline-block` with a fractional specified width, proving that the IO
        // record consumes the same unquantized CSS-pixel fragment geometry.
        let (out, outcome) = page(
            r##"<body><div id=probe style="display:inline-block;width:123.5px">HELLO</div><div id=out></div><script>
            var io = new IntersectionObserver(function (entries) {
                var e = entries[0];
                document.getElementById('out').textContent =
                    [e.isIntersecting, e.boundingClientRect.width, e.intersectionRatio].join(' ');
            });
            io.observe(document.getElementById('probe'));
            </script></body>"##,
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(
            out.contains("true 123.5 1"),
            "IO record should carry the real box + full ratio, got: {out}"
        );
    }

    #[test]
    fn intersection_observer_entries_expose_the_standard_interface() {
        // Intersection Observer §2.3 defines all seven readonly attributes on
        // the IntersectionObserverEntry interface and requires callback records
        // to be instances of that interface. This also covers the feature probe
        // used by standards-aware libraries before deciding to install a
        // synchronous geometry-polling polyfill.
        let (out, outcome) = page(
            r##"<body><div id=probe>probe</div><div id=out></div><script>
            var probe = document.getElementById('probe');
            var names = ['time', 'rootBounds', 'boundingClientRect',
                'intersectionRect', 'isIntersecting', 'intersectionRatio', 'target'];
            var manual = new IntersectionObserverEntry({
                time: 5, rootBounds: null,
                boundingClientRect: {x: 1, y: 2, width: 3, height: 4},
                intersectionRect: {x: 1, y: 2, width: 1, height: 2},
                isIntersecting: true, intersectionRatio: 0.5, target: probe
            });
            new IntersectionObserver(function (entries) {
                var e = entries[0];
                document.getElementById('out').textContent = [
                    'interface=' + names.every(function (name) {
                        return name in IntersectionObserverEntry.prototype;
                    }),
                    'callback=' + (e instanceof IntersectionObserverEntry),
                    'target=' + (e.target === probe),
                    'manual=' + (manual instanceof IntersectionObserverEntry),
                    'root=' + (manual.rootBounds === null),
                    'rect=' + manual.boundingClientRect.right + ',' +
                        manual.boundingClientRect.bottom
                ].join(' ');
            }).observe(probe);
            </script></body>"##,
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(
            out.contains("interface=true callback=true target=true manual=true root=true rect=4,6"),
            "IntersectionObserverEntry must expose and carry its Web IDL members: {out}"
        );
    }

    #[test]
    fn intersection_observer_sees_an_empty_generated_ratio_box() {
        // CSS Pseudo 4 §4.1 / CSS Content 3 §2: content:"" creates a
        // styleable box. CSS Box 4 §4: its vertical 56.25% padding resolves
        // against the 320px containing-block width, making the observed target
        // 180px tall. Media lazy-loaders gate source assignment on precisely
        // this positive IntersectionObserver geometry.
        let (out, outcome) = page(
            r##"<head><style>
            #thumb{width:320px}
            #thumb::before{content:"";display:block;width:100%;padding-top:56.25%}
            </style></head><body style="margin:0">
            <div id=thumb></div><div id=out></div><script>
            new IntersectionObserver(function (entries) {
                var e = entries[0];
                document.getElementById('out').textContent =
                    [e.isIntersecting, e.boundingClientRect.width,
                     e.boundingClientRect.height, e.intersectionRect.height].join(' ');
            }).observe(document.getElementById('thumb'));
            </script></body>"##,
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(
            out.contains("true 320 180 180"),
            "generated ratio box must supply real IO geometry: {out}"
        );
    }

    #[test]
    fn a_below_fold_target_with_a_box_is_not_intersecting_at_load() {
        // Honest viewport intersection for a target that HAS a laid-out box: a
        // boxed element far below the fold reports `isIntersecting:false`, ratio 0
        // at load (scroll is 0). A scroll-based lazy-loader then leaves it for when
        // the user scrolls to it — browser behaviour, and why an infinite scroller
        // no longer tries to reveal the whole document at load. The probe (a text
        // div, so it has a real box) sits below ~50 rows of real content (a
        // declared CSS height isn't reserved in flow, so the filler must be real
        // rows). The first observation ALWAYS fires (previousThresholdIndex = -1),
        // so the callback runs once with the false state.
        let filler = "filler line\n".repeat(50);
        let html = format!(
            r##"<body><pre>{filler}</pre>
            <div id=probe>probe</div><div id=out></div><script>
            var io = new IntersectionObserver(function (entries) {{
                var e = entries[0];
                document.getElementById('out').textContent =
                    'isx=' + e.isIntersecting + ' ratio=' + e.intersectionRatio;
            }});
            io.observe(document.getElementById('probe'));
            </script></body>"##
        );
        let (out, outcome) = page(&html);
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(
            out.contains("isx=false ratio=0"),
            "a below-fold BOXED target must report not-intersecting at load, got: {out}"
        );
    }

    #[test]
    fn an_empty_sentinel_gets_honest_geometry() {
        // The IntersectionObserver standard for infinite scroll observes an EMPTY
        // marker <div> (a "sentinel"). The layout now gives every element a real
        // ZERO-HEIGHT box at its flow position, so honest intersection works for
        // an empty element with NO guesswork: a sentinel near the TOP is
        // intersecting; the SAME empty sentinel below the fold is NOT (it's
        // honestly placed past the viewport, not reported always-visible).
        let (top, outcome) = page(
            r##"<body><h1>Top</h1><div id=probe></div><div id=out></div><script>
            new IntersectionObserver(function (e) {
                document.getElementById('out').textContent = 'top isx=' + e[0].isIntersecting;
            }).observe(document.getElementById('probe'));
            </script></body>"##,
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(
            top.contains("top isx=true"),
            "an empty sentinel at the top must intersect (it has a real box now): {top}"
        );
        let filler = "filler line\n".repeat(50);
        let html = format!(
            r##"<body><pre>{filler}</pre><div id=probe></div><div id=out></div><script>
            new IntersectionObserver(function (e) {{
                document.getElementById('out').textContent = 'below isx=' + e[0].isIntersecting;
            }}).observe(document.getElementById('probe'));
            </script></body>"##
        );
        let (below, outcome) = page(&html);
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(
            below.contains("below isx=false"),
            "an empty sentinel below the fold must be honestly NOT intersecting: {below}"
        );
    }

    #[test]
    fn a_shadow_rooted_abspos_sentinel_gets_honest_geometry() {
        // archive.org's `<infinite-scroller>` keeps its IntersectionObserver
        // sentinel as an EMPTY `position:absolute` <div> inside its SHADOW root,
        // positioned at the bottom of the growing content. Honest geometry must
        // reach it through BOTH the shadow boundary (the containing block gathers
        // its positioned descendants through the composed tree) AND the abspos
        // coordinate model (the sentinel's USED `top`, not its static in-flow DOM
        // position): a sentinel near the top of a relatively-positioned scroller
        // intersects; the same empty sentinel placed below the fold is honestly
        // NOT intersecting.
        let top = r##"<body><div id=host style="position:relative;height:32px"></div>
        <div id=out></div><script>
        var sr = document.getElementById('host').attachShadow({mode:'open'});
        sr.innerHTML = '<div id=s style="position:absolute;top:0"></div>';
        new IntersectionObserver(function (e) {
            document.getElementById('out').textContent = 'top isx=' + e[0].isIntersecting;
        }).observe(sr.querySelector('#s'));
        </script></body>"##;
        let (out, outcome) = page(top);
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(
            out.contains("top isx=true"),
            "a shadow-rooted abspos sentinel at the top must intersect: {out}"
        );

        let below = r##"<body><div id=host style="position:relative;height:1600px"></div>
        <div id=out></div><script>
        var sr = document.getElementById('host').attachShadow({mode:'open'});
        sr.innerHTML = '<div id=s style="position:absolute;top:1500px"></div>';
        new IntersectionObserver(function (e) {
            document.getElementById('out').textContent = 'below isx=' + e[0].isIntersecting;
        }).observe(sr.querySelector('#s'));
        </script></body>"##;
        let (out, outcome) = page(below);
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(
            out.contains("below isx=false"),
            "a shadow-rooted abspos sentinel below the fold must be honestly NOT intersecting: {out}"
        );
    }

    #[test]
    fn a_below_fold_lazy_image_loads_when_scrolled_into_view() {
        // The demand-driven half: the same below-fold lazy image stays blank at
        // load, then loads once the user scrolls it into view — a PageCmd::Scroll
        // updates scrollY, re-runs the intersection step, and the IO callback
        // (now isIntersecting) sets src. This is the live-engine path the old
        // "reveal everything at load" stub replaced; it's how infinite scroll and
        // scroll-based lazy loading both work.
        // Observe a text-bearing sentinel (so it has a real layout box) and load
        // the image when it scrolls into view — the standard sentinel-driven lazy
        // pattern. (A bare zero-size <img> may have no box, which a real lazy
        // image avoids by reserving space.)
        let filler = "filler line\n".repeat(50);
        let html = format!(
            r##"<body><pre>{filler}</pre>
            <img id=lazy data-lazy="/x.png"><div id=sentinel>load-zone</div><div id=out></div><script>
            var io = new IntersectionObserver(function (entries) {{
                entries.forEach(function (e) {{
                    if (e.isIntersecting) {{
                        var img = document.getElementById('lazy');
                        img.src = img.getAttribute('data-lazy');
                        io.unobserve(e.target);
                    }}
                }});
                document.getElementById('out').textContent =
                    'src=' + (document.getElementById('lazy').getAttribute('src') || 'NONE');
            }});
            io.observe(document.getElementById('sentinel'));
            </script></body>"##
        );
        let (handle, mut events) = live(&html);
        let first = match events.blocking_recv() {
            Some(PageEvt::Updated { html, outcome }) => {
                assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
                html
            }
            other => panic!("expected a live first render, got {other:?}"),
        };
        assert!(
            first.contains("src=NONE"),
            "the lazy image must NOT load at the top of the page, got: {first}"
        );
        // Scroll the image (below ~50 rows = 800px) into the 384px viewport.
        handle
            .cmds
            .blocking_send(PageCmd::Scroll { x: 0.0, y: 800.0 })
            .unwrap();
        let mut loaded = false;
        for _ in 0..8 {
            match events.blocking_recv() {
                Some(PageEvt::Updated { html, outcome }) => {
                    assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
                    if html.contains("src=/x.png") {
                        loaded = true;
                        break;
                    }
                }
                Some(PageEvt::Settled) => continue,
                other => panic!("unexpected event: {other:?}"),
            }
        }
        assert!(loaded, "the lazy image must load once scrolled into view");
    }

    #[test]
    fn a_window_scroll_listener_sees_the_threaded_position() {
        // Steam's infinite scroll listens on `window` and checks
        // `scrollY + innerHeight >= scrollHeight`. A PageCmd::Scroll fires the
        // viewport `scroll` event (reaching window listeners) with the real
        // scrollY, innerHeight, and documentElement.scrollHeight. A page with a
        // scroll listener and nothing else stays LIVE to receive the scroll.
        let filler = "filler line\n".repeat(50);
        let html = format!(
            r##"<body><pre>{filler}</pre><div id=out></div><script>
            window.addEventListener('scroll', function () {{
                document.getElementById('out').textContent =
                    'y=' + Math.round(window.scrollY) + ' ih=' + window.innerHeight +
                    ' atBottom=' + (window.scrollY + window.innerHeight >=
                                    document.documentElement.scrollHeight);
            }});
            </script></body>"##
        );
        let (handle, mut events) = live(&html);
        match events.blocking_recv() {
            Some(PageEvt::Updated { outcome, .. }) => {
                assert!(outcome.errors.is_empty(), "{:?}", outcome.errors)
            }
            other => panic!("a scroll-listener page must stay live, got {other:?}"),
        }
        handle
            .cmds
            .blocking_send(PageCmd::Scroll { x: 0.0, y: 320.0 })
            .unwrap();
        let mut saw = None;
        for _ in 0..8 {
            match events.blocking_recv() {
                Some(PageEvt::Updated { html, outcome }) => {
                    assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
                    if html.contains("y=320 ih=384") {
                        saw = Some(html);
                        break;
                    }
                }
                Some(PageEvt::Settled) => continue,
                other => panic!("unexpected event: {other:?}"),
            }
        }
        assert!(
            saw.is_some(),
            "the window scroll listener must see y=320 ih=384"
        );
    }

    #[test]
    fn a_bottom_sentinel_appends_a_batch_when_scrolled_to() {
        // The infinite-scroll mechanism end to end (via the actor, append in
        // place of a network fetch): a sentinel below the fold is NOT intersecting
        // at load (no batch), then scrolling to it fires the IO callback which
        // appends the next item. A mid-page scroll that reveals nothing new emits
        // `Settled` (edge-triggered: no threshold/isIntersecting change ⇒ no
        // entry ⇒ no mutation).
        let filler = "filler line\n".repeat(50);
        let html = format!(
            r##"<body><div id=list><div class=item>item-1</div></div>
            <pre>{filler}</pre><div id=sentinel>.</div><script>
            var n = 1;
            var io = new IntersectionObserver(function (entries) {{
                entries.forEach(function (e) {{
                    if (e.isIntersecting) {{
                        n++;
                        var d = document.createElement('div');
                        d.className = 'item';
                        d.textContent = 'item-' + n;
                        document.getElementById('list').appendChild(d);
                    }}
                }});
            }});
            io.observe(document.getElementById('sentinel'));
            </script></body>"##
        );
        let (handle, mut events) = live(&html);
        let first = match events.blocking_recv() {
            Some(PageEvt::Updated { html, outcome }) => {
                assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
                html
            }
            other => panic!("expected a live first render, got {other:?}"),
        };
        assert!(first.contains("item-1"), "{first}");
        assert!(
            !first.contains("item-2"),
            "no batch must load at the top, got: {first}"
        );
        // Scroll the sentinel (below ~50 rows = 800px) into view.
        handle
            .cmds
            .blocking_send(PageCmd::Scroll { x: 0.0, y: 800.0 })
            .unwrap();
        let mut appended = false;
        for _ in 0..8 {
            match events.blocking_recv() {
                Some(PageEvt::Updated { html, outcome }) => {
                    assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
                    if html.contains("item-2") {
                        appended = true;
                        break;
                    }
                }
                Some(PageEvt::Settled) => continue,
                other => panic!("unexpected event: {other:?}"),
            }
        }
        assert!(
            appended,
            "scrolling to the bottom sentinel must append the next batch"
        );
    }

    #[test]
    fn a_bottom_sentinel_re_arms_for_the_next_batch() {
        // The regression: after a batch loads and pushes the sentinel out of the
        // viewport, a SECOND scroll to the new bottom must load the next batch.
        // This only works if intersections are re-evaluated AFTER the batch
        // mutates the DOM (the sentinel goes isIntersecting:true→false, re-arming
        // the false→true trigger). Each batch (30 rows) here is taller than the
        // 24-row viewport, so it clears the sentinel — the well-built infinite
        // scroller. (Uses a synchronous append; the real fetch path is the live
        // smoke. `bare` has no network.)
        let filler = "filler line\n".repeat(50);
        let html = format!(
            r##"<body><div id=list></div><pre>{filler}</pre><div id=sentinel>.</div><script>
            var n = 0;
            new IntersectionObserver(function (entries) {{
                entries.forEach(function (e) {{
                    if (!e.isIntersecting) return;
                    var list = document.getElementById('list');
                    for (var i = 0; i < 30; i++) {{
                        n++;
                        var d = document.createElement('div');
                        d.textContent = 'item-' + n;
                        list.appendChild(d);
                    }}
                }});
            }}).observe(document.getElementById('sentinel'));
            </script></body>"##
        );
        let (handle, mut events) = live(&html);
        // First render: sentinel below the fold ⇒ no batch.
        match events.blocking_recv() {
            Some(PageEvt::Updated { html, .. }) => {
                assert!(!html.contains("item-1"), "no batch at load: {html}")
            }
            other => panic!("expected a live first render, got {other:?}"),
        }
        let recv_until = |events: &mut tokio::sync::mpsc::Receiver<PageEvt>, needle: &str| {
            for _ in 0..8 {
                match events.blocking_recv() {
                    Some(PageEvt::Updated { html, outcome }) => {
                        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
                        if html.contains(needle) {
                            return true;
                        }
                    }
                    Some(PageEvt::Settled) => continue,
                    other => panic!("unexpected event: {other:?}"),
                }
            }
            false
        };
        // Scroll #1: sentinel enters view ⇒ batch 1 (items 1..30) appends and
        // pushes the sentinel out of the viewport.
        handle
            .cmds
            .blocking_send(PageCmd::Scroll { x: 0.0, y: 800.0 })
            .unwrap();
        assert!(recv_until(&mut events, "item-1"), "batch 1 must load");
        // Scroll #2 to the new bottom: the re-armed sentinel re-enters ⇒ batch 2
        // (items 31..60). This is what dead-ended before the fetch-done /
        // post-mutation re-evaluation fix.
        handle
            .cmds
            .blocking_send(PageCmd::Scroll { x: 0.0, y: 1300.0 })
            .unwrap();
        assert!(
            recv_until(&mut events, "item-31"),
            "scrolling to the new bottom must load the SECOND batch (re-arm)"
        );
    }

    // --- MutationObserver -------------------------------------------------

    #[test]
    fn mutation_observer_reports_childlist_add_and_remove() {
        // Two synchronous mutations COALESCE into one microtask delivery with
        // two records — the spec's compound-microtask batching.
        let (out, outcome) = page(
            r##"<body><div id="t"></div><pre id="out"></pre><script>
            var out = document.getElementById('out'), t = document.getElementById('t');
            var log = [];
            new MutationObserver(function (recs) {
                for (var i = 0; i < recs.length; i++) {
                    var r = recs[i];
                    log.push(r.type + ':+' + r.addedNodes.length + '-' + r.removedNodes.length);
                }
                out.textContent = log.join(' ');
            }).observe(t, { childList: true });
            var span = document.createElement('span');
            t.appendChild(span);
            t.removeChild(span);
            </script></body>"##,
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(out.contains("childList:+1-0 childList:+0-1"), "{out}");
    }

    #[test]
    fn mutation_observer_ignores_unmatched_mutation_without_delivery() {
        // A registered observer is not enough to queue the compound
        // microtask: the DOM algorithm queues it only after an interested
        // registration receives a record. This also covers the fast path that
        // avoids Promise allocation for unrelated mutation categories.
        let (out, outcome) = page(
            r#"<body><div id=t></div><pre id=o></pre><script>
                const t = document.getElementById('t');
                let fired = 0;
                new MutationObserver(() => fired++).observe(t, { attributes: true });
                t.appendChild(document.createElement('span'));
                document.getElementById('o').textContent = 'fired=' + fired;
            </script></body>"#,
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(out.contains("fired=0"), "{out}");
    }

    #[test]
    fn mutation_observer_reports_attributes_with_old_value_and_filter() {
        let (out, outcome) = page(
            r##"<body><div id="t" class="a" data-x="1"></div><pre id="out"></pre><script>
            var out = document.getElementById('out'), t = document.getElementById('t');
            var log = [];
            new MutationObserver(function (recs) {
                for (var r of recs) log.push(r.attributeName + '=' + r.oldValue);
                out.textContent = log.join(' ');
            }).observe(t, { attributes: true, attributeOldValue: true, attributeFilter: ['class'] });
            t.setAttribute('class', 'b');   // observed (filter includes class)
            t.setAttribute('data-x', '2');  // filtered out
            </script></body>"##,
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        // The observer's report is exactly the one filtered-in attribute: the
        // <pre> holds "class=a" (old value of class) and nothing about data-x.
        // (The div itself still carries data-x="2" in the serialized markup —
        // assert on the <pre> content, not the whole document.)
        assert!(
            out.contains(">class=a</pre>"),
            "filtered report should be only class=a: {out}"
        );
    }

    #[test]
    fn mutation_observer_reports_character_data_with_old_value() {
        let (out, outcome) = page(
            r##"<body><p id="t">hello</p><pre id="out"></pre><script>
            var out = document.getElementById('out');
            var t = document.getElementById('t').firstChild;  // the text node
            new MutationObserver(function (recs) {
                out.textContent = recs[0].type + ':' + recs[0].oldValue;
            }).observe(t, { characterData: true, characterDataOldValue: true });
            t.data = 'world';
            </script></body>"##,
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(out.contains("characterData:hello"), "{out}");
    }

    #[test]
    fn mutation_observer_subtree_matches_deep_but_non_subtree_does_not() {
        // `subtree:true` sees a mutation on a deep descendant (via the
        // __dom_contains ancestor syscall); a plain registration on the same
        // root sees only its direct children.
        let (out, outcome) = page(
            r##"<body><div id="root"><div id="mid"><span id="leaf"></span></div></div>
            <pre id="a"></pre><pre id="b"></pre><script>
            var root = document.getElementById('root'), leaf = document.getElementById('leaf');
            var na = 0, nb = 0;
            new MutationObserver(function (r) { na += r.length; document.getElementById('a').textContent = 'a=' + na; })
                .observe(root, { childList: true, subtree: true });
            new MutationObserver(function (r) { nb += r.length; document.getElementById('b').textContent = 'b=' + nb; })
                .observe(root, { childList: true });   // no subtree
            leaf.appendChild(document.createElement('b'));  // deep descendant mutation
            </script></body>"##,
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(
            out.contains("a=1"),
            "subtree observer must see the deep mutation: {out}"
        );
        assert!(
            !out.contains("b=1"),
            "non-subtree observer must NOT see a descendant mutation: {out}"
        );
    }

    #[test]
    fn mutation_observer_disconnect_and_take_records() {
        let (out, outcome) = page(
            r##"<body><div id="t"></div><pre id="out"></pre><script>
            var out = document.getElementById('out'), t = document.getElementById('t');
            var fired = 0;
            var mo = new MutationObserver(function () { fired++; });
            mo.observe(t, { childList: true });
            t.appendChild(document.createElement('a'));   // queues a record
            var pending = mo.takeRecords().length;        // drains it synchronously
            mo.disconnect();
            t.appendChild(document.createElement('b'));   // ignored after disconnect
            out.textContent = 'pending=' + pending + ' fired=' + fired;
            </script></body>"##,
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        // takeRecords drained the queued record, so the async callback saw
        // nothing; the post-disconnect mutation never queued.
        assert!(out.contains("pending=1 fired=0"), "{out}");
    }

    #[test]
    fn mutation_observer_delivers_as_microtask_before_timers() {
        // Ordering proof: synchronous code first; microtasks (a promise
        // reaction queued before the mutation, then the MO delivery) run before
        // the macrotask timer. This is the async-XHR-vs-promise ordering trap's
        // cousin — getting it wrong reorders observer callbacks against fetch.
        let (out, outcome) = page(
            r##"<body><div id="t"></div><pre id="out"></pre><script>
            var seq = [], t = document.getElementById('t');
            function finish() { document.getElementById('out').textContent = seq.join(','); }
            new MutationObserver(function () { seq.push('mo'); finish(); }).observe(t, { childList: true });
            Promise.resolve().then(function () { seq.push('promise'); finish(); });
            setTimeout(function () { seq.push('timeout'); finish(); }, 0);
            t.appendChild(document.createElement('x'));   // queues the MO microtask
            seq.push('sync');
            </script></body>"##,
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(out.contains("sync,promise,mo,timeout"), "ordering: {out}");
    }

    #[test]
    fn mutation_observer_callback_mutation_requeues_then_settles() {
        // A callback that itself mutates the observed tree re-queues a delivery
        // (legal, spec) and the chain terminates once it stops mutating —
        // proving the reset-on-quiescence loop guard doesn't false-trip.
        let (out, outcome) = page(
            r##"<body><div id="t"></div><pre id="out"></pre><script>
            var t = document.getElementById('t'), turns = 0;
            new MutationObserver(function () {
                turns++;
                if (turns < 3) t.appendChild(document.createElement('i'));
                document.getElementById('out').textContent = 'turns=' + turns;
            }).observe(t, { childList: true });
            t.appendChild(document.createElement('i'));   // turn 1
            </script></body>"##,
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(out.contains("turns=3"), "{out}");
    }

    #[test]
    fn mutation_observer_runaway_loop_is_capped_and_degrades() {
        // An observer that mutates the observed node on EVERY delivery feeds
        // itself forever; the microtask-checkpoint lid trips and disables
        // delivery for the page (degrade, not hang).
        let (_out, outcome) = page(
            r##"<body><div id="t"></div><script>
            var t = document.getElementById('t');
            new MutationObserver(function () { t.setAttribute('data-n', String(Math.random())); })
                .observe(t, { attributes: true });
            t.setAttribute('data-n', '0');   // kick off the self-feeding loop
            </script></body>"##,
        );
        assert!(
            outcome
                .errors
                .iter()
                .any(|e| e.contains("MutationObserver") && e.contains("disabled")),
            "runaway observer loop should trip the lid: {:?}",
            outcome.errors
        );
    }

    #[test]
    fn live_click_injection_is_seen_by_a_subtree_observer() {
        // The dynamic-enhancement pattern (Stimulus / Alpine / htmx): a
        // body-rooted subtree observer enhances nodes added by a LATER
        // interaction. The click injects a <span data-enhance>; the observer
        // rewrites its text. Without a live MutationObserver this never fires.
        let (handle, mut events) = live(
            r##"<body><div id="host"></div><button id="go">go</button><script>
            new MutationObserver(function (recs) {
                for (var r of recs) for (var i = 0; i < r.addedNodes.length; i++) {
                    var n = r.addedNodes[i];
                    if (n.nodeType === 1 && n.hasAttribute && n.hasAttribute('data-enhance')) n.textContent = 'ENHANCED';
                }
            }).observe(document.body, { childList: true, subtree: true });
            document.getElementById('go').addEventListener('click', function () {
                var s = document.createElement('span');
                s.setAttribute('data-enhance', '');
                document.getElementById('host').appendChild(s);
            });
            </script></body>"##,
        );
        let mut first = String::new();
        for _ in 0..4 {
            match events.blocking_recv() {
                Some(PageEvt::Updated { html, .. }) | Some(PageEvt::Static { html, .. }) => {
                    first = html;
                    if first.contains(">go<") {
                        break;
                    }
                }
                other => panic!("expected a render, got {other:?}"),
            }
        }
        let go = first
            .find("id=\"go\"")
            // Native buttons retain their authored CSS-box position. Their
            // actor marker is metadata on the button itself, after its id,
            // rather than an invented parent anchor before it.
            .and_then(|at| first[at..].find("x-trust-js:").map(|i| at + i))
            .map(|i| {
                first[i + "x-trust-js:".len()..]
                    .split(':')
                    .next()
                    .unwrap()
                    .parse::<usize>()
                    .unwrap()
            })
            .expect("a clickable marker for the button");
        handle.cmds.blocking_send(PageCmd::Click(go)).unwrap();
        let Some(PageEvt::Updated { html, outcome }) = events.blocking_recv() else {
            panic!("expected Updated after the click");
        };
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(
            html.contains("ENHANCED"),
            "the subtree observer must enhance the click-injected node: {html}"
        );
    }

    #[test]
    fn spa_router_platform_surface_works() {
        // The router-slot recipe (archive.org's router): an <a> as URL
        // parser honoring <base href>, history.state round-tripping
        // with location updates, and `new`-construction of a defined
        // custom element (routers mount pages that way).
        let (out, outcome) = page(
            r##"<html><head><base href="/"></head><body><div id=out></div><script>
            var a = document.createElement('a');
            a.href = '.';
            var parts = [a.pathname, a.protocol];
            history.replaceState({n: 7}, '', '/sub/page?q=1');
            parts.push(history.state.n, location.pathname, location.search);
            class RoutePage extends HTMLElement {}
            customElements.define('route-page', RoutePage);
            var el = new RoutePage();
            parts.push(el.localName, el instanceof RoutePage);
            document.getElementById('out').textContent = parts.join(' ');
            </script></body></html>"##,
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(
            out.contains("/ https: 7 /sub/page ?q=1 route-page true"),
            "router surface broken: {out}"
        );
    }

    #[test]
    fn history_state_updates_follow_same_document_url_rules() {
        // WHATWG HTML §7.2.5 shared history push/replace state steps:
        // state is structured-cloned, every push/replace is retained in order,
        // no popstate/hashchange fires, and forbidden URL rewrites throw
        // SecurityError without changing the active URL.
        let (out, outcome) = page(
            r##"<body><pre id=out></pre><script>
            var pop = 0, hash = 0;
            addEventListener('popstate', function () { pop++; });
            addEventListener('hashchange', function () { hash++; });
            var input = { n: 1 };
            history.pushState(input, '', '/watch?v=first');
            input.n = 99;
            var detached = history.state.n;
            history.replaceState({ n: 2 }, '', '?v=second');
            var updates = JSON.parse(__trust.takeHistoryUpdates());
            var denied = '';
            try { history.pushState(null, '', 'https://other.example/nope'); }
            catch (e) { denied = e.name; }
            document.getElementById('out').textContent = JSON.stringify({
                detached: detached, state: history.state.n,
                length: history.length, href: location.href,
                updates: updates, pop: pop, hash: hash, denied: denied
            });
            </script></body>"##,
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(out.contains("\"detached\":1"), "{out}");
        assert!(out.contains("\"state\":2"), "{out}");
        assert!(out.contains("\"length\":2"), "{out}");
        assert!(
            out.contains("\"href\":\"https://example.com/watch?v=second\""),
            "{out}"
        );
        assert!(out.contains("\"replace\":false"), "{out}");
        assert!(out.contains("\"replace\":true"), "{out}");
        assert!(out.contains("\"pop\":0"), "{out}");
        assert!(out.contains("\"hash\":0"), "{out}");
        assert!(out.contains("\"denied\":\"SecurityError\""), "{out}");
    }

    #[test]
    fn a_page_without_scripts_passes_through_untouched() {
        let html = "<body><noscript>no js here</noscript><p>hi</p></body>";
        let (out, outcome) = page(html);
        assert_eq!(out, html);
        assert!(outcome.errors.is_empty());
    }

    #[test]
    fn scripts_build_the_page_with_create_element() {
        let (out, outcome) = page(
            "<body><div id=root></div><script>\
             var d = document.getElementById('root');\
             var h = document.createElement('h1');\
             h.appendChild(document.createTextNode('Built by JS'));\
             d.appendChild(h);\
             </script><noscript>enable javascript!</noscript></body>",
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(out.contains("<h1>Built by JS</h1>"), "{out}");
        // JS ran: noscript content and the script itself are gone.
        assert!(!out.contains("enable javascript"), "{out}");
        assert!(!out.contains("createElement"), "{out}");
    }

    #[test]
    fn get_computed_style_reads_the_cascade_not_just_inline() {
        // getComputedStyle now resolves sheet rules, inheritance, and UA
        // defaults via the cascade — it used to see only the inline style
        // attribute, returning "" for everything a stylesheet set.
        let (out, outcome) = page(
            "<head><style>.card{font-weight:bold}</style></head>\
             <body><div class=card><span id=s>x</span></div>\
             <b id=b>y</b>\
             <script>\
               var s = document.getElementById('s');\
               var b = document.getElementById('b');\
               document.body.setAttribute('data-inherit', getComputedStyle(s).fontWeight);\
               document.body.setAttribute('data-ua', getComputedStyle(b).getPropertyValue('font-weight'));\
             </script></body>",
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(
            out.contains("data-inherit=\"bold\""),
            "sheet font-weight inherits through getComputedStyle: {out}"
        );
        assert!(
            out.contains("data-ua=\"bold\""),
            "UA <b> default visible through getComputedStyle: {out}"
        );
    }

    #[test]
    fn get_computed_style_materializes_positioned_box_initial_values() {
        // CSS Cascade 5 §4 gives every property a specified/computed value;
        // CSSOM §9 exposes the resolved value, not an internal "unset"
        // sentinel. A fitting library distinguishes the initial `auto` insets
        // from authored coordinates before assigning fixed positioning.
        let (out, outcome) = page(
            "<body><div id=d></div><script>\
               var d = document.getElementById('d');\
               var s = getComputedStyle(d);\
               var vertically = s.top !== 'auto' ? 'top' : s.bottom !== 'auto' ? 'bottom' : '';\
               var horizontally = s.left !== 'auto' ? 'left' : s.right !== 'auto' ? 'right' : '';\
               d.setAttribute('data-initials', [s.position,s.top,s.right,s.bottom,s.left,s.maxWidth,s.maxHeight,s.boxSizing,s.marginTop,s.direction,s.opacity].join('|'));\
               if (!vertically) { d.style.position='fixed'; d.style.top='0px'; }\
               if (!horizontally) { d.style.position='fixed'; d.style.left='0px'; }\
             </script></body>",
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(
            out.contains(
                "data-initials=\"static|auto|auto|auto|auto|none|none|content-box|0px|ltr|1\""
            ),
            "CSSOM exposed the specified initial values: {out}"
        );
        assert!(
            out.contains("style=\"position: fixed; top: 0px; left: 0px;"),
            "an ordinary fitting algorithm can now establish a fixed box: {out}"
        );
    }

    #[test]
    fn media_queries_apply_at_the_viewport_width() {
        // bare() viewport = 80 cols × 8px = 640px wide. A max-width:768px
        // block matches (hides); a min-width:1000px block doesn't (kept).
        let (out, outcome) = page(
            "<head><style>\
               @media (max-width: 768px) { .mobile-hide { display: none } }\
               @media (min-width: 1000px) { .desktop-hide { display: none } }\
             </style></head>\
             <body>\
               <p class=mobile-hide>HIDE_AT_NARROW</p>\
               <p class=desktop-hide>KEEP_AT_NARROW</p>\
               <script>document.title = 'x';</script>\
             </body>",
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(
            !out.contains("HIDE_AT_NARROW"),
            "max-width:768px matched at 640px → hidden: {out}"
        );
        assert!(
            out.contains("KEEP_AT_NARROW"),
            "min-width:1000px not matched at 640px → kept: {out}"
        );
    }

    /// `window.matchMedia(q).matches` evaluates the query against the real
    /// viewport through the same evaluator as CSS `@media` — it was a stub that
    /// always returned `false`, so `(min-width: …)` tests read false at any
    /// width and responsive apps (Mastodon's `layoutFromWindow`) fell to their
    /// narrowest/mobile layout. bare() viewport = 80 cols × 8px = 640px.
    #[test]
    fn match_media_evaluates_against_the_viewport() {
        let (out, outcome) = page(
            "<body><div id=o></div><script>\
             var o = document.getElementById('o');\
             o.setAttribute('data-min500', String(matchMedia('(min-width: 500px)').matches));\
             o.setAttribute('data-min1000', String(matchMedia('(min-width: 1000px)').matches));\
             o.setAttribute('data-max768', String(matchMedia('(max-width: 768px)').matches));\
             o.setAttribute('data-land', String(matchMedia('(orientation: landscape)').matches));\
             o.setAttribute('data-and', String(matchMedia('screen and (min-width: 600px)').matches));\
             o.setAttribute('data-scheme', String(matchMedia('(prefers-color-scheme: dark)').matches));\
             o.setAttribute('data-unknown', String(matchMedia('(unknown-feature: foo)').matches));\
             </script></body>",
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        // 640px: >=500 true, >=1000 false, <=768 true, landscape (640x384) true.
        assert!(out.contains("data-min500=\"true\""), "{out}");
        assert!(out.contains("data-min1000=\"false\""), "{out}");
        assert!(out.contains("data-max768=\"true\""), "{out}");
        assert!(out.contains("data-land=\"true\""), "{out}");
        assert!(out.contains("data-and=\"true\""), "{out}");
        // The environment features answer (dark is the terminal aesthetic)…
        assert!(out.contains("data-scheme=\"true\""), "{out}");
        // …while unrecognized features stay false (the conservative default).
        assert!(out.contains("data-unknown=\"false\""), "{out}");
    }

    #[test]
    fn image_current_src_uses_srcset_sizes_picture_and_device_density() {
        let mut env = PageEnv::bare("https://example.com/gallery/page");
        env.viewport = (600, 400);
        env.cell_px = (1, 1);
        env.device_pixel_ratio = 2.0;
        let (out, outcome) = transform(
            r#"<body><picture>
              <source media="(max-width: 700px)" type="image/webp"
                srcset="small.webp 600w, medium.webp 1200w, giant.webp 3840w"
                sizes="50vw">
              <img id=hero src="giant-fallback.webp">
            </picture><script>
              var img = document.getElementById('hero');
              img.setAttribute('data-current', img.currentSrc);
              img.setAttribute('data-dpr', String(devicePixelRatio));
            </script></body>"#,
            &env,
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(
            out.contains("data-current=\"https://example.com/gallery/small.webp\""),
            "{out}"
        );
        assert!(out.contains("data-dpr=\"2\""), "{out}");
        assert!(!out.contains("data-current=\"https://example.com/gallery/giant-fallback.webp\""));
    }

