    #[test]
    fn select_options_surface_drives_react_style_option_mounting() {
        // React's <select> commit (postMountWrapper/updateOptions) reads
        // `select.options`, iterates `.length`, and reads/writes each option's
        // `.value`/`.selected`/`.defaultSelected`. A missing
        // `HTMLSelectElement.options` made `select.options` undefined, so
        // `undefined.length` threw a ToObject TypeError that aborted React's
        // whole render — pixiv's login page mounts a language <select>, so the
        // crash left the form a blank shell. Exercise the same surface plus the
        // controlled-select `value` setter, and confirm the selection lands on
        // the `selected` attribute the layout reads.
        let (out, outcome) = page(
            "<body><select id=s>\
               <option value=en>English</option>\
               <option value=ja>\u{65e5}\u{672c}\u{8a9e}</option>\
               <option>plain</option>\
             </select><pre id=o></pre><script>\
             var s = document.getElementById('s');\
             var opts = s.options, n = opts.length, want = 'ja';\
             for (var i = 0; i < n; i++) {\
               var hit = opts[i].value === want;\
               if (opts[i].selected !== hit) opts[i].selected = hit;\
               if (hit) opts[i].defaultSelected = true;\
             }\
             var r = 'len=' + n + ' val=' + s.value + ' idx=' + s.selectedIndex\
               + ' sel=' + s.selectedOptions.length + ' third=' + opts[2].value;\
             s.value = 'en';\
             r += ' after=' + s.selectedIndex + '/' + s.value;\
             document.getElementById('o').textContent = r;\
             </script></body>",
        );
        assert!(!outcome.panicked, "{outcome:?}");
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        // .options is iterable+indexable; .value/.selectedIndex/.selectedOptions
        // read the selection; a valueless <option> falls back to its text; the
        // controlled `value=` setter re-points the selection.
        assert!(
            out.contains("len=3 val=ja idx=1 sel=1 third=plain after=0/en"),
            "{out}"
        );
        // The final selection ("en") carries the `selected` attribute the layout
        // and form-submit path read.
        assert!(out.contains("value=\"en\" selected"), "{out}");
    }

    #[test]
    fn type_specific_idl_accessors_are_writable_expandos_off_their_interface() {
        // Type-specific IDL accessors (HTMLSelectElement.options,
        // HTMLMediaElement.error, …) live ONLY on their owning interface's
        // prototype now, exactly as a browser does. On any OTHER element the
        // name is therefore a plain writable expando — `el.options = x` no longer
        // throws "cannot set non-writable property" in strict mode (the trap #3
        // that aborted YouTube's Polymer, which declares an `options` property on
        // its `ytd-*` custom elements and assigns it during data-binding). On the
        // OWNING element the read-only accessor is genuinely getter-only, so
        // assigning it in strict mode throws a TypeError — what a real browser
        // does (her call 2026-06-24: spec-compliant over the old silent no-op).
        let (out, outcome) = page(
            "<body><div id=d></div><pre id=o></pre>\
             <script>\
             'use strict';\
             var r;\
             try {\
             class YtThing extends HTMLElement {\
               setup(){ this.options = {sort:'rel'}; this.error = null; }\
             }\
             customElements.define('yt-thing', YtThing);\
             var t = document.createElement('yt-thing');\
             t.setup();\
             var d = document.getElementById('d');\
             d.options = [1,2,3];\
             var s = document.createElement('select');\
             s.innerHTML = '<option value=a></option><option value=b></option>';\
             var before = s.options.length;\
             var threw = false;\
             try { s.options = 'nope'; } catch (e) { threw = true; }\
             r = 'opt=' + t.options.sort + ' err=' + (t.error === null)\
               + ' exp=' + d.options.join(',')\
               + ' selRO=' + (threw && before === 2 && s.options.length === 2);\
             } catch (e) { r = 'THREW: ' + e; }\
             document.getElementById('o').textContent = r;\
             </script></body>",
        );
        assert!(!outcome.panicked, "{outcome:?}");
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        // Off-type writes are writable expandos; the owning-type read-only
        // write threw (and left the live `options` collection intact).
        assert!(
            out.contains("opt=rel err=true exp=1,2,3 selRO=true"),
            "{out}"
        );
    }

    #[test]
    fn dom_interfaces_carry_only_their_own_idl_attributes() {
        // The standards-compliance payoff of per-interface prototypes: a
        // type-specific IDL name exists ONLY on its owning interface, so the
        // `prop in element` feature test (polymer_resin, jQuery, React all use
        // it) answers correctly — `"options" in div === false`, etc. Also checks
        // the interface constructors are globals and `instanceof` is honest.
        let (out, outcome) = page(
            "<body><pre id=o></pre><script>\
             var r;\
             try {\
             var div = document.createElement('div');\
             var sel = document.createElement('select');\
             var vid = document.createElement('video');\
             var a = document.createElement('a');\
             var leaks = ['options','selectedOptions','error','duration','videoWidth',\
               'checked','selected','multiple','value','type','name','href','src',\
               'pathname','content','contentDocument','sheet','getContext'];\
             var anyLeak = leaks.filter(function (k) { return k in div; });\
             r = 'leaks=' + anyLeak.join(',')\
               + ' selOpts=' + ('options' in sel) + ' selVal=' + (sel.value === '')\
               + ' vidErr=' + ('error' in vid) + ' aHref=' + ('href' in a)\
               + ' aPath=' + ('pathname' in a) + ' divPath=' + ('pathname' in div)\
               + ' iSel=' + (sel instanceof HTMLSelectElement)\
               + ' iVid=' + (vid instanceof HTMLVideoElement)\
               + ' iVidMedia=' + (vid instanceof HTMLMediaElement)\
               + ' iDivHtml=' + (div instanceof HTMLElement)\
               + ' iDivEl=' + (div instanceof Element)\
               + ' iDivSel=' + (div instanceof HTMLSelectElement)\
               + ' iDivDiv=' + (div instanceof HTMLDivElement)\
               + ' ctor=' + (typeof HTMLAnchorElement === 'function');\
             } catch (e) { r = 'THREW: ' + (e && e.stack || e); }\
             document.getElementById('o').textContent = r;\
             </script></body>",
        );
        assert!(!outcome.panicked, "{outcome:?}");
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        // No type-specific name leaks onto <div>; each is present on its owner;
        // instanceof is honest both ways (div IS HTMLElement/HTMLDivElement, is
        // NOT HTMLSelectElement).
        assert!(out.contains("leaks= "), "{out}"); // empty leak list
        assert!(
            out.contains(
                "selOpts=true selVal=true vidErr=true aHref=true aPath=true \
                 divPath=false iSel=true iVid=true iVidMedia=true iDivHtml=true \
                 iDivEl=true iDivSel=false iDivDiv=true ctor=true"
            ),
            "{out}"
        );
    }

    #[test]
    fn data_is_a_characterdata_property_not_a_node_property() {
        // `data` is a CharacterData-only IDL attribute (Text/Comment) per the DOM
        // spec — it must NOT exist on Element. When it leaked onto Node (and thus
        // every element), `"data" in someDiv` was wrongly true, which fools the
        // `prop in element` feature test libraries use to tell a known DOM
        // property from an expando. YouTube's polymer_resin does exactly this on a
        // reference element to decide whether a `.data` PROPERTY binding is a sink
        // to sanitize; the leak made it replace every ytd-* renderer's `.data`
        // object with its innocuous sentinel, so the search results never
        // rendered. Element must have no `data`; Text/Comment keep theirs.
        let (out, outcome) = page(
            "<body><pre id=o></pre><script>\
             var div=document.createElement('div');\
             var t=document.createTextNode('hello');\
             var c=document.createComment('cmt');\
             var r='dataInDiv='+('data' in div)\
               +' divData='+(div.data===undefined)\
               +' dataInText='+('data' in t)+' textData='+t.data\
               +' dataInComment='+('data' in c)+' commentData='+c.data;\
             div.data={kind:'rel'};\
             r+=' expando='+div.data.kind;\
             document.getElementById('o').textContent=r;\
             </script></body>",
        );
        assert!(!outcome.panicked, "{outcome:?}");
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        // Element: no `data` (so `in` is false and a plain read is undefined), but
        // it stays a normal writable expando. Text/Comment: `data` present + live.
        assert!(
            out.contains(
                "dataInDiv=false divData=true dataInText=true textData=hello \
                 dataInComment=true commentData=cmt expando=rel"
            ),
            "{out}"
        );
    }

    #[test]
    fn an_injected_inline_script_executes() {
        // The universal SDK-loader idiom: page JS builds a <script> and appends
        // it to the document; a real browser runs it. We never did, so a
        // runtime-injected dependency silently never loaded (pixiv's login
        // injects reCAPTCHA this way then polls for it forever). An inline
        // injected script's text now evaluates, mutating the live DOM.
        let (out, outcome) = page(
            "<body><pre id=o>before</pre><script>\
             var s = document.createElement('script');\
             s.textContent = \"document.getElementById('o').textContent = 'injected-ran';\";\
             document.body.appendChild(s);\
             </script></body>",
        );
        assert!(!outcome.panicked, "{outcome:?}");
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(out.contains("injected-ran"), "{out}");
        // Re-appending the same script must NOT re-run it (HTML "already
        // started" flag), so the text stays as the first run left it.
        let (out2, _) = page(
            "<body><pre id=o>x</pre><script>\
             var c = 0; window.__n = function(){ return ++c; };\
             var s = document.createElement('script');\
             s.textContent = \"document.getElementById('o').textContent = String(window.__n());\";\
             document.body.appendChild(s);\
             document.body.appendChild(s);\
             </script></body>",
        );
        assert!(out2.contains(">1<"), "ran once, not twice: {out2}");
    }

    #[test]
    fn an_injected_inline_module_executes_and_fires_load() {
        // HTML's dynamically prepared module-script path is distinct from a
        // classic eval: it must parse/evaluate through the page module loader
        // before resolving the element's load event. Code-split custom-element
        // bundles (including Reddit's carousel) use this exact pattern.
        let (out, outcome) = page(
            r#"<body><pre id=o>before</pre><script>
            const s = document.createElement('script');
            s.type = 'module';
            s.textContent = "document.getElementById('o').textContent='module-ran';";
            s.addEventListener('load', () => document.body.setAttribute('data-module-load', 'yes'));
            s.addEventListener('error', () => document.body.setAttribute('data-module-load', 'no'));
            document.body.appendChild(s);
            </script></body>"#,
        );
        assert!(!outcome.panicked, "{outcome:?}");
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(out.contains(">module-ran<"), "{out}");
        assert!(out.contains(r#"data-module-load="yes""#), "{out}");
    }

    #[test]
    fn an_injected_module_upgrades_a_connected_custom_element() {
        // Code-split component bundles define their element after the server
        // rendered host is already in the document. The definition and the
        // connection reaction must both run on the module task, otherwise its
        // light-DOM fallback remains laid out as a stack of slides.
        let (out, outcome) = page(
            r#"<body><x-gallery></x-gallery><script>
            const s = document.createElement('script');
            s.type = 'module';
            s.textContent = `class XGallery extends HTMLElement {
              constructor() { super(); this.attachShadow({mode:'open'}); }
              connectedCallback() { this.shadowRoot.innerHTML = '<span>gallery-ready</span>'; }
            }
            customElements.define('x-gallery', XGallery);`;
            document.body.appendChild(s);
            </script></body>"#,
        );
        assert!(!outcome.panicked, "{outcome:?}");
        assert!(outcome.errors.is_empty(), "{outcome:?}");
        assert!(out.contains("gallery-ready"), "{out}");
    }

    #[test]
    fn parser_elements_report_connected_to_the_document() {
        let (out, outcome) = page(
            r#"<body><div id="probe"><span></span></div><script>
            const d = document.getElementById('probe');
            document.body.setAttribute('data-connected', [
              document.isConnected, document.documentElement.isConnected,
              document.body.isConnected, d.isConnected, d.firstElementChild.isConnected
            ].join(','));
            </script></body>"#,
        );
        assert!(outcome.errors.is_empty(), "{outcome:?}");
        assert!(
            out.contains(r#"data-connected="true,true,true,true,true""#),
            "{out}"
        );
    }

    #[test]
    fn node_is_connected_crosses_shadow_roots_but_not_detached_nodes() {
        let (out, outcome) = page(
            r#"<body><div id=host></div><script>
            const host = document.getElementById('host');
            const root = host.attachShadow({ mode: 'open' });
            const shadowChild = document.createElement('span');
            const detached = document.createElement('i');
            root.appendChild(shadowChild);
            document.body.setAttribute('data-connected', [
              host.isConnected, root.isConnected, shadowChild.isConnected,
              detached.isConnected
            ].join(','));
            </script></body>"#,
        );
        assert!(outcome.errors.is_empty(), "{outcome:?}");
        assert!(
            out.contains(r#"data-connected="true,true,true,false""#),
            "{out}"
        );
    }

    #[test]
    fn a_live_page_services_an_injected_module_after_first_paint() {
        let (handle, mut events) = live(
            r#"<body><pre id=o>before</pre><script>
            const s = document.createElement('script');
            s.type = 'module';
            s.textContent = "document.getElementById('o').textContent='module-ran';";
            document.body.appendChild(s);
            </script></body>"#,
        );
        let mut saw_first = false;
        let mut saw_module = false;
        for _ in 0..8 {
            match events.blocking_recv() {
                Some(PageEvt::Updated { html, .. }) => {
                    if html.contains(">before<") {
                        saw_first = true;
                    }
                    if html.contains(">module-ran<") {
                        saw_module = true;
                        break;
                    }
                }
                Some(PageEvt::Static { html, .. }) => {
                    if html.contains(">module-ran<") {
                        saw_module = true;
                        break;
                    }
                }
                Some(PageEvt::Settled) => {}
                other => panic!("unexpected page event: {other:?}"),
            }
        }
        drop(handle);
        assert!(
            saw_first,
            "resident actor should paint before async module work"
        );
        assert!(saw_module, "resident actor should service the module task");
    }

    #[test]
    fn a_live_dynamic_script_completes_before_window_load() {
        // HTML §4.12.1.1 marks a connected dynamically prepared script as
        // delaying the preparation-time document's load event until its
        // result is ready. The resident actor may paint the shell first, but
        // it must not dispatch window.load ahead of that script task.
        let (handle, mut events) = live(
            r#"<body><pre id=o>before</pre><button>keep live</button><script>
            window.__order = [];
            document.addEventListener('DOMContentLoaded', function () {
              var s = document.createElement('script');
              s.textContent = "window.__order.push('script'); document.getElementById('o').textContent=window.__order.join('|');";
              document.body.appendChild(s);
            });
            window.addEventListener('load', function () {
              window.__order.push('load');
              document.getElementById('o').textContent = window.__order.join('|');
            });
            </script></body>"#,
        );
        let mut ordered = false;
        for _ in 0..8 {
            match events.blocking_recv() {
                Some(PageEvt::Updated { html, outcome }) => {
                    assert!(outcome.errors.is_empty(), "{outcome:?}");
                    ordered |= html.contains(">script|load<");
                    if ordered {
                        break;
                    }
                }
                Some(PageEvt::Static { html, outcome }) => {
                    assert!(outcome.errors.is_empty(), "{outcome:?}");
                    ordered |= html.contains(">script|load<");
                    break;
                }
                Some(PageEvt::Settled) => {}
                other => panic!("unexpected live-page event: {other:?}"),
            }
        }
        drop(handle);
        assert!(
            ordered,
            "window.load must follow the dynamically prepared script"
        );
    }

    #[test]
    fn injected_classic_script_has_its_own_current_script_scope() {
        // A dynamically prepared classic script gets the same execution scope
        // as a parser-created one: itself synchronously and through its cleanup
        // microtask checkpoint, then null in a later timer task. The outer
        // script must not leak into the deferred injected-script execution.
        let (out, outcome) = page(
            r#"<body><script>
            var outerScript = document.currentScript;
            var s = document.createElement('script');
            s.textContent = `
                var injectedScript = document.currentScript;
                document.body.setAttribute('data-injected-sync',
                    injectedScript && injectedScript !== outerScript ? 'self' : 'wrong');
                Promise.resolve().then(function () {
                    document.body.setAttribute('data-injected-micro',
                        document.currentScript === injectedScript ? 'self' : 'wrong');
                    setTimeout(function () {
                        document.body.setAttribute('data-injected-timer',
                            document.currentScript === null ? 'null' : 'set');
                    }, 0);
                });
            `;
            document.body.appendChild(s);
            </script></body>"#,
        );
        assert!(!outcome.panicked, "{outcome:?}");
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(out.contains(r#"data-injected-sync="self""#), "{out}");
        assert!(out.contains(r#"data-injected-micro="self""#), "{out}");
        assert!(out.contains(r#"data-injected-timer="null""#), "{out}");
    }

    #[test]
    fn document_referrer_is_a_string_not_undefined() {
        // `document.referrer` must always be a STRING (HTML §3.1.5) — "" for a
        // direct navigation. Returning undefined broke connected-react-router:
        // its reducer seeds initial state from `document.referrer`, so an
        // undefined value made the slice reducer return undefined on INIT,
        // tripping Redux's "reducer returned undefined during initialization"
        // (#12) and aborting the whole store + render (crunchyroll's blank page).
        let (out, outcome) = page(
            "<body><pre id=o></pre><script>\
             var r = document.referrer;\
             document.getElementById('o').textContent = (typeof r) + ':' + JSON.stringify(r);\
             </script></body>",
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(
            out.contains("string:\"\""),
            "referrer is the empty string: {out}"
        );
    }

    #[test]
    fn element_traversal_accessors_live_on_the_spec_interfaces() {
        // The ParentNode (children/firstElementChild/lastElementChild/
        // childElementCount) and NonDocumentTypeChildNode (next/previous
        // ElementSibling) accessors must be OWN properties of the spec
        // interfaces — Document/DocumentFragment/Element/ShadowRoot and
        // Element/CharacterData — NOT Node. ShadyDOM (YouTube/Polymer shady
        // mode) wires its native shim by capturing
        // `Object.getOwnPropertyDescriptor(Element.prototype,"firstElementChild")`;
        // with the getter only on Node.prototype that capture silently no-ops,
        // a non-shadow element's shady `firstElementChild` returns undefined,
        // and the renderer-stamper re-creates instead of reusing → doubled
        // masthead buttons. The final `captured=span` line exercises the exact
        // capture-then-call pattern ShadyDOM uses.
        let html = r#"<body><pre id=o></pre><script>
            function own(p,n){ return !!Object.getOwnPropertyDescriptor(p,n); }
            var host=document.createElement('div');
            host.appendChild(document.createTextNode('t'));
            var span=document.createElement('span'); host.appendChild(span);
            var d=Object.getOwnPropertyDescriptor(Element.prototype,'firstElementChild');
            document.getElementById('o').textContent = [
                'E.fec='+own(Element.prototype,'firstElementChild'),
                'E.children='+own(Element.prototype,'children'),
                'E.nes='+own(Element.prototype,'nextElementSibling'),
                'Doc.fec='+own(Document.prototype,'firstElementChild'),
                'DF.fec='+own(DocumentFragment.prototype,'firstElementChild'),
                'SR.fec='+own(ShadowRoot.prototype,'firstElementChild'),
                'CD.nes='+own(CharacterData.prototype,'nextElementSibling'),
                'Node.fec='+own(Node.prototype,'firstElementChild'),
                'captured='+(d&&d.get? d.get.call(host).localName : 'NONE')
            ].join(' ');
            </script></body>"#;
        let (out, outcome) = page(html);
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        for expect in [
            "E.fec=true",
            "E.children=true",
            "E.nes=true",
            "Doc.fec=true",
            "DF.fec=true",
            "SR.fec=true",
            "CD.nes=true",
            "Node.fec=false",
            "captured=span",
        ] {
            assert!(out.contains(expect), "missing {expect:?} in: {out}");
        }
    }

    // ---- WebAssembly (js-api): Stage 1 — Module / validate / compile ----

    /// Compile WAT text into a `new Uint8Array([...])` JS literal, so a wasm
    /// fixture can be embedded directly in a test `<script>`. `wat` is a
    /// dev-dependency (pure-Rust); the runtime never accepts WAT text.
    fn wat_u8(wat: &str) -> String {
        let bytes = wat::parse_str(wat).expect("valid wat fixture");
        let nums: Vec<String> = bytes.iter().map(|b| b.to_string()).collect();
        format!("new Uint8Array([{}])", nums.join(","))
    }

    #[test]
    fn wasm_validate_accepts_valid_and_rejects_garbage() {
        let valid = wat_u8(r#"(module (func (export "f") (result i32) i32.const 7))"#);
        let html = format!(
            "<body><pre id=o></pre><script>\
             var ok = WebAssembly.validate({valid}) === true && \
                      WebAssembly.validate(new Uint8Array([0,1,2,3])) === false;\
             document.getElementById('o').textContent = ok ? 'VALIDOK' : 'BAD';\
             </script></body>"
        );
        let (out, outcome) = page(&html);
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(out.contains("VALIDOK"), "{out}");
    }

    #[test]
    fn wasm_module_introspects_imports_and_exports() {
        // A module with one import and three exports of different kinds.
        let bytes = wat_u8(
            r#"(module
                (import "env" "log" (func (param i32)))
                (global (export "g") i32 (i32.const 1))
                (func (export "add") (param i32 i32) (result i32)
                    local.get 0 local.get 1 i32.add)
                (memory (export "mem") 1))"#,
        );
        let html = format!(
            "<body><pre id=o></pre><script>\
             var m = new WebAssembly.Module({bytes});\
             var ex = WebAssembly.Module.exports(m);\
             var im = WebAssembly.Module.imports(m);\
             document.getElementById('o').textContent = JSON.stringify(ex) + '|' + JSON.stringify(im);\
             </script></body>"
        );
        let (out, outcome) = page(&html);
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(out.contains(r#"{"name":"g","kind":"global"}"#), "{out}");
        assert!(out.contains(r#"{"name":"add","kind":"function"}"#), "{out}");
        assert!(out.contains(r#"{"name":"mem","kind":"memory"}"#), "{out}");
        assert!(
            out.contains(r#"{"module":"env","name":"log","kind":"function"}"#),
            "{out}"
        );
    }

    #[test]
    fn wasm_module_metadata_preserves_declaration_order() {
        // WebAssembly JS API §4.2 walks the module's import and export sections in
        // declaration order. The underlying wasmi registries must not regroup by
        // external kind or expose hash-map iteration order.
        let bytes = wat_u8(
            r#"(module
                (import "env" "f" (func $f))
                (import "env" "g" (global $g i32))
                (import "env" "m" (memory $m 1))
                (import "env" "t" (table $t 1 externref))
                (export "m" (memory $m))
                (export "t" (table $t))
                (export "g" (global $g))
                (export "f" (func $f)))"#,
        );
        let html = format!(
            "<body><pre id=o></pre><script>\
             var m = new WebAssembly.Module({bytes});\
             var imports = WebAssembly.Module.imports(m).map(function(v){{return v.kind}}).join(',');\
             var exports = WebAssembly.Module.exports(m).map(function(v){{return v.kind}}).join(',');\
             document.getElementById('o').textContent = imports + '|' + exports;\
             </script></body>"
        );
        let (out, outcome) = page(&html);
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(
            out.contains("function,global,memory,table|memory,table,global,function"),
            "{out}"
        );
    }

    #[test]
    fn wasm_compile_throws_compileerror_on_bad_bytes() {
        let html = "<body><pre id=o></pre><script>\
             var r='none';\
             try { new WebAssembly.Module(new Uint8Array([0,1,2,3,4,5,6,7])); }\
             catch(e){ r = e.name + '|' + (e instanceof WebAssembly.CompileError) + '|' + (e instanceof Error); }\
             document.getElementById('o').textContent = r;\
             </script></body>";
        let (out, outcome) = page(html);
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(out.contains("CompileError|true|true"), "{out}");
    }

    #[test]
    fn wasm_compile_returns_a_promise_resolving_to_a_module() {
        let bytes = wat_u8(r#"(module (func (export "f")))"#);
        let html = format!(
            "<body><pre id=o>pending</pre><script>\
             var p = WebAssembly.compile({bytes});\
             var isP = p instanceof Promise;\
             p.then(function(m){{ document.getElementById('o').textContent = \
                 (isP && (m instanceof WebAssembly.Module)) ? 'COMPILED' : 'BAD'; }});\
             </script></body>"
        );
        let (out, outcome) = page(&html);
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(out.contains("COMPILED"), "{out}");
    }

    #[test]
    fn wasm_module_custom_sections_returns_exact_bytes() {
        // A module carrying a custom section named "greet" with payload "hello".
        let bytes = wat_u8(r#"(module (@custom "greet" "hello"))"#);
        let html = format!(
            "<body><pre id=o></pre><script>\
             var m = new WebAssembly.Module({bytes});\
             var secs = WebAssembly.Module.customSections(m, 'greet');\
             var none = WebAssembly.Module.customSections(m, 'absent');\
             var v = new Uint8Array(secs[0]);\
             document.getElementById('o').textContent = \
                 secs.length + '|' + none.length + '|' + Array.from(v).join(',');\
             </script></body>"
        );
        let (out, outcome) = page(&html);
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        // "hello" = [104,101,108,108,111]
        assert!(out.contains("1|0|104,101,108,108,111"), "{out}");
    }

    // ---- WebAssembly: Stage 2 — Instance / Exported Functions / conversions ----

    #[test]
    fn wasm_instance_calls_an_exported_add() {
        let bytes = wat_u8(
            r#"(module (func (export "add") (param i32 i32) (result i32)
                local.get 0 local.get 1 i32.add))"#,
        );
        let html = format!(
            "<body><pre id=o></pre><script>\
             var inst = new WebAssembly.Instance(new WebAssembly.Module({bytes}));\
             document.getElementById('o').textContent = 'r=' + inst.exports.add(20, 22);\
             </script></body>"
        );
        let (out, outcome) = page(&html);
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(out.contains("r=42"), "{out}");
    }

    #[test]
    fn wasm_reexported_function_preserves_wrapper_identity() {
        // WebAssembly JS API exported-function caching is by core function
        // address, including an imported function re-exported by another module.
        let source = wat_u8(
            r#"(module
                (func (export "f") (param i32) (result i32) local.get 0))"#,
        );
        let forwarding = wat_u8(
            r#"(module
                (import "env" "f" (func $f (param i32) (result i32)))
                (export "f" (func $f)))"#,
        );
        let html = format!(
            "<body><pre id=o></pre><script>\
             var first = new WebAssembly.Instance(new WebAssembly.Module({source}));\
             var second = new WebAssembly.Instance(new WebAssembly.Module({forwarding}),\
                 {{env:{{f:first.exports.f}}}});\
             document.getElementById('o').textContent =\
                 (first.exports.f === second.exports.f) + '|' + second.exports.f(9);\
             </script></body>"
        );
        let (out, outcome) = page(&html);
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(out.contains("true|9"), "{out}");
    }

    #[test]
    fn wasm_instantiate_resolves_module_and_instance() {
        let bytes = wat_u8(r#"(module (func (export "f") (result i32) i32.const 5))"#);
        let html = format!(
            "<body><pre id=o>pending</pre><script>\
             WebAssembly.instantiate({bytes}).then(function(res){{\
                document.getElementById('o').textContent = \
                    (res.module instanceof WebAssembly.Module) + ',' + \
                    (res.instance instanceof WebAssembly.Instance) + ',' + res.instance.exports.f();\
             }});\
             </script></body>"
        );
        let (out, outcome) = page(&html);
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(out.contains("true,true,5"), "{out}");
    }

    #[test]
    fn wasm_i64_round_trips_as_bigint() {
        // i64 params/results are BigInt at the JS boundary (js-api ToJSValue/
        // ToWebAssemblyValue). 2^53 + 1 would be lossy as a Number — BigInt is exact.
        let bytes = wat_u8(
            r#"(module (func (export "inc") (param i64) (result i64)
                local.get 0 i64.const 1 i64.add))"#,
        );
        let html = format!(
            "<body><pre id=o></pre><script>\
             var inst = new WebAssembly.Instance(new WebAssembly.Module({bytes}));\
             var r = inst.exports.inc(9007199254740992n);\
             document.getElementById('o').textContent = (typeof r) + ':' + r.toString();\
             </script></body>"
        );
        let (out, outcome) = page(&html);
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(out.contains("bigint:9007199254740993"), "{out}");
    }

    #[test]
    fn wasm_passing_a_non_bigint_for_i64_throws_typeerror() {
        let bytes = wat_u8(r#"(module (func (export "id") (param i64) (result i64) local.get 0))"#);
        let html = format!(
            "<body><pre id=o></pre><script>\
             var inst = new WebAssembly.Instance(new WebAssembly.Module({bytes}));\
             var r='none'; try {{ inst.exports.id(5); }} catch(e){{ r = e.constructor.name; }}\
             document.getElementById('o').textContent = r;\
             </script></body>"
        );
        let (out, outcome) = page(&html);
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(out.contains("TypeError"), "{out}");
    }

    #[test]
    fn wasm_multi_value_returns_an_array() {
        let bytes =
            wat_u8(r#"(module (func (export "pair") (result i32 i32) i32.const 1 i32.const 2))"#);
        let html = format!(
            "<body><pre id=o></pre><script>\
             var inst = new WebAssembly.Instance(new WebAssembly.Module({bytes}));\
             var r = inst.exports.pair();\
             document.getElementById('o').textContent = Array.isArray(r) + ':' + r.join(',');\
             </script></body>"
        );
        let (out, outcome) = page(&html);
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(out.contains("true:1,2"), "{out}");
    }

    #[test]
    fn wasm_f32_and_f64_round_trip_as_numbers() {
        let bytes = wat_u8(
            r#"(module
                (func (export "mul32") (param f32 f32) (result f32) local.get 0 local.get 1 f32.mul)
                (func (export "mul64") (param f64 f64) (result f64) local.get 0 local.get 1 f64.mul))"#,
        );
        let html = format!(
            "<body><pre id=o></pre><script>\
             var e = new WebAssembly.Instance(new WebAssembly.Module({bytes})).exports;\
             document.getElementById('o').textContent = 'a='+e.mul32(1.5,2)+' b='+e.mul64(0.1,0.2);\
             </script></body>"
        );
        let (out, outcome) = page(&html);
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(out.contains("a=3"), "{out}"); // 1.5*2 exact in f32
        assert!(out.contains("b=0.020000000"), "{out}"); // 0.1*0.2 = 0.020000000000000004 in f64
    }

    #[test]
    fn wasm_trap_throws_runtimeerror() {
        // i32.div_s by zero traps → RuntimeError (js-api error mapping).
        let bytes = wat_u8(
            r#"(module (func (export "boom") (result i32) i32.const 1 i32.const 0 i32.div_s))"#,
        );
        let html = format!(
            "<body><pre id=o></pre><script>\
             var inst = new WebAssembly.Instance(new WebAssembly.Module({bytes}));\
             var r='none'; try {{ inst.exports.boom(); }} catch(e){{ \
                r = (e instanceof WebAssembly.RuntimeError) + ':' + (e instanceof Error); }}\
             document.getElementById('o').textContent = r;\
             </script></body>"
        );
        let (out, outcome) = page(&html);
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(out.contains("true:true"), "{out}");
    }

